import React, { createContext, useContext, useState, useEffect } from 'react';

// Tipos de datos editables
export interface HomeContent {
  heroTitle: string;
  heroSubtitle: string;
  introTitle: string;
  introText: string;
}

export interface AboutContent {
  history: string;
  mission: string;
  vision: string;
}

export interface DonationItem {
  id: number;
  name: string;
  desc: string;
  priority: 'Alta' | 'Media' | 'Baja';
}

interface ContentContextType {
  homeContent: HomeContent;
  updateHomeContent: (data: HomeContent) => void;
  aboutContent: AboutContent;
  updateAboutContent: (data: AboutContent) => void;
  donationNeeds: DonationItem[];
  addDonationNeed: (item: Omit<DonationItem, 'id'>) => void;
  removeDonationNeed: (id: number) => void;
}

const defaultHome: HomeContent = {
  heroTitle: 'Transformamos una visita, una palabra y un abrazo en cuidado humano.',
  heroSubtitle: 'Somos Vida y Esperanza La Serena. Acompañamos con dignidad y compasión a pacientes y familias cuando más lo necesitan.',
  introTitle: 'Por qué existimos',
  introText: 'Porque creemos que la salud no es solo tratamiento, sino también presencia, acompañamiento y dignidad. Nuestra labor es puente entre el equipo clínico y la persona hospitalizada, entre el miedo y la confianza, entre la espera incierta y la palabra de aliento.'
};

const defaultAbout: AboutContent = {
  history: 'Nacimos como "Vida y Esperanza", uno de los cuerpos de voluntariado permanente del Hospital de La Serena. En ese primer momento, la idea fue simple: estar presentes junto al paciente, ofrecer compañía, entregar apoyos materiales cuando era necesario. Hoy formamos parte de los cinco cuerpos de voluntariado del hospital.',
  mission: 'Acompañar con dignidad, compasión y esperanza a pacientes y familias del Hospital de La Serena, aportando un vínculo humano que complemente la atención clínica.',
  vision: 'Ser reconocidas como un voluntariado hospitalario referente en la Región de Coquimbo, que inspire a nuevas voluntarias y contribuya a una cultura de humanización en salud.'
};

const defaultNeeds: DonationItem[] = [
  { id: 1, name: 'Pañales Adulto', desc: 'Tallas M y G', priority: 'Alta' },
  { id: 2, name: 'Útiles de Aseo', desc: 'Jabón, shampoo, cepillos', priority: 'Media' },
  { id: 3, name: 'Ropa de Abrigo', desc: 'Gorros, bufandas, chalecos', priority: 'Alta' },
  { id: 4, name: 'Libros y Revistas', desc: 'En buen estado para salas de espera', priority: 'Baja' },
];

const ContentContext = createContext<ContentContextType | undefined>(undefined);

export const ContentProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  // Inicializar estado desde localStorage o usar defaults
  const [homeContent, setHomeContent] = useState<HomeContent>(() => {
    const saved = localStorage.getItem('homeContent');
    return saved ? JSON.parse(saved) : defaultHome;
  });

  const [aboutContent, setAboutContent] = useState<AboutContent>(() => {
    const saved = localStorage.getItem('aboutContent');
    return saved ? JSON.parse(saved) : defaultAbout;
  });

  const [donationNeeds, setDonationNeeds] = useState<DonationItem[]>(() => {
    const saved = localStorage.getItem('donationNeeds');
    return saved ? JSON.parse(saved) : defaultNeeds;
  });

  // Guardar en localStorage cuando cambien
  useEffect(() => { localStorage.setItem('homeContent', JSON.stringify(homeContent)); }, [homeContent]);
  useEffect(() => { localStorage.setItem('aboutContent', JSON.stringify(aboutContent)); }, [aboutContent]);
  useEffect(() => { localStorage.setItem('donationNeeds', JSON.stringify(donationNeeds)); }, [donationNeeds]);

  const updateHomeContent = (data: HomeContent) => setHomeContent(data);
  const updateAboutContent = (data: AboutContent) => setAboutContent(data);

  const addDonationNeed = (item: Omit<DonationItem, 'id'>) => {
    const newItem = { ...item, id: Date.now() };
    setDonationNeeds([...donationNeeds, newItem]);
  };

  const removeDonationNeed = (id: number) => {
    setDonationNeeds(donationNeeds.filter(item => item.id !== id));
  };

  return (
    <ContentContext.Provider value={{
      homeContent,
      updateHomeContent,
      aboutContent,
      updateAboutContent,
      donationNeeds,
      addDonationNeed,
      removeDonationNeed
    }}>
      {children}
    </ContentContext.Provider>
  );
};

export const useContent = () => {
  const context = useContext(ContentContext);
  if (!context) throw new Error('useContent must be used within a ContentProvider');
  return context;
};

