import React, { createContext, useContext, useState, useEffect } from 'react';
import { Campaign, CampaignStatus } from '../types';

interface CRMContextType {
  campaigns: Campaign[];
  addCampaign: (campaign: Omit<Campaign, 'id'>) => void;
  updateCampaign: (id: number, campaign: Partial<Campaign>) => void;
  deleteCampaign: (id: number) => void;
  getCampaignStats: () => { active: number; planned: number; completed: number };
}

// Datos de ejemplo para poblar inicialmente
const defaultCampaigns: Campaign[] = [
  {
    id: 1,
    name: 'Campaña Invierno 2025',
    objective: 'Recolección de abrigos y frazadas',
    startDate: '2025-05-01',
    endDate: '2025-08-31',
    channel: 'Redes Sociales, Radio Local',
    targetAudience: 'Comunidad La Serena',
    status: CampaignStatus.PLANNED,
    budget: '$50.000',
    notes: 'Contactar a radio Montecarlo para entrevista.'
  },
  {
    id: 2,
    name: 'Reclutamiento Voluntarias',
    objective: 'Captar 10 nuevas voluntarias turno tarde',
    startDate: '2025-03-01',
    endDate: '2025-04-15',
    channel: 'Instagram, Facebook',
    targetAudience: 'Mujeres mayores de 30 años',
    status: CampaignStatus.ACTIVE,
    budget: '$20.000',
    notes: 'Diseñar flyers digitales.'
  }
];

const CRMContext = createContext<CRMContextType | undefined>(undefined);

export const CRMProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [campaigns, setCampaigns] = useState<Campaign[]>(() => {
    const saved = localStorage.getItem('crm_campaigns');
    return saved ? JSON.parse(saved) : defaultCampaigns;
  });

  useEffect(() => {
    localStorage.setItem('crm_campaigns', JSON.stringify(campaigns));
  }, [campaigns]);

  const addCampaign = (campaign: Omit<Campaign, 'id'>) => {
    const newCampaign = { ...campaign, id: Date.now() };
    setCampaigns([...campaigns, newCampaign]);
  };

  const updateCampaign = (id: number, updatedFields: Partial<Campaign>) => {
    setCampaigns(campaigns.map(c => (c.id === id ? { ...c, ...updatedFields } : c)));
  };

  const deleteCampaign = (id: number) => {
    setCampaigns(campaigns.filter(c => c.id !== id));
  };

  const getCampaignStats = () => {
    return {
      active: campaigns.filter(c => c.status === CampaignStatus.ACTIVE).length,
      planned: campaigns.filter(c => c.status === CampaignStatus.PLANNED).length,
      completed: campaigns.filter(c => c.status === CampaignStatus.COMPLETED).length,
    };
  };

  return (
    <CRMContext.Provider value={{ campaigns, addCampaign, updateCampaign, deleteCampaign, getCampaignStats }}>
      {children}
    </CRMContext.Provider>
  );
};

export const useCRM = () => {
  const context = useContext(CRMContext);
  if (!context) throw new Error('useCRM must be used within a CRMProvider');
  return context;
};

