import React, { createContext, useContext, useState, useEffect } from 'react';
import { User, UserRole } from '../types';

interface AuthContextType {
  user: User | null;
  isAuthenticated: boolean;
  login: (username: string, pass: string) => boolean;
  logout: () => void;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export const AuthProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [user, setUser] = useState<User | null>(() => {
    const saved = localStorage.getItem('auth_user');
    return saved ? JSON.parse(saved) : null;
  });

  useEffect(() => {
    if (user) {
      localStorage.setItem('auth_user', JSON.stringify(user));
    } else {
      localStorage.removeItem('auth_user');
    }
  }, [user]);

  const login = (username: string, pass: string) => {
    // Mock login logic
    if (username === 'admin' && pass === 'admin') {
      const mockUser: User = {
        id: 1,
        username: 'admin',
        name: 'Coordinadora General',
        role: UserRole.ADMIN
      };
      setUser(mockUser);
      return true;
    }
    return false;
  };

  const logout = () => {
    setUser(null);
  };

  return (
    <AuthContext.Provider value={{ user, isAuthenticated: !!user, login, logout }}>
      {children}
    </AuthContext.Provider>
  );
};

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (!context) throw new Error('useAuth must be used within an AuthProvider');
  return context;
};

import React, { createContext, useContext, useState, useEffect } from 'react';
import { Volunteer, VolunteerStatus } from '../types';

interface VolunteerContextType {
  volunteers: Volunteer[];
  addVolunteer: (vol: Omit<Volunteer, 'id' | 'hoursThisMonth' | 'joinDate' | 'status'>) => void;
  updateVolunteerStatus: (id: number, status: VolunteerStatus) => void;
  getVolunteerStats: () => { active: number; pending: number; totalHours: number };
}

const defaultVolunteers: Volunteer[] = [
  { id: 1, fullName: 'María González', email: 'maria@email.com', phone: '+56911111111', status: VolunteerStatus.ACTIVE, hoursThisMonth: 12, joinDate: '2020-03-15', availability: 'Mañanas' },
  { id: 2, fullName: 'Ana Pérez', email: 'ana@email.com', phone: '+56922222222', status: VolunteerStatus.ACTIVE, hoursThisMonth: 8, joinDate: '2021-06-10', availability: 'Tardes' },
  { id: 3, fullName: 'Carla Ruiz', email: 'carla@email.com', phone: '+56933333333', status: VolunteerStatus.PENDING, hoursThisMonth: 0, joinDate: '2025-02-20', availability: 'Fines de Semana', motivation: 'Quiero ayudar a la comunidad.' },
  { id: 4, fullName: 'Luisa Mora', email: 'luisa@email.com', phone: '+56944444444', status: VolunteerStatus.TRAINING, hoursThisMonth: 2, joinDate: '2025-01-15', availability: 'Mañanas' },
];

const VolunteerContext = createContext<VolunteerContextType | undefined>(undefined);

export const VolunteerProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [volunteers, setVolunteers] = useState<Volunteer[]>(() => {
    const saved = localStorage.getItem('volunteers_data');
    return saved ? JSON.parse(saved) : defaultVolunteers;
  });

  useEffect(() => {
    localStorage.setItem('volunteers_data', JSON.stringify(volunteers));
  }, [volunteers]);

  const addVolunteer = (volData: Omit<Volunteer, 'id' | 'hoursThisMonth' | 'joinDate' | 'status'>) => {
    const newVol: Volunteer = {
      ...volData,
      id: Date.now(),
      status: VolunteerStatus.PENDING, // Always starts as pending via web form
      hoursThisMonth: 0,
      joinDate: new Date().toISOString().split('T')[0]
    };
    setVolunteers([...volunteers, newVol]);
  };

  const updateVolunteerStatus = (id: number, status: VolunteerStatus) => {
    setVolunteers(volunteers.map(v => v.id === id ? { ...v, status } : v));
  };

  const getVolunteerStats = () => {
    return {
      active: volunteers.filter(v => v.status === VolunteerStatus.ACTIVE).length,
      pending: volunteers.filter(v => v.status === VolunteerStatus.PENDING).length,
      totalHours: volunteers.reduce((acc, curr) => acc + curr.hoursThisMonth, 0)
    };
  };

  return (
    <VolunteerContext.Provider value={{ volunteers, addVolunteer, updateVolunteerStatus, getVolunteerStats }}>
      {children}
    </VolunteerContext.Provider>
  );
};

export const useVolunteer = () => {
  const context = useContext(VolunteerContext);
  if (!context) throw new Error('useVolunteer must be used within a VolunteerProvider');
  return context;
};

