import React from 'react';

// Enums
export enum UserRole {
  SUPERADMIN = 'SUPERADMIN',
  COLLABORATOR = 'COLLABORATOR',
  VOLUNTEER = 'VOLUNTEER'
}

export enum DonationType {
  MONETARY = 'Monetario',
  SUPPLIES = 'Insumos',
  SERVICE = 'Servicio'
}

export enum VolunteerStatus {
  PENDING = 'Pendiente', 
  ACTIVE = 'Activo',
  TRAINING = 'En Formación',
  INACTIVE = 'Inactivo',
  ON_LEAVE = 'Licencia'
}

export enum CampaignStatus {
  DRAFT = 'Borrador',
  PLANNED = 'Planificada',
  ACTIVE = 'En Curso',
  COMPLETED = 'Finalizada',
  CANCELLED = 'Cancelada'
}

export type DonationCategory = 'Higiene' | 'Ropa' | 'Alimentos' | 'Médico' | 'Entretención' | 'Otro';
export type HospitalUnit = 'Pediatría' | 'Medicina Hombres' | 'Medicina Mujeres' | 'Urgencias' | 'Geriatría' | 'Oncología';
export type VolunteerGroup = 'Grupo A (Lunes)' | 'Grupo B (Martes)' | 'Grupo C (Miércoles)' | 'Grupo D (Jueves)' | 'Grupo E (Viernes)' | 'Fines de Semana';

// Interfaces
export interface User {
  id: number;
  username: string;
  role: UserRole;
  name: string;
  volunteerId?: number; // Links user to a volunteer profile
}

export interface Volunteer {
  id: number;
  fullName: string;
  email: string;
  phone: string;
  status: VolunteerStatus;
  hoursThisMonth: number;
  joinDate: string;
  availability?: string;
  motivation?: string;

  // New Fields for Coordination
  hospitalUnit?: HospitalUnit;
  group?: VolunteerGroup;
  skills?: string[]; // e.g. "Primeros Auxilios", "Contención"
  vaccinationStatus?: boolean;
}

export interface Shift {
  id: number;
  volunteerId: number;
  date: string; // YYYY-MM-DD
  startTime: string; // HH:MM
  endTime: string; // HH:MM
  hospitalUnit: HospitalUnit;
  status: 'Programado' | 'Completado' | 'Cancelado';
}

export interface Activity {
  id: number;
  name: string;
  date: string;
  beneficiaries: number;
  status: 'Programada' | 'En Curso' | 'Finalizada';
}

export interface Donation {
  id: number;
  donorName: string;
  type: DonationType;
  amountOrItem: string;
  date: string;
  status: 'Pendiente' | 'Recibido';
}

export interface DonationItem {
  id: number;
  name: string;
  desc: string;
  priority: 'Alta' | 'Media' | 'Baja';
  category: DonationCategory;
  targetAmount?: number;
  currentAmount: number;
  unit?: string;
}

export interface Campaign {
  id: number;
  name: string;
  objective: string;
  startDate: string;
  endDate: string;
  channel: string;
  targetAudience: string;
  status: CampaignStatus;
  budget?: string;
  notes?: string;
}

export interface NavItem {
  label: string;
  path: string;
  icon?: React.ReactNode;
}

import React, { createContext, useContext, useState, useEffect } from 'react';
import { User, UserRole } from '../types';

interface AuthContextType {
  user: User | null;
  isAuthenticated: boolean;
  login: (username: string, pass: string) => boolean;
  logout: () => void;
  hasPermission: (requiredRole: UserRole[]) => boolean;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export const AuthProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [user, setUser] = useState<User | null>(() => {
    const saved = localStorage.getItem('auth_user');
    return saved ? JSON.parse(saved) : null;
  });

  useEffect(() => {
    if (user) {
      localStorage.setItem('auth_user', JSON.stringify(user));
    } else {
      localStorage.removeItem('auth_user');
    }
  }, [user]);

  const login = (username: string, pass: string) => {
    // Mock Login with Roles

    // 1. Super Admin
    if (username === 'admin' && pass === 'admin') {
      setUser({
        id: 1,
        username: 'admin',
        name: 'Coordinadora General',
        role: UserRole.SUPERADMIN
      });
      return true;
    }

    // 2. Collaborator (e.g., Group Leader)
    if (username === 'colab' && pass === 'colab') {
      setUser({
        id: 2,
        username: 'colab',
        name: 'Jefa de Grupo',
        role: UserRole.COLLABORATOR
      });
      return true;
    }

    // 3. Volunteer (Regular User)
    if (username === 'vol' && pass === 'vol') {
      setUser({
        id: 3,
        username: 'vol',
        name: 'María González', // Matches a volunteer in the mock data
        role: UserRole.VOLUNTEER,
        volunteerId: 1
      });
      return true;
    }

    return false;
  };

  const logout = () => {
    setUser(null);
  };

  const hasPermission = (allowedRoles: UserRole[]) => {
    if (!user) return false;
    return allowedRoles.includes(user.role);
  };

  return (
    <AuthContext.Provider value={{ user, isAuthenticated: !!user, login, logout, hasPermission }}>
      {children}
    </AuthContext.Provider>
  );
};

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (!context) throw new Error('useAuth must be used within an AuthProvider');
  return context;
};

