import React from 'react';

// Enums
export enum UserRole {
  SUPERADMIN = 'SUPERADMIN',
  COLLABORATOR = 'COLLABORATOR',
  VOLUNTEER = 'VOLUNTEER'
}

export enum DonationType {
  MONETARY = 'Monetario',
  SUPPLIES = 'Insumos',
  SERVICE = 'Servicio'
}

export enum VolunteerStatus {
  PENDING = 'Pendiente', 
  ACTIVE = 'Activo',
  TRAINING = 'En Formación',
  INACTIVE = 'Inactivo',
  ON_LEAVE = 'Licencia'
}

export enum CampaignStatus {
  DRAFT = 'Borrador',
  PLANNED = 'Planificada',
  ACTIVE = 'En Curso',
  COMPLETED = 'Finalizada',
  CANCELLED = 'Cancelada'
}

export enum BlogPostStatus {
  DRAFT = 'Borrador',
  PUBLISHED = 'Publicado',
  ARCHIVED = 'Archivado'
}

export type DonationCategory = 'Higiene' | 'Ropa' | 'Alimentos' | 'Médico' | 'Entretención' | 'Otro';
export type HospitalUnit = 'Pediatría' | 'Medicina Hombres' | 'Medicina Mujeres' | 'Urgencias' | 'Geriatría' | 'Oncología';
export type VolunteerGroup = 'Grupo A (Lunes)' | 'Grupo B (Martes)' | 'Grupo C (Miércoles)' | 'Grupo D (Jueves)' | 'Grupo E (Viernes)' | 'Fines de Semana';

// Interfaces
export interface User {
  id: number;
  username: string;
  role: UserRole;
  name: string;
  volunteerId?: number; // Links user to a volunteer profile
}

export interface BlogPost {
  id: number;
  title: string;
  excerpt: string;
  content: string; // HTML or Markdown content
  coverImage: string;
  author: string;
  publishDate: string;
  status: BlogPostStatus;
  tags: string[];
}

export interface Volunteer {
  id: number;
  fullName: string;
  email: string;
  phone: string;
  status: VolunteerStatus;
  hoursThisMonth: number;
  joinDate: string;
  availability?: string;
  motivation?: string;

  // New Fields for Coordination
  hospitalUnit?: HospitalUnit;
  group?: VolunteerGroup;
  skills?: string[]; // e.g. "Primeros Auxilios", "Contención"
  vaccinationStatus?: boolean;
}

export interface Shift {
  id: number;
  volunteerId: number;
  date: string; // YYYY-MM-DD
  startTime: string; // HH:MM
  endTime: string; // HH:MM
  hospitalUnit: HospitalUnit;
  status: 'Programado' | 'Completado' | 'Cancelado';
}

export interface Activity {
  id: number;
  name: string;
  date: string;
  beneficiaries: number;
  status: 'Programada' | 'En Curso' | 'Finalizada';
}

export interface Donation {
  id: number;
  donorName: string;
  type: DonationType;
  amountOrItem: string;
  date: string;
  status: 'Pendiente' | 'Recibido';
}

export interface DonationItem {
  id: number;
  name: string;
  desc: string;
  priority: 'Alta' | 'Media' | 'Baja';
  category: DonationCategory;
  targetAmount?: number;
  currentAmount: number;
  unit?: string;
}

export interface Campaign {
  id: number;
  name: string;
  objective: string;
  startDate: string;
  endDate: string;
  channel: string;
  targetAudience: string;
  status: CampaignStatus;
  budget?: string;
  notes?: string;
}

export interface NavItem {
  label: string;
  path: string;
  icon?: React.ReactNode;
}

