const BlogContext = createContext<BlogContextType | undefined>(undefined);

export const BlogProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [posts, setPosts] = useState<BlogPost[]>(() => {
    const saved = localStorage.getItem('blog_posts');
    return saved ? JSON.parse(saved) : defaultPosts;
  });

  useEffect(() => {
    localStorage.setItem('blog_posts', JSON.stringify(posts));
  }, [posts]);

  const addPost = (post: Omit<BlogPost, 'id' | 'publishDate'>) => {
    const newPost: BlogPost = {
      ...post,
      id: Date.now(),
      publishDate: new Date().toISOString().split('T')[0]
    };
    setPosts([newPost, ...posts]);
  };

  const updatePost = (id: number, updatedFields: Partial<BlogPost>) => {
    setPosts(posts.map(p => (p.id === id ? { ...p, ...updatedFields } : p)));
  };

  const deletePost = (id: number) => {
    setPosts(posts.filter(p => p.id !== id));
  };

  const getPublishedPosts = () => {
    return posts.filter(p => p.status === BlogPostStatus.PUBLISHED).sort((a, b) => new Date(b.publishDate).getTime() - new Date(a.publishDate).getTime());
  };

  const getPostById = (id: number) => {
    return posts.find(p => p.id === id);
  };

  return (
    <BlogContext.Provider value={{ posts, addPost, updatePost, deletePost, getPublishedPosts, getPostById }}>
      {children}
    </BlogContext.Provider>
  );
};

export const useBlog = () => {
  const context = useContext(BlogContext);
  if (!context) throw new Error('useBlog must be used within a BlogProvider');
  return context;
};

import React, { useState } from 'react';
import { ArrowLeft, Plus, Edit2, Trash2, Save, X, Image as ImageIcon, Eye } from 'lucide-react';
import { useBlog } from '../../context/BlogContext';
import { BlogPost, BlogPostStatus } from '../../types';

interface AdminBlogProps {
  onBack: () => void;
}

export const AdminBlog: React.FC<AdminBlogProps> = ({ onBack }) => {
  const { posts, addPost, updatePost, deletePost } = useBlog();
  const [isEditing, setIsEditing] = useState<number | null>(null);
  const [isCreating, setIsCreating] = useState(false);

  const initialFormState = {
    title: '',
    excerpt: '',
    content: '',
    coverImage: '',
    author: '',
    status: BlogPostStatus.DRAFT,
    tags: '' // Handle as string for input
  };

  const [formData, setFormData] = useState(initialFormState);

  const handleCreate = () => {
    setFormData(initialFormState);
    setIsCreating(true);
    setIsEditing(null);
  };

  const handleEdit = (post: BlogPost) => {
    setFormData({
      ...post,
      tags: post.tags.join(', ')
    });
    setIsEditing(post.id);
    setIsCreating(false);
  };

  const handleCancel = () => {
    setIsCreating(false);
    setIsEditing(null);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const processedData = {
      ...formData,
      tags: formData.tags.split(',').map(t => t.trim()).filter(t => t !== '')
    };

    if (isEditing) {
      updatePost(isEditing, processedData);
    } else {
      addPost(processedData);
    }
    handleCancel();
  };

  const handleDelete = (id: number) => {
    if (window.confirm('¿Estás segura de eliminar esta publicación?')) {
      deletePost(id);
    }
  };

  const getStatusColor = (status: BlogPostStatus) => {
    switch (status) {
      case BlogPostStatus.PUBLISHED: return 'bg-emerald-100 text-emerald-800 border-emerald-200';
      case BlogPostStatus.DRAFT: return 'bg-yellow-100 text-yellow-800 border-yellow-200';
      case BlogPostStatus.ARCHIVED: return 'bg-gray-100 text-gray-800 border-gray-200';
      default: return 'bg-gray-50';
    }
  };

  return (
    <div className="min-h-screen bg-gray-50 p-6">
      <div className="max-w-6xl mx-auto">

        <div className="flex justify-between items-center mb-6">
          <div className="flex items-center gap-4">
            <button onClick={onBack} className="bg-white p-2 rounded-full shadow-sm hover:bg-gray-100 transition text-gray-600">
              <ArrowLeft size={20} />
            </button>
            <div>
              <h1 className="text-2xl font-bold text-gray-800">Gestión de Blog & Noticias</h1>
              <p className="text-gray-500 text-sm">Crea contenido para mantener informada a la comunidad.</p>
            </div>
          </div>
          <button 
            onClick={handleCreate}
            className="bg-emerald-600 hover:bg-emerald-700 text-white px-4 py-2 rounded-lg flex items-center gap-2 transition shadow-sm font-medium"
          >
            <Plus size={18} /> Nueva Entrada
          </button>
        </div>

        <div className="grid lg:grid-cols-3 gap-6">

          {/* List of Posts */}
          <div className={`lg:col-span-2 space-y-4 ${isCreating || isEditing ? 'hidden lg:block' : 'block'}`}>
            {posts.length === 0 ? (
                <div className="bg-white rounded-xl shadow-sm p-12 text-center text-gray-500">
                    <p>No hay publicaciones aún.</p>
                </div>
            ) : (
                posts.map(post => (
                <div key={post.id} className="bg-white rounded-xl shadow-sm border border-gray-100 overflow-hidden hover:shadow-md transition flex flex-col sm:flex-row">
                    <div className="sm:w-32 h-32 bg-gray-100 flex-shrink-0 relative">
                        {post.coverImage ? (
                            <img src={post.coverImage} alt={post.title} className="w-full h-full object-cover" />
                        ) : (
                            <div className="w-full h-full flex items-center justify-center text-gray-300"><ImageIcon size={24}/></div>
                        )}
                        <span className={`absolute top-2 left-2 text-[10px] uppercase font-bold px-2 py-0.5 rounded-md border shadow-sm ${getStatusColor(post.status)}`}>
                            {post.status}
                        </span>
                    </div>

                    <div className="p-4 flex-1 flex flex-col justify-between">
                        <div>
                            <h3 className="font-bold text-gray-900 line-clamp-1">{post.title}</h3>
                            <p className="text-gray-500 text-sm mt-1 line-clamp-2">{post.excerpt}</p>
                        </div>
                        <div className="flex justify-between items-end mt-3">
                            <div className="text-xs text-gray-400">
                                {post.author} • {new Date(post.publishDate).toLocaleDateString()}
                            </div>
                            <div className="flex gap-2">
                                <button onClick={() => handleEdit(post)} className="p-1.5 text-gray-500 hover:text-emerald-600 hover:bg-emerald-50 rounded-lg transition" title="Editar">
                                    <Edit2 size={16} />
                                </button>
                                <button onClick={() => handleDelete(post.id)} className="p-1.5 text-gray-500 hover:text-red-600 hover:bg-red-50 rounded-lg transition" title="Eliminar">
                                    <Trash2 size={16} />
                                </button>
                            </div>
                        </div>
                    </div>
                </div>
                ))
            )}
          </div>

          {/* Editor Form */}
          {(isCreating || isEditing) && (
            <div className="lg:col-span-1">
              <div className="bg-white rounded-xl shadow-lg border border-emerald-100 p-6 sticky top-6">
                <div className="flex justify-between items-center mb-6">
                  <h2 className="text-lg font-bold text-gray-800">
                    {isEditing ? 'Editar Publicación' : 'Crear Publicación'}
                  </h2>
                  <button onClick={handleCancel} className="text-gray-400 hover:text-gray-600">
                    <X size={20} />
                  </button>
                </div>

                <form onSubmit={handleSubmit} className="space-y-4">
                  <div>
                    <label className="block text-xs font-semibold text-gray-700 mb-1 uppercase">Título</label>
                    <input 
                      type="text" required value={formData.title} onChange={e => setFormData({...formData, title: e.target.value})}
                      className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-emerald-500 outline-none text-sm"
                    />
                  </div>

                  <div>
                    <label className="block text-xs font-semibold text-gray-700 mb-1 uppercase">Estado</label>
                    <select 
                      value={formData.status} onChange={e => setFormData({...formData, status: e.target.value as BlogPostStatus})}
                      className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-emerald-500 outline-none text-sm bg-white"
                    >
                        {Object.values(BlogPostStatus).map(s => <option key={s} value={s}>{s}</option>)}
                    </select>
                  </div>

                  <div>
                    <label className="block text-xs font-semibold text-gray-700 mb-1 uppercase">Resumen (Bajada)</label>
                    <textarea 
                      rows={2} required value={formData.excerpt} onChange={e => setFormData({...formData, excerpt: e.target.value})}
                      className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-emerald-500 outline-none text-sm"
                    />
                  </div>

                  <div>
                    <label className="block text-xs font-semibold text-gray-700 mb-1 uppercase">Contenido (HTML simple)</label>
                    <textarea 
                      rows={8} required value={formData.content} onChange={e => setFormData({...formData, content: e.target.value})}
                      className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-emerald-500 outline-none text-sm font-mono text-xs"
                      placeholder="<p>Escribe aquí tu contenido...</p>"
                    />
                    <p className="text-[10px] text-gray-400 mt-1">Acepta etiquetas HTML básicas como p, ul, li, strong.</p>
                  </div>

                  <div>
                    <label className="block text-xs font-semibold text-gray-700 mb-1 uppercase">URL Imagen Portada</label>
                    <input 
                      type="text" value={formData.coverImage} onChange={e => setFormData({...formData, coverImage: e.target.value})}
                      className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-emerald-500 outline-none text-sm"
                      placeholder="https://..."
                    />
                  </div>

                  <div>
                    <label className="block text-xs font-semibold text-gray-700 mb-1 uppercase">Autor</label>
                    <input 
                      type="text" value={formData.author} onChange={e => setFormData({...formData, author: e.target.value})}
                      className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-emerald-500 outline-none text-sm"
                    />
                  </div>

                  <div>
                    <label className="block text-xs font-semibold text-gray-700 mb-1 uppercase">Etiquetas (separadas por coma)</label>
                    <input 
                      type="text" value={formData.tags} onChange={e => setFormData({...formData, tags: e.target.value})}
                      className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-emerald-500 outline-none text-sm"
                      placeholder="Salud, Eventos, Urgente"
                    />
                  </div>

                  <div className="pt-2 flex gap-3">
                    <button type="submit" className="flex-1 bg-emerald-600 text-white py-2 rounded-lg hover:bg-emerald-700 font-bold text-sm flex justify-center items-center gap-2">
                        <Save size={16} /> Guardar
                    </button>
                  </div>
                </form>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

