import { AdminVolunteers } from './pages/admin/AdminVolunteers'; 
import { AdminBlog } from './pages/admin/AdminBlog';
import { VolunteerPortal } from './pages/portal/VolunteerPortal'; // New Page
import { LoginPage } from './pages/LoginPage';
import { ContentProvider } from './context/ContentContext';
import { CRMProvider } from './context/CRMContext';
import { VolunteerProvider } from './context/VolunteerContext';
import { BlogProvider } from './context/BlogContext';
import { AuthProvider, useAuth } from './context/AuthContext';
import { UserRole } from './types';

const AppRoutes: React.FC = () => {
  const [currentPage, setCurrentPage] = useState('home');
  const [selectedPostId, setSelectedPostId] = useState<number | null>(null);
  const { isAuthenticated, user } = useAuth();

  useEffect(() => {
    const handleHashChange = () => {
      const hash = window.location.hash.replace('#', '');
      if (hash) {
          // Check if hash has params (simple simulation)
          const parts = hash.split('?');
          setCurrentPage(parts[0]);
      } else {
        setCurrentPage('home');
      }
    };
    window.addEventListener('hashchange', handleHashChange);
    handleHashChange();
    return () => window.removeEventListener('hashchange', handleHashChange);
  }, []);

  const navigate = (page: string, params?: any) => {
    window.location.hash = page;
    setCurrentPage(page);
    if (params && params.id) {
        setSelectedPostId(params.id);
    }
    window.scrollTo(0, 0);
  };

  const isAdminRoute = currentPage.startsWith('admin') || currentPage === 'dashboard';
  const isPortalRoute = currentPage === 'portal';

  // Login Page Logic
  if (currentPage === 'login') {
      return <LoginPage onLoginSuccess={() => {
        // Redirect based on role
        // This logic sits inside LoginPage typically, but here we redirect to generic dash/portal
        // The AppRoutes re-render will catch the role below
        const currentUser = JSON.parse(localStorage.getItem('auth_user') || '{}');
        if (currentUser.role === UserRole.VOLUNTEER) {
             navigate('portal');
        } else {
             navigate('dashboard');
        }
      }} onNavigateHome={() => navigate('home')} />;
  }

  // Admin Routes Protection
  if (isAdminRoute) {
    if (!isAuthenticated) {
      return <LoginPage onLoginSuccess={() => navigate('dashboard')} onNavigateHome={() => navigate('home')} />;
    }
    // If a volunteer tries to access admin, redirect to portal
    if (user?.role === UserRole.VOLUNTEER) {
        navigate('portal');
        return null;
    }

    return (
      <AdminLayout currentPage={currentPage} onNavigate={navigate}>
        {currentPage === 'dashboard' && <Dashboard onNavigate={navigate} />}
        {currentPage === 'admin-volunteers' && <AdminVolunteers />}
        {currentPage === 'admin-campaigns' && <AdminCampaigns onBack={() => navigate('dashboard')} />}
        {currentPage === 'admin-donations' && <AdminDonations onBack={() => navigate('dashboard')} />}
        {currentPage === 'admin-blog' && <AdminBlog onBack={() => navigate('dashboard')} />}
        {currentPage === 'admin-home' && <AdminHome onBack={() => navigate('dashboard')} />}
        {currentPage === 'admin-about' && <AdminAbout onBack={() => navigate('dashboard')} />}
      </AdminLayout>
    );
  }

  // Volunteer Portal Protection
  if (isPortalRoute) {
     if (!isAuthenticated) return <LoginPage onLoginSuccess={() => navigate('portal')} onNavigateHome={() => navigate('home')} />;
     return <VolunteerPortal onNavigate={navigate} />;
  }

  // Public Layout
  return (
    <Layout currentPage={currentPage} onNavigate={navigate}>
      {currentPage === 'home' && <HomePage onNavigate={navigate} />}
      {currentPage === 'about' && <AboutPage />}
      {currentPage === 'blog' && <BlogPage onNavigatePost={(id) => navigate('blog-post', { id })} />}
      {currentPage === 'blog-post' && selectedPostId && <BlogPostPage postId={selectedPostId} onBack={() => navigate('blog')} />}
      {currentPage === 'volunteer' && <VolunteerPage />}
      {currentPage === 'donate' && <DonationPage />}
    </Layout>
  );
};

const App: React.FC = () => {
  return (
    <AuthProvider>
      <ContentProvider>
        <CRMProvider>
          <VolunteerProvider>
            <BlogProvider>
                <AppRoutes />
            </BlogProvider>
          </VolunteerProvider>
        </CRMProvider>
      </ContentProvider>
    </AuthProvider>
  );
};

