import React, { useState, useEffect } from 'react';
import { ArrowRight, Heart, Clock, Smile, Users, BookOpen, Hand, Star, Sun, ChevronLeft, ChevronRight } from 'lucide-react';
import { useContent } from '../context/ContentContext';
import { useBlog } from '../context/BlogContext';

interface HomePageProps {
  onNavigate: (page: string, params?: any) => void;
}

const ICON_MAP = {
  Heart: <Heart className="text-emerald-600" size={28} />,
  Users: <Users className="text-emerald-600" size={28} />,
  Smile: <Smile className="text-emerald-600" size={28} />,
  Hand: <Hand className="text-emerald-600" size={28} />,
  Star: <Star className="text-emerald-600" size={28} />,
  Sun: <Sun className="text-emerald-600" size={28} />
};

export const HomePage: React.FC<HomePageProps> = ({ onNavigate }) => {
  const { homeContent, services, heroSlides } = useContent();
  const { getPublishedPosts } = useBlog();
  const [currentSlide, setCurrentSlide] = useState(0);

  const recentPosts = getPublishedPosts().slice(0, 5);
  const activeSlides = heroSlides.filter(s => s.isActive);

  // Auto-play Slider logic
  useEffect(() => {
    if (activeSlides.length <= 1) return;
    const interval = setInterval(() => {
      setCurrentSlide((prev) => (prev + 1) % activeSlides.length);
    }, 6000); // Change every 6 seconds
    return () => clearInterval(interval);
  }, [activeSlides.length]);

  const handlePostClick = (id: number) => {
    onNavigate('blog-post', { id });
  };

  const nextSlide = () => {
    setCurrentSlide((prev) => (prev + 1) % activeSlides.length);
  };

  const prevSlide = () => {
    setCurrentSlide((prev) => (prev - 1 + activeSlides.length) % activeSlides.length);
  };

  return (
    <div className="flex flex-col">
      {/* Dynamic Hero Slider */}
      <div className="relative h-screen min-h-[600px] w-full overflow-hidden bg-gray-900">

        {activeSlides.map((slide, index) => (
            <div 
                key={slide.id}
                className={`absolute inset-0 transition-opacity duration-1000 ease-in-out ${index === currentSlide ? 'opacity-100 z-10' : 'opacity-0 z-0'}`}
            >
                {/* Background Media */}
                <div className="absolute inset-0">
                    {slide.mediaType === 'video' ? (
                         <video 
                            className="w-full h-full object-cover"
                            autoPlay 
                            loop 
                            muted 
                            playsInline
                            poster="https://via.placeholder.com/1920x1080/000000/ffffff?text=Loading+Video"
                         >
                            <source src={slide.mediaUrl} type="video/mp4" />
                        </video>
                    ) : (
                        <img
                            src={slide.mediaUrl}
                            alt={slide.title}
                            className="w-full h-full object-cover"
                        />
                    )}
                    {/* Overlay Gradient */}
                    <div className="absolute inset-0 bg-gradient-to-r from-emerald-900/90 via-emerald-900/60 to-black/30" />
                </div>

                {/* Content */}
                <div className="relative z-20 container mx-auto px-4 sm:px-6 lg:px-8 h-full flex flex-col justify-center">
                    <div className="max-w-3xl animate-fade-in-up">
                        <h1 className="text-4xl md:text-6xl font-extrabold tracking-tight text-white mb-6 leading-tight drop-shadow-md">
                            {slide.title}
                        </h1>
                        <p className="text-lg md:text-2xl text-emerald-50 mb-8 max-w-xl font-light drop-shadow">
                            {slide.subtitle}
                        </p>

                        <div className="flex flex-col sm:flex-row gap-4">
                            {slide.buttons.filter(btn => btn.label).map((btn, btnIdx) => (
                                <button
                                    key={btnIdx}
                                    onClick={() => onNavigate(btn.link)}
                                    className={`inline-flex items-center justify-center px-8 py-3.5 text-base font-bold rounded-full transition-all transform hover:scale-105 shadow-lg ${
                                        btn.style === 'primary' 
                                        ? 'bg-emerald-500 hover:bg-emerald-400 text-white border-2 border-emerald-500' 
                                        : 'bg-transparent hover:bg-white/10 text-white border-2 border-white backdrop-blur-sm'
                                    }`}
                                >
                                    {btn.label}
                                    {btn.style === 'primary' && <ArrowRight className="ml-2 -mr-1 h-5 w-5" />}
                                </button>
                            ))}
                        </div>
                    </div>
                </div>
            </div>
        ))}

        {/* Slider Controls (Only if > 1 slide) */}
        {activeSlides.length > 1 && (
            <>
                <button onClick={prevSlide} className="absolute left-4 top-1/2 -translate-y-1/2 z-30 p-2 text-white/50 hover:text-white bg-black/20 hover:bg-black/40 rounded-full backdrop-blur-sm transition">
                    <ChevronLeft size={32} />
                </button>
                <button onClick={nextSlide} className="absolute right-4 top-1/2 -translate-y-1/2 z-30 p-2 text-white/50 hover:text-white bg-black/20 hover:bg-black/40 rounded-full backdrop-blur-sm transition">
                    <ChevronRight size={32} />
                </button>

                {/* Dots */}
                <div className="absolute bottom-8 left-1/2 -translate-x-1/2 z-30 flex gap-2">
                    {activeSlides.map((_, idx) => (
                        <button
                            key={idx}
                            onClick={() => setCurrentSlide(idx)}
                            className={`w-3 h-3 rounded-full transition-all ${idx === currentSlide ? 'bg-emerald-500 w-8' : 'bg-white/50 hover:bg-white'}`}
                        />
                    ))}
                </div>
            </>
        )}
      </div>

      {/* Intro Section */}
      <section className="py-16 bg-white">
        <div className="container mx-auto px-4 sm:px-6 lg:px-8 text-center max-w-3xl">
          <h2 className="text-3xl font-bold text-gray-900 mb-6">{homeContent.introTitle}</h2>
          <p className="text-lg text-gray-600 leading-relaxed mb-8">
            {homeContent.introText}
          </p>
          <div className="h-1 w-20 bg-emerald-500 mx-auto rounded-full"></div>
        </div>
      </section>

      {/* Latest News Carousel */}
      {recentPosts.length > 0 && (
        <section className="py-12 bg-white border-t border-gray-100">
          <div className="container mx-auto px-4 sm:px-6 lg:px-8">
            <div className="flex justify-between items-center mb-8">
                <h2 className="text-2xl font-bold text-gray-900 flex items-center gap-2">
                    <BookOpen className="text-emerald-600" size={24}/> Actualidad y Noticias
                </h2>
                <button onClick={() => onNavigate('blog')} className="text-emerald-600 hover:text-emerald-800 text-sm font-semibold flex items-center gap-1">
                    Ver todo <ArrowRight size={16}/>
                </button>
            </div>

            <div className="flex overflow-x-auto gap-6 pb-6 snap-x">
                {recentPosts.map(post => (
                    <div 
                        key={post.id} 
                        className="min-w-[300px] md:min-w-[350px] bg-white rounded-xl shadow-md border border-gray-100 overflow-hidden snap-start cursor-pointer hover:shadow-lg transition-all"
                        onClick={() => handlePostClick(post.id)}
                    >
                        <div className="h-40 relative">
                             <img src={post.coverImage} alt={post.title} className="w-full h-full object-cover"/>
                             <div className="absolute inset-0 bg-gradient-to-t from-black/60 to-transparent" />
                             <span className="absolute bottom-2 left-3 text-white text-xs font-bold">{new Date(post.publishDate).toLocaleDateString()}</span>
                        </div>
                        <div className="p-4">
                            <h3 className="font-bold text-gray-800 mb-2 line-clamp-2 leading-tight">{post.title}</h3>
                            <p className="text-gray-500 text-sm line-clamp-2">{post.excerpt}</p>
                        </div>
                    </div>
                ))}
            </div>
          </div>
        </section>
      )}

      {/* What We Do Cards (Dynamic Services) */}
      <section className="py-16 bg-gray-50">
        <div className="container mx-auto px-4 sm:px-6 lg:px-8">
          <div className="text-center mb-12">
            <h2 className="text-3xl font-bold text-gray-900">Nuestras Áreas de Acción</h2>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
            {services.map(service => (
              <div key={service.id} className="bg-white rounded-xl shadow-md p-8 hover:shadow-lg transition-shadow border-t-4 border-emerald-500">
                <div className="w-12 h-12 bg-emerald-100 rounded-lg flex items-center justify-center mb-6">
                  {ICON_MAP[service.icon] || <Heart className="text-emerald-600" size={28} />}
                </div>
                <h3 className="text-xl font-bold text-gray-900 mb-3">{service.title}</h3>
                <p className="text-gray-600">
                  {service.description}
                </p>
              </div>
            ))}
            {services.length === 0 && (
                <div className="col-span-3 text-center text-gray-400 italic">
                    No hay áreas de acción configuradas.
                </div>
            )}
          </div>
        </div>
      </section>

      {/* Impact Stats */}
      <section className="py-16 bg-emerald-900 text-white">
        <div className="container mx-auto px-4 sm:px-6 lg:px-8">
          <div className="grid grid-cols-2 md:grid-cols-4 gap-8 text-center">
            <div>
              <div className="text-4xl font-bold text-emerald-300 mb-2">17+</div>
              <div className="text-emerald-100 text-sm font-medium">Años de Servicio</div>
            </div>
            <div>
              <div className="text-4xl font-bold text-emerald-300 mb-2">70+</div>
              <div className="text-emerald-100 text-sm font-medium">Voluntarias Activas</div>
            </div>
            <div>
              <div className="text-4xl font-bold text-emerald-300 mb-2">1000s</div>
              <div className="text-emerald-100 text-sm font-medium">Pacientes Acompañados</div>
            </div>
            <div>
              <div className="text-4xl font-bold text-emerald-300 mb-2">100%</div>
              <div className="text-emerald-100 text-sm font-medium">Compromiso</div>
            </div>
          </div>
        </div>
      </section>

      {/* Testimonial */}
      <section className="py-20 bg-white">
        <div className="container mx-auto px-4 sm:px-6 lg:px-8">
          <div className="max-w-4xl mx-auto bg-emerald-50 rounded-2xl p-10 relative">
            <div className="text-6xl text-emerald-200 absolute top-4 left-6">"</div>
            <blockquote className="text-center relative z-10">
              <p className="text-xl md:text-2xl text-emerald-900 font-medium italic leading-relaxed mb-6">
                Cuando entré al hospital sola desde otro pueblo, encontré a las voluntarias que me esperaron, 
                me contaron qué pasaba y me acompañaron hasta mi hijo. Fue un bálsamo impensado.
