// Helper to calculate lighter/darker shades (simple approximate version)
const adjustBrightness = (hex: string, percent: number) => {
    let r = parseInt(hex.substring(1, 3), 16);
    let g = parseInt(hex.substring(3, 5), 16);
    let b = parseInt(hex.substring(5, 7), 16);

    r = Math.round(r * (1 + percent));
    g = Math.round(g * (1 + percent));
    b = Math.round(b * (1 + percent));

    r = (r < 255) ? r : 255;
    g = (g < 255) ? g : 255;
    b = (b < 255) ? b : 255;

    r = (r > 0) ? r : 0;
    g = (g > 0) ? g : 0;
    b = (b > 0) ? b : 0;

    const RR = ((r.toString(16).length === 1) ? "0" + r.toString(16) : r.toString(16));
    const GG = ((g.toString(16).length === 1) ? "0" + g.toString(16) : g.toString(16));
    const BB = ((b.toString(16).length === 1) ? "0" + b.toString(16) : b.toString(16));

    return "#" + RR + GG + BB;
}

const ContentContext = createContext<ContentContextType | undefined>(undefined);

export const ContentProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  // --- STATE ---
  const [branding, setBranding] = useState<BrandingConfig>(() => {
      const saved = localStorage.getItem('branding_config');
      return saved ? JSON.parse(saved) : defaultBranding;
  });

  const [homeContent, setHomeContent] = useState<HomeContent>(() => {
    const saved = localStorage.getItem('homeContent');
    return saved ? JSON.parse(saved) : defaultHome;
  });

  const [heroSlides, setHeroSlides] = useState<HeroSlide[]>(() => {
    const saved = localStorage.getItem('hero_slides');
    return saved ? JSON.parse(saved) : defaultSlides;
  });

  const [aboutContent, setAboutContent] = useState<AboutContent>(() => {
    const saved = localStorage.getItem('aboutContent');
    return saved ? JSON.parse(saved) : defaultAbout;
  });

  const [donationNeeds, setDonationNeeds] = useState<DonationItem[]>(() => {
    const saved = localStorage.getItem('donationNeeds');
    return saved ? JSON.parse(saved) : defaultNeeds;
  });

  const [services, setServices] = useState<ServiceItem[]>(() => {
    const saved = localStorage.getItem('content_services');
    return saved ? JSON.parse(saved) : defaultServices;
  });

  const [customPages, setCustomPages] = useState<CustomPage[]>(() => {
    const saved = localStorage.getItem('content_custom_pages');
    return saved ? JSON.parse(saved) : [];
  });

  // --- PERSISTENCE ---
  useEffect(() => { localStorage.setItem('branding_config', JSON.stringify(branding)); }, [branding]);
  useEffect(() => { localStorage.setItem('homeContent', JSON.stringify(homeContent)); }, [homeContent]);
  useEffect(() => { localStorage.setItem('hero_slides', JSON.stringify(heroSlides)); }, [heroSlides]);
  useEffect(() => { localStorage.setItem('aboutContent', JSON.stringify(aboutContent)); }, [aboutContent]);
  useEffect(() => { localStorage.setItem('donationNeeds', JSON.stringify(donationNeeds)); }, [donationNeeds]);
  useEffect(() => { localStorage.setItem('content_services', JSON.stringify(services)); }, [services]);
  useEffect(() => { localStorage.setItem('content_custom_pages', JSON.stringify(customPages)); }, [customPages]);

  // --- BRANDING EFFECT ---
  useEffect(() => {
    const root = document.documentElement;
    const base = branding.primaryColor;

    // Set Font
    root.style.setProperty('--font-primary', branding.fontFamily);

    // Generate Palette (Approximate logic for client-side generation without heavy libs)
    // 50 (Lightest) -> 500 (Base) -> 900 (Darkest)
    root.style.setProperty('--brand-50', adjustBrightness(base, 0.9));
    root.style.setProperty('--brand-100', adjustBrightness(base, 0.7));
    root.style.setProperty('--brand-200', adjustBrightness(base, 0.5));
    root.style.setProperty('--brand-300', adjustBrightness(base, 0.3));
    root.style.setProperty('--brand-400', adjustBrightness(base, 0.15));
    root.style.setProperty('--brand-500', base);
    root.style.setProperty('--brand-600', adjustBrightness(base, -0.1));
    root.style.setProperty('--brand-700', adjustBrightness(base, -0.2));
    root.style.setProperty('--brand-800', adjustBrightness(base, -0.3));
    root.style.setProperty('--brand-900', adjustBrightness(base, -0.45));
    root.style.setProperty('--brand-950', adjustBrightness(base, -0.6));

  }, [branding]);


  // --- ACTIONS ---
  const updateBranding = (config: BrandingConfig) => setBranding(config);

  const updateHomeContent = (data: HomeContent) => setHomeContent(data);

  // Hero Slides
  const addHeroSlide = (slide: Omit<HeroSlide, 'id'>) => {
    setHeroSlides([...heroSlides, { ...slide, id: Date.now() }]);
  };
  const updateHeroSlide = (id: number, slide: Partial<HeroSlide>) => {
    setHeroSlides(heroSlides.map(s => s.id === id ? { ...s, ...slide } : s));
  };
  const deleteHeroSlide = (id: number) => {
    setHeroSlides(heroSlides.filter(s => s.id !== id));
  };

  const updateAboutContent = (data: AboutContent) => setAboutContent(data);

  // Donations
  const addDonationNeed = (item: Omit<DonationItem, 'id' | 'currentAmount'>) => {
    const newItem: DonationItem = { ...item, id: Date.now(), currentAmount: 0 };
    setDonationNeeds([...donationNeeds, newItem]);
  };
  const updateDonationProgress = (id: number, amountToAdd: number) => {
    setDonationNeeds(prev => prev.map(item => {
      if (item.id === id) {
        const newAmount = Math.max(0, item.currentAmount + amountToAdd);
        return { ...item, currentAmount: newAmount };
      }
      return item;
    }));
  };
  const removeDonationNeed = (id: number) => {
    setDonationNeeds(donationNeeds.filter(item => item.id !== id));
  };

  // Services
  const addService = (item: Omit<ServiceItem, 'id'>) => {
    setServices([...services, { ...item, id: Date.now() }]);
  };
  const updateService = (id: number, item: Partial<ServiceItem>) => {
    setServices(services.map(s => s.id === id ? { ...s, ...item } : s));
  };
  const deleteService = (id: number) => {
    setServices(services.filter(s => s.id !== id));
  };

  // Custom Pages
  const addCustomPage = (page: Omit<CustomPage, 'id' | 'lastModified'>) => {
    setCustomPages([...customPages, { ...page, id: Date.now(), lastModified: new Date().toISOString() }]);
  };
  const updateCustomPage = (id: number, page: Partial<CustomPage>) => {
    setCustomPages(customPages.map(p => p.id === id ? { ...p, ...page, lastModified: new Date().toISOString() } : p));
  };
  const deleteCustomPage = (id: number) => {
    setCustomPages(customPages.filter(p => p.id !== id));
  };
  const getPageBySlug = (slug: string) => customPages.find(p => p.slug === slug && p.isVisible);

  return (
    <ContentContext.Provider value={{
      homeContent, updateHomeContent,
      branding, updateBranding,
      heroSlides, addHeroSlide, updateHeroSlide, deleteHeroSlide,
      aboutContent, updateAboutContent,
      donationNeeds, addDonationNeed, updateDonationProgress, removeDonationNeed,
      services, addService, updateService, deleteService,
      customPages, addCustomPage, updateCustomPage, deleteCustomPage, getPageBySlug
    }}>
      {children}
    </ContentContext.Provider>
  );
};

export const useContent = () => {
  const context = useContext(ContentContext);
  if (!context) throw new Error('useContent must be used within a ContentProvider');
  return context;
};

