export const VolunteerProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [volunteers, setVolunteers] = useState<Volunteer[]>(() => {
    const saved = localStorage.getItem('volunteers_data');
    return saved ? JSON.parse(saved) : defaultVolunteers;
  });

  const [shifts, setShifts] = useState<Shift[]>(() => {
    const saved = localStorage.getItem('volunteers_shifts');
    return saved ? JSON.parse(saved) : defaultShifts;
  });

  useEffect(() => {
    localStorage.setItem('volunteers_data', JSON.stringify(volunteers));
  }, [volunteers]);

  useEffect(() => {
    localStorage.setItem('volunteers_shifts', JSON.stringify(shifts));
  }, [shifts]);

  const addVolunteer = (volData: Omit<Volunteer, 'id' | 'hoursThisMonth' | 'joinDate' | 'status'>) => {
    const newVol: Volunteer = {
      ...volData,
      id: Date.now(),
      status: VolunteerStatus.PENDING,
      hoursThisMonth: 0,
      joinDate: new Date().toISOString().split('T')[0]
    };
    setVolunteers([...volunteers, newVol]);
  };

  const updateVolunteerStatus = (id: number, status: VolunteerStatus) => {
    setVolunteers(volunteers.map(v => v.id === id ? { ...v, status } : v));
  };

  const updateVolunteerDetails = (id: number, details: Partial<Volunteer>) => {
    setVolunteers(volunteers.map(v => v.id === id ? { ...v, ...details } : v));
  };

  const getVolunteerStats = () => {
    return {
      active: volunteers.filter(v => v.status === VolunteerStatus.ACTIVE).length,
      pending: volunteers.filter(v => v.status === VolunteerStatus.PENDING).length,
      totalHours: volunteers.reduce((acc, curr) => acc + curr.hoursThisMonth, 0)
    };
  };

  const addShift = (shift: Omit<Shift, 'id'>) => {
    const newShift = { ...shift, id: Date.now() };
    setShifts([...shifts, newShift]);
  };

  const getShiftsByVolunteer = (volunteerId: number) => {
    return shifts.filter(s => s.volunteerId === volunteerId).sort((a,b) => a.date.localeCompare(b.date));
  };

  return (
    <VolunteerContext.Provider value={{ 
      volunteers, 
      shifts,
      addVolunteer, 
      updateVolunteerStatus, 
      updateVolunteerDetails,
      getVolunteerStats,
      addShift,
      getShiftsByVolunteer
    }}>
      {children}
    </VolunteerContext.Provider>
  );
};

export const useVolunteer = () => {
  const context = useContext(VolunteerContext);
  if (!context) throw new Error('useVolunteer must be used within a VolunteerProvider');
  return context;
};

