                                {vol.status}
                            </span>
                        </td>
                        <td className="px-6 py-4 text-gray-600">
                            {vol.availability || 'No especificada'}
                        </td>
                        <td className="px-6 py-4 text-right space-x-2">
                             <button 
                                onClick={() => handleEditClick(vol)}
                                className="text-emerald-600 hover:text-emerald-800 text-xs font-medium border border-emerald-200 px-3 py-1 rounded hover:bg-emerald-50 transition flex items-center gap-1 inline-flex"
                             >
                                <Edit size={12} /> Gestionar Ficha
                            </button>
                        </td>
                        </tr>
                    ))}
                    </tbody>
                </table>
                </div>
            </div>
        </>
      )}

      {/* Volunteer Edit Modal */}
      {editingVolunteer && (
        <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
            <div className="bg-white rounded-xl shadow-2xl w-full max-w-2xl max-h-[90vh] overflow-y-auto">
                <form onSubmit={handleSaveVolunteer}>
                    {/* Modal Header */}
                    <div className="bg-emerald-900 text-white p-6 sticky top-0 z-10 flex justify-between items-center">
                        <div className="flex items-center gap-4">
                            <div className="w-12 h-12 bg-white/20 rounded-full flex items-center justify-center text-xl font-bold">
                                {editingVolunteer.fullName.charAt(0)}
                            </div>
                            <div>
                                <h2 className="text-xl font-bold">Ficha de Voluntaria</h2>
                                <p className="text-emerald-200 text-sm">Editando perfil y asignaciones</p>
                            </div>
                        </div>
                        <button type="button" onClick={() => setEditingVolunteer(null)} className="text-emerald-200 hover:text-white transition">
                            <X size={24} />
                        </button>
                    </div>

                    {/* Modal Body */}
                    <div className="p-6 space-y-6">

                        {/* Status Section */}
                        <div className="bg-gray-50 p-4 rounded-lg border border-gray-200">
                            <label className="block text-xs font-bold text-gray-500 uppercase mb-2">Estado Actual</label>
                            <div className="flex flex-wrap gap-2">
                                {Object.values(VolunteerStatus).map(status => (
                                    <button
                                        key={status}
                                        type="button"
                                        onClick={() => setEditingVolunteer({...editingVolunteer, status: status})}
                                        className={`px-3 py-1.5 rounded-lg text-sm font-medium border transition ${
                                            editingVolunteer.status === status 
                                            ? 'bg-emerald-600 text-white border-emerald-600 shadow-sm' 
                                            : 'bg-white text-gray-600 border-gray-300 hover:bg-gray-100'
                                        }`}
                                    >
                                        {status}
                                    </button>
                                ))}
                            </div>
                        </div>

                        {/* Coordination Info */}
                        <div className="grid md:grid-cols-2 gap-6">
                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-1">Unidad Hospitalaria</label>
                                <select 
                                    className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-emerald-500 outline-none bg-white"
                                    value={editingVolunteer.hospitalUnit || ''}
                                    onChange={e => setEditingVolunteer({...editingVolunteer, hospitalUnit: e.target.value as HospitalUnit})}
                                >
                                    <option value="">-- Sin Asignar --</option>
                                    <option value="Pediatría">Pediatría</option>
                                    <option value="Medicina Hombres">Medicina Hombres</option>
                                    <option value="Medicina Mujeres">Medicina Mujeres</option>
                                    <option value="Urgencias">Urgencias</option>
                                    <option value="Geriatría">Geriatría</option>
                                    <option value="Oncología">Oncología</option>
                                </select>
                            </div>
                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-1">Grupo / Turno</label>
                                <select 
                                    className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-emerald-500 outline-none bg-white"
                                    value={editingVolunteer.group || ''}
                                    onChange={e => setEditingVolunteer({...editingVolunteer, group: e.target.value as VolunteerGroup})}
                                >
                                    <option value="">-- Sin Asignar --</option>
                                    <option value="Grupo A (Lunes)">Grupo A (Lunes)</option>
                                    <option value="Grupo B (Martes)">Grupo B (Martes)</option>
                                    <option value="Grupo C (Miércoles)">Grupo C (Miércoles)</option>
                                    <option value="Grupo D (Jueves)">Grupo D (Jueves)</option>
                                    <option value="Grupo E (Viernes)">Grupo E (Viernes)</option>
                                    <option value="Fines de Semana">Fines de Semana</option>
                                </select>
                            </div>

                            {/* NEW MANUAL LOCATION FIELD */}
                            <div className="md:col-span-2">
                                <label className="block text-sm font-medium text-gray-700 mb-1">Lugar Específico (Manual)</label>
                                <input 
                                    type="text" 
                                    value={editingVolunteer.location || ''} 
                                    onChange={e => setEditingVolunteer({...editingVolunteer, location: e.target.value})}
                                    placeholder="Ej: Sala 5, Torre Nueva, Box de Atención..."
                                    className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm focus:ring-2 focus:ring-emerald-500 outline-none"
                                />
                                <p className="text-xs text-gray-400 mt-1">Ingresa manualmente el detalle del lugar o sector asignado.</p>
                            </div>
                        </div>

                        {/* Personal Info */}
                        <div className="space-y-4 pt-4 border-t border-gray-100">
                             <h3 className="font-bold text-gray-800 flex items-center gap-2"><User size={18}/> Datos Personales</h3>
                             <div className="grid md:grid-cols-2 gap-4">
                                <div>
                                    <label className="block text-xs text-gray-500 mb-1">Nombre Completo</label>
                                    <input 
                                        type="text" 
                                        value={editingVolunteer.fullName} 
                                        onChange={e => setEditingVolunteer({...editingVolunteer, fullName: e.target.value})}
                                        className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm"
                                    />
                                </div>
                                <div>
                                    <label className="block text-xs text-gray-500 mb-1">Teléfono</label>
                                    <input 
                                        type="text" 
                                        value={editingVolunteer.phone} 
                                        onChange={e => setEditingVolunteer({...editingVolunteer, phone: e.target.value})}
                                        className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm"
                                    />
                                </div>
                                <div className="md:col-span-2">
                                    <label className="block text-xs text-gray-500 mb-1">Email</label>
                                    <input 
                                        type="email" 
                                        value={editingVolunteer.email} 
                                        onChange={e => setEditingVolunteer({...editingVolunteer, email: e.target.value})}
                                        className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm"
                                    />
                                </div>
                             </div>
                        </div>

                        {/* Motivation / Notes */}
                        <div>
                             <label className="block text-sm font-medium text-gray-700 mb-1">Motivación / Notas</label>
                             <textarea 
                                rows={3}
                                value={editingVolunteer.motivation || ''}
                                onChange={e => setEditingVolunteer({...editingVolunteer, motivation: e.target.value})}
                                className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm bg-gray-50"
                             />
                        </div>
                    </div>

                    {/* Footer Actions */}
                    <div className="p-6 border-t border-gray-100 bg-gray-50 flex justify-end gap-3 rounded-b-xl">
                        <button 
                            type="button" 
                            onClick={() => setEditingVolunteer(null)}
                            className="px-4 py-2 text-gray-700 hover:bg-gray-200 rounded-lg font-medium transition"
                        >
                            Cancelar
                        </button>
                        <button 
                            type="submit"
                            className="px-6 py-2 bg-emerald-600 text-white hover:bg-emerald-700 rounded-lg font-bold shadow-md flex items-center gap-2 transition"
                        >
                            <Save size={18} /> Guardar Ficha
                        </button>
                    </div>
                </form>
            </div>
        </div>
      )}

      {/* Calendar Tab Logic */}
      {activeTab === 'calendar' && (
        <div className="space-y-4">
            {/* Calendar Controls */}
            <div className="flex justify-between items-center bg-white p-4 rounded-xl shadow-sm border border-gray-200">
                <div className="flex items-center gap-4">
                    <button className="p-1 hover:bg-gray-100 rounded-full"><ChevronLeft /></button>
                    <div className="flex items-center gap-2 font-bold text-gray-800">
                        <CalendarIcon size={20} className="text-emerald-600" />
                        <span>Semana del {currentWeek[0].toLocaleDateString()}</span>
                    </div>
                    <button className="p-1 hover:bg-gray-100 rounded-full"><ChevronRight /></button>
                </div>
                <button onClick={handleAddShift} className="bg-emerald-600 text-white px-4 py-2 rounded-lg text-sm font-medium hover:bg-emerald-700 flex items-center gap-2">
                    <Plus size={16} /> Asignar Turno
                </button>
            </div>

            {/* Calendar Grid */}
            <div className="grid grid-cols-7 gap-2">
                {currentWeek.map((day, idx) => (
                    <div key={idx} className="bg-white rounded-lg border border-gray-200 min-h-[300px] flex flex-col">
                        <div className={`text-center py-2 border-b border-gray-100 font-semibold text-sm ${idx === 0 ? 'bg-emerald-50 text-emerald-800' : 'bg-gray-50 text-gray-700'}`}>
                            {day.toLocaleDateString('es-ES', { weekday: 'short', day: 'numeric' })}
                        </div>
                        <div className="p-2 flex-1 space-y-2">
                            {shifts
                                .filter(s => s.date === day.toISOString().split('T')[0])
                                .map(shift => {
                                    const vol = volunteers.find(v => v.id === shift.volunteerId);
                                    return (
                                        <div key={shift.id} className="bg-blue-50 border-l-4 border-blue-500 p-2 rounded text-xs shadow-sm hover:bg-blue-100 transition cursor-pointer">
                                            <div className="font-bold text-gray-800">{vol?.fullName.split(' ')[0]}</div>
                                            <div className="text-gray-500">{shift.startTime} - {shift.endTime}</div>
                                            <div className="text-blue-700 truncate mt-1">{shift.hospitalUnit}</div>
                                        </div>
                                    );
                                })
                            }
                            {/* Empty State visual */}
                            {shifts.filter(s => s.date === day.toISOString().split('T')[0]).length === 0 && (
                                <div className="h-full flex items-center justify-center text-gray-300 text-xs">
                                    Sin turnos
                                </div>
                            )}
                        </div>
                    </div>
                ))}
            </div>
        </div>
      )}
    </div>
  );
};

import React from 'react';

// Enums
export enum UserRole {
  SUPERADMIN = 'SUPERADMIN',
  COLLABORATOR = 'COLLABORATOR',
  VOLUNTEER = 'VOLUNTEER'
}

export enum DonationType {
  MONETARY = 'Monetario',
  SUPPLIES = 'Insumos',
  SERVICE = 'Servicio'
}

export enum VolunteerStatus {
  PENDING = 'Pendiente', 
  ACTIVE = 'Activo',
  TRAINING = 'En Formación',
  INACTIVE = 'Inactivo',
  ON_LEAVE = 'Licencia'
}

export enum CampaignStatus {
  DRAFT = 'Borrador',
  PLANNED = 'Planificada',
  ACTIVE = 'En Curso',
  COMPLETED = 'Finalizada',
  CANCELLED = 'Cancelada'
}

export enum BlogPostStatus {
  DRAFT = 'Borrador',
  PUBLISHED = 'Publicado',
  ARCHIVED = 'Archivado'
}

export type DonationCategory = 'Higiene' | 'Ropa' | 'Alimentos' | 'Médico' | 'Entretención' | 'Otro';
export type HospitalUnit = 'Pediatría' | 'Medicina Hombres' | 'Medicina Mujeres' | 'Urgencias' | 'Geriatría' | 'Oncología';
export type VolunteerGroup = 'Grupo A (Lunes)' | 'Grupo B (Martes)' | 'Grupo C (Miércoles)' | 'Grupo D (Jueves)' | 'Grupo E (Viernes)' | 'Fines de Semana';

// Interfaces
export interface User {
  id: number;
  username: string;
  role: UserRole;
  name: string;
  volunteerId?: number; // Links user to a volunteer profile
}

// CMS Interfaces
export interface BrandingConfig {
  logoUrl: string;
  primaryColor: string; // Hex code (Brand)
  secondaryColor: string; // Hex code (Accent)
  fontFamily: string;
}

export interface HeroButton {
  label: string;
  link: string; // Internal route (e.g. 'donate') or external URL
  style: 'primary' | 'outline';
}

export interface HeroSlide {
  id: number;
  mediaType: 'image' | 'video';
  mediaUrl: string; // URL to image or mp4
  title: string;
  subtitle: string;
  buttons: HeroButton[]; // Array of buttons (0 to 2 recommended)
  isActive: boolean;
  order: number;
}

export interface ServiceItem {
  id: number;
  title: string;
  description: string;
  icon: 'Heart' | 'Users' | 'Smile' | 'Hand' | 'Star' | 'Sun'; // Icon keys
}

export interface CustomPage {
  id: number;
  slug: string; // URL friendly name (e.g., 'protocolos-covid')
  title: string;
  content: string; // HTML content
  isVisible: boolean;
  lastModified: string;
}

export interface BlogPost {
  id: number;
  title: string;
  excerpt: string;
  content: string; // HTML or Markdown content
  coverImage: string;
  author: string;
  publishDate: string;
  status: BlogPostStatus;
  tags: string[];
}

export interface Volunteer {
  id: number;
  fullName: string;
  email: string;
  phone: string;
  status: VolunteerStatus;
  hoursThisMonth: number;
  joinDate: string;
  availability?: string;
  motivation?: string;
  profileImage?: string; // New field for user avatar

  // New Fields for Coordination
  hospitalUnit?: HospitalUnit;
  location?: string; // Manual entry for specific place (e.g. "Sala 5", "Torre Nueva")
  group?: VolunteerGroup;
  skills?: string[]; // e.g. "Primeros Auxilios", "Contención"
  vaccinationStatus?: boolean;
}

export interface Shift {
  id: number;
  volunteerId: number;
  date: string; // YYYY-MM-DD
  startTime: string; // HH:MM
  endTime: string; // HH:MM
  hospitalUnit: HospitalUnit;
  status: 'Programado' | 'Completado' | 'Cancelado';
}

export interface Activity {
  id: number;
  name: string;
  date: string;
  beneficiaries: number;
  status: 'Programada' | 'En Curso' | 'Finalizada';
}

export interface Donation {
  id: number;
  donorName: string;
  type: DonationType;
  amountOrItem: string;
  date: string;
  status: 'Pendiente' | 'Recibido';
}

export interface DonationItem {
  id: number;
  name: string;
  desc: string;
  priority: 'Alta' | 'Media' | 'Baja';
  category: DonationCategory;
  targetAmount?: number;
  currentAmount: number;
  unit?: string;
}

export interface Campaign {
  id: number;
  name: string;
  objective: string;
  startDate: string;
  endDate: string;
  channel: string;
  targetAudience: string;
  status: CampaignStatus;
  budget?: string;
  notes?: string;
}

export interface NavItem {
  label: string;
  path: string;
  icon?: React.ReactNode;
}

import React, { useState, useEffect } from 'react';
import { useAuth } from '../../context/AuthContext';
import { useVolunteer } from '../../context/VolunteerContext';
import { LogOut, Calendar, Clock, User, Mail, Shield, Phone, Edit2, Save, X, Camera } from 'lucide-react';

interface VolunteerPortalProps {
  onNavigate: (page: string) => void;
}

export const VolunteerPortal: React.FC<VolunteerPortalProps> = ({ onNavigate }) => {
  const { user, logout } = useAuth();
  const { volunteers, getShiftsByVolunteer, updateVolunteerDetails } = useVolunteer();

  // Find the volunteer profile linked to the logged-in user
  const volunteerProfile = volunteers.find(v => v.id === user?.volunteerId);
  // Ensure shifts are dynamic based on current state
  const myShifts = user?.volunteerId ? getShiftsByVolunteer(user.volunteerId) : [];

  // Edit Mode State
  const [isEditing, setIsEditing] = useState(false);
  const [formData, setFormData] = useState({
      fullName: '',
      email: '',
      phone: '',
      profileImage: ''
  });

  // Init form data when profile loads
  useEffect(() => {
    if (volunteerProfile) {
        setFormData({
            fullName: volunteerProfile.fullName,
            email: volunteerProfile.email,
            phone: volunteerProfile.phone,
            profileImage: volunteerProfile.profileImage || ''
        });
    }
  }, [volunteerProfile]);

  const handleLogout = () => {
    logout();
    onNavigate('home');
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setFormData(prev => ({ ...prev, profileImage: reader.result as string }));
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSave = () => {
      if (volunteerProfile) {
          updateVolunteerDetails(volunteerProfile.id, {
              fullName: formData.fullName,
              email: formData.email,
              phone: formData.phone,
              profileImage: formData.profileImage
          });
          setIsEditing(false);
      }
  };

  if (!volunteerProfile) {
    return (
        <div className="min-h-screen flex items-center justify-center bg-gray-50">
            <div className="text-center">
                <h2 className="text-xl font-bold text-gray-800">Error de Perfil</h2>
                <p className="text-gray-600">No se encontró una ficha de voluntario asociada a tu usuario.</p>
                <button onClick={handleLogout} className="mt-4 text-emerald-600 hover:underline">Cerrar Sesión</button>
            </div>
        </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50">
      {/* Navbar specific for Volunteer Portal */}
      <nav className="bg-emerald-800 text-white shadow-md">
        <div className="container mx-auto px-4 py-3 flex justify-between items-center">
            <div className="flex items-center gap-2 font-bold text-lg">
                <Shield size={24} />
                Portal Voluntario
            </div>
            <div className="flex items-center gap-4">
                <div className="flex items-center gap-2">
                    {volunteerProfile.profileImage ? (
                        <img src={volunteerProfile.profileImage} alt="Profile" className="w-8 h-8 rounded-full object-cover border border-emerald-400" />
                    ) : (
                        <div className="w-8 h-8 rounded-full bg-emerald-600 flex items-center justify-center text-xs font-bold">
                            {volunteerProfile.fullName.charAt(0)}
                        </div>
                    )}
                    <span className="text-sm font-medium hidden sm:block">Hola, {volunteerProfile.fullName.split(' ')[0]}</span>
                </div>
                <button onClick={handleLogout} className="bg-emerald-900 hover:bg-emerald-950 p-2 rounded-lg transition text-xs flex items-center gap-1">
                    <LogOut size={14} /> Salir
                </button>
            </div>
        </div>
      </nav>

      <div className="container mx-auto px-4 py-8 max-w-5xl">
        <div className="grid md:grid-cols-3 gap-6">

            {/* Profile Card (Editable) */}
            <div className="md:col-span-1">
                <div className="bg-white rounded-xl shadow-sm border border-gray-200 overflow-hidden relative">
                    {/* Header Background */}
                    <div className="h-24 bg-gradient-to-r from-emerald-600 to-emerald-500"></div>

                    {/* Avatar Logic */}
                    <div className="absolute top-12 left-1/2 -translate-x-1/2">
                        <div className="relative group">
                            <div className="w-24 h-24 rounded-full border-4 border-white shadow-md overflow-hidden bg-white flex items-center justify-center">
                                {formData.profileImage ? (
                                    <img src={formData.profileImage} alt="Profile" className="w-full h-full object-cover" />
                                ) : (
                                    <span className="text-3xl font-bold text-emerald-600">{formData.fullName.charAt(0)}</span>
                                )}
                            </div>
                            {isEditing && (
                                <label className="absolute inset-0 bg-black/50 rounded-full flex items-center justify-center text-white cursor-pointer opacity-0 group-hover:opacity-100 transition-opacity">
                                    <Camera size={24} />
                                    <input type="file" className="hidden" accept="image/*" onChange={handleImageUpload} />
                                </label>
                            )}
                        </div>
                    </div>

                    <div className="pt-16 pb-6 px-6 text-center">
                        {!isEditing ? (
                            <>
                                <h2 className="text-xl font-bold text-gray-900">{volunteerProfile.fullName}</h2>
                                <span className={`px-3 py-1 text-xs font-bold rounded-full mt-2 inline-block ${
                                    volunteerProfile.status === 'Activo' ? 'bg-green-100 text-green-700' : 'bg-yellow-100 text-yellow-700'
                                }`}>
                                    {volunteerProfile.status}
                                </span>

                                <div className="mt-6 space-y-4 text-left">
                                    <div className="flex items-center justify-between py-2 border-b border-gray-50">
                                        <span className="text-xs font-bold text-gray-400 uppercase">Unidad</span>
                                        <span className="text-sm font-medium text-gray-700">{volunteerProfile.hospitalUnit || '-'}</span>
                                    </div>
                                    <div className="flex items-center justify-between py-2 border-b border-gray-50">
                                        <span className="text-xs font-bold text-gray-400 uppercase">Grupo</span>
                                        <span className="text-sm font-medium text-gray-700">{volunteerProfile.group || '-'}</span>
                                    </div>
                                    <div className="flex items-center justify-between py-2 border-b border-gray-50">
                                        <span className="text-xs font-bold text-gray-400 uppercase">Teléfono</span>
                                        <span className="text-sm font-medium text-gray-700 flex items-center gap-1">
                                            {volunteerProfile.phone}
                                        </span>
                                    </div>
                                     <div className="flex items-center justify-between py-2 border-b border-gray-50">
                                        <span className="text-xs font-bold text-gray-400 uppercase">Email</span>
                                        <span className="text-sm font-medium text-gray-700 truncate max-w-[150px]" title={volunteerProfile.email}>
                                            {volunteerProfile.email}
