// --- STORAGE ENGINE (Simula SQL/NoSQL) ---
// Helper genérico para simular llamadas asíncronas a BD
const dbCall = async <T>(operation: () => T): Promise<T> => {
  return new Promise((resolve) => {
    setTimeout(() => {
      resolve(operation());
    }, NETWORK_DELAY);
  });
};

// Generic LocalStorage Wrapper
const getCollection = <T>(key: string, defaults: T[] = []): T[] => {
  const data = localStorage.getItem(key);
  return data ? JSON.parse(data) : defaults;
};

const saveCollection = <T>(key: string, data: T[]): void => {
  localStorage.setItem(key, JSON.stringify(data));
};

// --- API EXPORTADA ---

export const db = {
  volunteers: {
    getAll: () => dbCall(() => getCollection<Volunteer>('volunteers_data', defaultVolunteers)),
    create: (data: Omit<Volunteer, 'id'>) => dbCall(() => {
      const list = getCollection<Volunteer>('volunteers_data', defaultVolunteers);
      const newItem = { ...data, id: Date.now() } as Volunteer;
      saveCollection('volunteers_data', [...list, newItem]);
      return newItem;
    }),
    update: (id: number, data: Partial<Volunteer>) => dbCall(() => {
      const list = getCollection<Volunteer>('volunteers_data', defaultVolunteers);
      const updated = list.map(item => item.id === id ? { ...item, ...data } : item);
      saveCollection('volunteers_data', updated);
      return updated.find(i => i.id === id);
    }),
    delete: (id: number) => dbCall(() => {
      const list = getCollection<Volunteer>('volunteers_data', defaultVolunteers);
      saveCollection('volunteers_data', list.filter(i => i.id !== id));
    })
  },

  shifts: {
    getAll: () => dbCall(() => getCollection<Shift>('volunteers_shifts', [])),
    create: (data: Omit<Shift, 'id'>) => dbCall(() => {
      const list = getCollection<Shift>('volunteers_shifts', []);
      const newItem = { ...data, id: Date.now() } as Shift;
      saveCollection('volunteers_shifts', [...list, newItem]);
      return newItem;
    }),
    update: (id: number, data: Partial<Shift>) => dbCall(() => {
        const list = getCollection<Shift>('volunteers_shifts', []);
        const updated = list.map(item => item.id === id ? { ...item, ...data } : item);
        saveCollection('volunteers_shifts', updated);
        return updated.find(i => i.id === id);
    }),
    delete: (id: number) => dbCall(() => {
        const list = getCollection<Shift>('volunteers_shifts', []);
        saveCollection('volunteers_shifts', list.filter(i => i.id !== id));
    })
  },

  crm: {
    getCampaigns: () => dbCall(() => getCollection<Campaign>('crm_campaigns', defaultCampaigns)),
    create: (data: Omit<Campaign, 'id'>) => dbCall(() => {
        const list = getCollection<Campaign>('crm_campaigns', defaultCampaigns);
        const newItem = { ...data, id: Date.now() } as Campaign;
        saveCollection('crm_campaigns', [...list, newItem]);
        return newItem;
    }),
    update: (id: number, data: Partial<Campaign>) => dbCall(() => {
        const list = getCollection<Campaign>('crm_campaigns', defaultCampaigns);
        const updated = list.map(c => c.id === id ? { ...c, ...data } : c);
        saveCollection('crm_campaigns', updated);
    }),
    delete: (id: number) => dbCall(() => {
        const list = getCollection<Campaign>('crm_campaigns', defaultCampaigns);
        saveCollection('crm_campaigns', list.filter(c => c.id !== id));
    })
  },

  blog: {
    getPosts: () => dbCall(() => getCollection<BlogPost>('blog_posts', defaultPosts)),
    create: (data: Omit<BlogPost, 'id' | 'publishDate'>) => dbCall(() => {
        const list = getCollection<BlogPost>('blog_posts', defaultPosts);
        const newItem: BlogPost = { ...data, id: Date.now(), publishDate: new Date().toISOString() };
        saveCollection('blog_posts', [newItem, ...list]);
        return newItem;
    }),
    update: (id: number, data: Partial<BlogPost>) => dbCall(() => {
        const list = getCollection<BlogPost>('blog_posts', defaultPosts);
        const updated = list.map(p => p.id === id ? { ...p, ...data } : p);
        saveCollection('blog_posts', updated);
    }),
    delete: (id: number) => dbCall(() => {
        const list = getCollection<BlogPost>('blog_posts', defaultPosts);
        saveCollection('blog_posts', list.filter(p => p.id !== id));
    })
  },

  content: {
    // Generic helper for single-object stores (Branding, About, etc.)
    get: <T>(key: string, defaultVal: T) => dbCall(() => {
        const d = localStorage.getItem(key);
        return d ? JSON.parse(d) as T : defaultVal;
    }),
    set: <T>(key: string, val: T) => dbCall(() => {
        localStorage.setItem(key, JSON.stringify(val));
        return val;
    }),
    // Collections (Services, Needs, Slides, Pages)
    getList: <T>(key: string, defaultVal: T[]) => dbCall(() => getCollection<T>(key, defaultVal)),
    createItem: <T>(key: string, item: any) => dbCall(() => {
        const list = getCollection<T>(key, []);
        const newItem = { ...item, id: Date.now() };
        saveCollection(key, [...list, newItem]);
        return newItem;
    }),
    updateItem: <T extends {id: number}>(key: string, id: number, updates: Partial<T>) => dbCall(() => {
        const list = getCollection<T>(key, []);
        const updated = list.map(i => i.id === id ? { ...i, ...updates } : i);
        saveCollection(key, updated);
        return updated;
    }),
    deleteItem: <T extends {id: number}>(key: string, id: number) => dbCall(() => {
        const list = getCollection<T>(key, []);
        saveCollection(key, list.filter(i => i.id !== id));
    })
  },

  auth: {
      login: (username: string, pass: string) => dbCall(() => {
        // Simulated Server-Side Validation
        if (username === 'admin' && pass === 'admin') return { id: 1, username, name: 'Coordinadora General', role: UserRole.SUPERADMIN };
        if (username === 'colab' && pass === 'colab') return { id: 2, username, name: 'Jefa de Grupo', role: UserRole.COLLABORATOR };
        if (username === 'vol' && pass === 'vol') return { id: 3, username, name: 'María González', role: UserRole.VOLUNTEER, volunteerId: 1 };
        return null;
      }),
      getUser: () => dbCall(() => {
          const u = localStorage.getItem('auth_user');
          return u ? JSON.parse(u) as User : null;
      }),
      setUser: (user: User | null) => dbCall(() => {
          if(user) localStorage.setItem('auth_user', JSON.stringify(user));
          else localStorage.removeItem('auth_user');
      })
  }
};

import React, { createContext, useContext, useState, useEffect } from 'react';
import { Volunteer, VolunteerStatus, Shift } from '../types';
import { db } from '../services/db';

interface VolunteerContextType {
  volunteers: Volunteer[];
  shifts: Shift[];
  loading: boolean;
  addVolunteer: (vol: Omit<Volunteer, 'id' | 'hoursThisMonth' | 'joinDate' | 'status'>) => Promise<void>;
  updateVolunteerStatus: (id: number, status: VolunteerStatus) => Promise<void>;
  updateVolunteerDetails: (id: number, details: Partial<Volunteer>) => Promise<void>;
  getVolunteerStats: () => { active: number; pending: number; totalHours: number };
  addShift: (shift: Omit<Shift, 'id'>) => Promise<void>;
  updateShift: (id: number, shift: Partial<Shift>) => Promise<void>;
  deleteShift: (id: number) => Promise<void>;
  getShiftsByVolunteer: (volunteerId: number) => Shift[];
}

const VolunteerContext = createContext<VolunteerContextType | undefined>(undefined);

export const VolunteerProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [volunteers, setVolunteers] = useState<Volunteer[]>([]);
  const [shifts, setShifts] = useState<Shift[]>([]);
  const [loading, setLoading] = useState(true);

  // Initial Load from DB
  useEffect(() => {
    const loadData = async () => {
        try {
            const [vols, shfts] = await Promise.all([
                db.volunteers.getAll(),
                db.shifts.getAll()
            ]);
            setVolunteers(vols);
            setShifts(shfts);
        } catch (error) {
            console.error("Failed to load volunteer data", error);
        } finally {
            setLoading(false);
        }
    };
    loadData();
  }, []);

  const addVolunteer = async (volData: Omit<Volunteer, 'id' | 'hoursThisMonth' | 'joinDate' | 'status'>) => {
    const newVol = await db.volunteers.create({
      ...volData,
      status: VolunteerStatus.PENDING,
      hoursThisMonth: 0,
      joinDate: new Date().toISOString().split('T')[0]
    });
    setVolunteers(prev => [...prev, newVol]);
  };

  const updateVolunteerStatus = async (id: number, status: VolunteerStatus) => {
    await db.volunteers.update(id, { status });
    setVolunteers(prev => prev.map(v => v.id === id ? { ...v, status } : v));
  };

  const updateVolunteerDetails = async (id: number, details: Partial<Volunteer>) => {
    await db.volunteers.update(id, details);
    setVolunteers(prev => prev.map(v => v.id === id ? { ...v, ...details } : v));
  };

  const getVolunteerStats = () => {
    return {
      active: volunteers.filter(v => v.status === VolunteerStatus.ACTIVE).length,
      pending: volunteers.filter(v => v.status === VolunteerStatus.PENDING).length,
      totalHours: volunteers.reduce((acc, curr) => acc + curr.hoursThisMonth, 0)
    };
  };

  const addShift = async (shift: Omit<Shift, 'id'>) => {
    const newShift = await db.shifts.create(shift);
    setShifts(prev => [...prev, newShift]);
  };

  const updateShift = async (id: number, shift: Partial<Shift>) => {
    await db.shifts.update(id, shift);
    setShifts(prev => prev.map(s => s.id === id ? { ...s, ...shift } : s));
  };

  const deleteShift = async (id: number) => {
    await db.shifts.delete(id);
    setShifts(prev => prev.filter(s => s.id !== id));
  };

  const getShiftsByVolunteer = (volunteerId: number) => {
    return shifts.filter(s => s.volunteerId === volunteerId).sort((a,b) => a.date.localeCompare(b.date));
  };

  return (
    <VolunteerContext.Provider value={{ 
      volunteers, 
      shifts,
      loading,
      addVolunteer, 
      updateVolunteerStatus, 
      updateVolunteerDetails,
      getVolunteerStats,
      addShift,
      updateShift,
      deleteShift,
      getShiftsByVolunteer
    }}>
      {children}
    </VolunteerContext.Provider>
  );
};

export const useVolunteer = () => {
  const context = useContext(VolunteerContext);
  if (!context) throw new Error('useVolunteer must be used within a VolunteerProvider');
  return context;
};

