import React, { createContext, useContext, useState, useEffect } from 'react';
import { BlogPost, BlogPostStatus } from '../types';
import { db } from '../services/db';

interface BlogContextType {
  posts: BlogPost[];
  loading: boolean;
  addPost: (post: Omit<BlogPost, 'id' | 'publishDate'>) => Promise<void>;
  updatePost: (id: number, post: Partial<BlogPost>) => Promise<void>;
  deletePost: (id: number) => Promise<void>;
  getPublishedPosts: () => BlogPost[];
  getPostById: (id: number) => BlogPost | undefined;
}

const BlogContext = createContext<BlogContextType | undefined>(undefined);

export const BlogProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [posts, setPosts] = useState<BlogPost[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const load = async () => {
        const data = await db.blog.getPosts();
        setPosts(data);
        setLoading(false);
    };
    load();
  }, []);

  const addPost = async (post: Omit<BlogPost, 'id' | 'publishDate'>) => {
    const newPost = await db.blog.create(post);
    setPosts(prev => [newPost, ...prev]);
  };

  const updatePost = async (id: number, updatedFields: Partial<BlogPost>) => {
    await db.blog.update(id, updatedFields);
    setPosts(prev => prev.map(p => (p.id === id ? { ...p, ...updatedFields } : p)));
  };

  const deletePost = async (id: number) => {
    await db.blog.delete(id);
    setPosts(prev => prev.filter(p => p.id !== id));
  };

  const getPublishedPosts = () => {
    return posts.filter(p => p.status === BlogPostStatus.PUBLISHED).sort((a, b) => new Date(b.publishDate).getTime() - new Date(a.publishDate).getTime());
  };

  const getPostById = (id: number) => {
    return posts.find(p => p.id === id);
  };

  return (
    <BlogContext.Provider value={{ posts, loading, addPost, updatePost, deletePost, getPublishedPosts, getPostById }}>
      {children}
    </BlogContext.Provider>
  );
};

export const useBlog = () => {
  const context = useContext(BlogContext);
  if (!context) throw new Error('useBlog must be used within a BlogProvider');
  return context;
};

import React, { createContext, useContext, useState, useEffect } from 'react';
import { User, UserRole } from '../types';
import { db } from '../services/db';

interface AuthContextType {
  user: User | null;
  isAuthenticated: boolean;
  isLoading: boolean;
  login: (username: string, pass: string) => Promise<boolean>;
  logout: () => Promise<void>;
  hasPermission: (requiredRole: UserRole[]) => boolean;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export const AuthProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [user, setUser] = useState<User | null>(null);
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    const initAuth = async () => {
        const u = await db.auth.getUser();
        setUser(u);
        setIsLoading(false);
    };
    initAuth();
  }, []);

  const login = async (username: string, pass: string) => {
    setIsLoading(true);
    const userResult = await db.auth.login(username, pass);
    if (userResult) {
        await db.auth.setUser(userResult);
        setUser(userResult);
        setIsLoading(false);
        return true;
    }
    setIsLoading(false);
    return false;
  };

  const logout = async () => {
    await db.auth.setUser(null);
    setUser(null);
  };

  const hasPermission = (allowedRoles: UserRole[]) => {
    if (!user) return false;
    return allowedRoles.includes(user.role);
  };

  return (
    <AuthContext.Provider value={{ user, isAuthenticated: !!user, isLoading, login, logout, hasPermission }}>
      {children}
    </AuthContext.Provider>
  );
};

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (!context) throw new Error('useAuth must be used within an AuthProvider');
  return context;
};

