  storageBucket: "TU_PROYECTO.appspot.com",
  messagingSenderId: "TU_SENDER_ID",
  appId: "TU_APP_ID"
};

// Initialize Firebase
const app = initializeApp(firebaseConfig);

// Initialize Cloud Firestore and get a reference to the service
export const firestore = getFirestore(app);

import { 
  Volunteer, Shift, Campaign, BlogPost, DonationItem, ServiceItem, 
  CustomPage, HeroSlide, BrandingConfig, User, VolunteerStatus, CampaignStatus, BlogPostStatus, UserRole 
} from '../types';
import { firestore } from './firebaseConfig';
import { 
  collection, getDocs, addDoc, updateDoc, deleteDoc, 
  query, where, doc, getDoc, setDoc 
} from 'firebase/firestore';

// --- DEFAULTS (Fallback if DB is empty) ---
const defaultBranding: BrandingConfig = {
    logoUrl: 'https://i.imgur.com/k2yKx60.jpg',
    primaryColor: '#10b981',
    secondaryColor: '#3b82f6',
    fontFamily: 'Inter'
};

// --- HELPER FUNCTIONS ---

// Como usamos "id: number" en tu app pero Firestore usa strings,
// usaremos el campo interno 'id' del documento para buscar, 
// o generaremos uno nuevo al crear.

// Obtener toda una colección
const getCollection = async <T>(collectionName: string): Promise<T[]> => {
    try {
        const querySnapshot = await getDocs(collection(firestore, collectionName));
        return querySnapshot.docs.map(doc => {
             // Retornamos los datos. Si el doc tiene un ID numérico interno, lo usa.
             // Si no, podríamos usar doc.id, pero tu app espera numbers.
             return { ...doc.data() } as T;
        });
    } catch (error) {
        console.error(`Error getting collection ${collectionName}:`, error);
        return [];
    }
};

// Crear item (Generando ID numérico para compatibilidad)
const createItem = async <T>(collectionName: string, data: any): Promise<T> => {
    try {
        const newId = Date.now();
        const itemWithId = { ...data, id: newId };
        await addDoc(collection(firestore, collectionName), itemWithId);
        return itemWithId as T;
    } catch (error) {
        console.error(`Error creating in ${collectionName}:`, error);
        throw error;
    }
};

// Actualizar item (Buscando por el campo numérico 'id')
const updateItem = async <T>(collectionName: string, id: number, data: Partial<T>): Promise<void> => {
    try {
        // 1. Buscar el documento que tenga este ID numérico
        const q = query(collection(firestore, collectionName), where("id", "==", id));
        const querySnapshot = await getDocs(q);

        if (!querySnapshot.empty) {
            const docRef = querySnapshot.docs[0].ref;
            await updateDoc(docRef, data as any);
        } else {
            console.warn(`No document found with numeric id: ${id} in ${collectionName}`);
        }
    } catch (error) {
        console.error(`Error updating in ${collectionName}:`, error);
        throw error;
    }
};

// Borrar item
const deleteItem = async (collectionName: string, id: number): Promise<void> => {
    try {
        const q = query(collection(firestore, collectionName), where("id", "==", id));
        const querySnapshot = await getDocs(q);
        if (!querySnapshot.empty) {
            await deleteDoc(querySnapshot.docs[0].ref);
        }
    } catch (error) {
        console.error(`Error deleting in ${collectionName}:`, error);
        throw error;
    }
};

// Configuración Global (Single Documents)
const getSetting = async <T>(docId: string, defaultVal: T): Promise<T> => {
    try {
        const docRef = doc(firestore, 'settings', docId);
        const docSnap = await getDoc(docRef);
        if (docSnap.exists()) {
            return docSnap.data() as T;
        } else {
            return defaultVal;
        }
    } catch (error) {
        return defaultVal;
    }
};

const setSetting = async <T>(docId: string, data: T): Promise<T> => {
    try {
        await setDoc(doc(firestore, 'settings', docId), data as any);
        return data;
    } catch (error) {
        console.error("Error setting config:", error);
        throw error;
    }
};


// --- API ---

export const db = {
  volunteers: {
    getAll: () => getCollection<Volunteer>('volunteers'),
    create: (data: Omit<Volunteer, 'id'>) => createItem<Volunteer>('volunteers', data),
    update: (id: number, data: Partial<Volunteer>) => updateItem<Volunteer>('volunteers', id, data),
    delete: (id: number) => deleteItem('volunteers', id)
  },

  shifts: {
    getAll: () => getCollection<Shift>('shifts'),
    create: (data: Omit<Shift, 'id'>) => createItem<Shift>('shifts', data),
    update: (id: number, data: Partial<Shift>) => updateItem<Shift>('shifts', id, data),
    delete: (id: number) => deleteItem('shifts', id)
  },

  crm: {
    getCampaigns: () => getCollection<Campaign>('campaigns'),
    create: (data: Omit<Campaign, 'id'>) => createItem<Campaign>('campaigns', data),
    update: (id: number, data: Partial<Campaign>) => updateItem<Campaign>('campaigns', id, data),
    delete: (id: number) => deleteItem('campaigns', id)
  },

  blog: {
    getPosts: () => getCollection<BlogPost>('posts'),
    create: (data: Omit<BlogPost, 'id' | 'publishDate'>) => {
        return createItem<BlogPost>('posts', { ...data, publishDate: new Date().toISOString() });
    },
    update: (id: number, data: Partial<BlogPost>) => updateItem<BlogPost>('posts', id, data),
    delete: (id: number) => deleteItem('posts', id)
  },

  content: {
    // Configuración única (Branding, Textos Home, etc)
    get: <T>(key: string, defaultVal: T) => getSetting<T>(key, defaultVal),
    set: <T>(key: string, val: T) => setSetting<T>(key, val),

    // Listas de contenido (Slides, Services, etc)
    getList: <T>(key: string, defaultVal: T[]) => getCollection<T>(key),
    createItem: <T>(key: string, item: any) => createItem<T>(key, item),
    updateItem: <T extends {id: number}>(key: string, id: number, updates: Partial<T>) => {
        // Wrapper para retornar la lista actualizada es costoso en Firebase, 
        // así que la app tendrá que manejar la actualización optimista o recargar.
        // Por compatibilidad con tu context actual, hacemos el update y devolvemos la lista completa nueva.
        return updateItem<T>(key, id, updates).then(() => getCollection<T>(key));
    },
    deleteItem: <T extends {id: number}>(key: string, id: number) => {
         return deleteItem(key, id);
    }
  },

  auth: {
      login: async (username: string, pass: string) => {
        // En un entorno real usaríamos Firebase Auth.
        // Para mantener compatibilidad con tu sistema de usuarios simple:
        // Buscamos en una colección 'users' si hay coincidencia.
        try {
            const q = query(
                collection(firestore, 'users'), 
                where("username", "==", username),
                where("password", "==", pass) // NOTA: Inseguro para producción real, ideal usar Auth.
            );
            const snapshot = await getDocs(q);
            if (!snapshot.empty) {
                return snapshot.docs[0].data() as User;
            }
            // Fallback para admin inicial si la BD está vacía
            if (username === 'admin' && pass === 'admin') {
                return { id: 1, username: 'admin', name: 'SuperAdmin Local', role: UserRole.SUPERADMIN };
            }
            return null;
        } catch (e) {
            console.error("Login error", e);
            // Fallback de emergencia
            if (username === 'admin' && pass === 'admin') return { id: 1, username: 'admin', name: 'SuperAdmin Local', role: UserRole.SUPERADMIN };
            return null;
        }
      },
      getUser: async () => {
          const u = localStorage.getItem('auth_user');
          return u ? JSON.parse(u) as User : null;
      },
      setUser: async (user: User | null) => {
          if(user) localStorage.setItem('auth_user', JSON.stringify(user));
          else localStorage.removeItem('auth_user');
      }
  }
};

