const dbCall = <T>(fn: () => T): Promise<T> => {
  return new Promise((resolve) => {
    setTimeout(() => {
      resolve(fn());
    }, 300); // Small delay to simulate async feeling
  });
};

// Generic Helpers
const getList = <T>(key: string, defaultData: T[] = []): T[] => {
    const stored = localStorage.getItem(key);
    return stored ? JSON.parse(stored) : defaultData;
};

const saveList = <T>(key: string, data: T[]) => {
    localStorage.setItem(key, JSON.stringify(data));
};

const createItem = <T>(key: string, item: any, defaultData: T[] = []): T => {
    const list = getList<T>(key, defaultData);
    const newItem = { ...item, id: Date.now() };
    saveList(key, [...list, newItem]);
    return newItem as T;
};

const updateItem = <T extends {id: number}>(key: string, id: number, updates: Partial<T>, defaultData: T[] = []): T[] => {
    const list = getList<T>(key, defaultData);
    const updatedList = list.map(i => i.id === id ? { ...i, ...updates } : i);
    saveList(key, updatedList);
    return updatedList;
};

const deleteItem = <T extends {id: number}>(key: string, id: number, defaultData: T[] = []): void => {
    const list = getList<T>(key, defaultData);
    const updatedList = list.filter(i => i.id !== id);
    saveList(key, updatedList);
};

