        if (username === 'admin' && pass === 'admin') return { id: 1, username: 'admin', name: 'SuperAdmin', role: UserRole.SUPERADMIN };
        if (username === 'colab' && pass === 'colab') return { id: 2, username: 'colab', name: 'Colaborador', role: UserRole.COLLABORATOR };
        if (username === 'vol' && pass === 'vol') return { id: 3, username: 'vol', name: 'Voluntaria Demo', role: UserRole.VOLUNTEER, volunteerId: 1 };
        return null;
      }),
      getUser: () => dbCall(() => {
          const u = localStorage.getItem('auth_user');
          return u ? JSON.parse(u) as User : null;
      }),
      setUser: (user: User | null) => dbCall(() => {
          if(user) localStorage.setItem('auth_user', JSON.stringify(user));
          else localStorage.removeItem('auth_user');
      })
  }
};

import { createClient } from '@supabase/supabase-js';

const SUPABASE_URL_KEY = 'vidayesperanza_supabase_url';
const SUPABASE_ANON_KEY_KEY = 'vidayesperanza_supabase_key';

export const getStoredCredentials = () => {
    return {
        url: localStorage.getItem(SUPABASE_URL_KEY),
        key: localStorage.getItem(SUPABASE_ANON_KEY_KEY)
    };
};

export const setStoredCredentials = (url: string, key: string) => {
    localStorage.setItem(SUPABASE_URL_KEY, url);
    localStorage.setItem(SUPABASE_ANON_KEY_KEY, key);
    window.location.reload(); // Reload to initialize client
};

export const clearCredentials = () => {
    localStorage.removeItem(SUPABASE_URL_KEY);
    localStorage.removeItem(SUPABASE_ANON_KEY_KEY);
    window.location.reload();
};

const creds = getStoredCredentials();

// Initialize client only if creds exist, otherwise export null to be handled by wrapper
export const supabase = (creds.url && creds.key) 
    ? createClient(creds.url, creds.key) 
    : null;

