const fetchAll = async <T>(table: string, defaults: T[]): Promise<T[]> => {
    if (!supabase) return defaults;
    const { data, error } = await supabase.from(table).select('*');
    if (error) {
        console.error(`Error fetching ${table}:`, error);
        return defaults;
    }
    // Return defaults if data is empty (only for critical content tables)
    if (!data || data.length === 0) {
        if(table === 'hero_slides') return defaultSlides as unknown as T[];
        if(table === 'services') return defaultServices as unknown as T[];
        if(table === 'donation_needs') return defaultDonationNeeds as unknown as T[];
        if(table === 'blog_posts') return defaultPosts as unknown as T[];
        return [] as T[]; 
    }
    return data as T[];
};

const insertItem = async <T>(table: string, item: any): Promise<T> => {
    if (!supabase) return item;
    // Remove ID if present to allow DB auto-increment (Supabase specific)
    const { id, ...rest } = item; 
    const { data, error } = await supabase.from(table).insert(rest).select().single();
    if (error) {
        console.error(`Error inserting into ${table}:`, error);
        throw error;
    }
    return data as T;
};

const updateRow = async <T>(table: string, id: number, updates: any): Promise<void> => {
    if (!supabase) return;
    const { error } = await supabase.from(table).update(updates).eq('id', id);
    if (error) console.error(`Error updating ${table}:`, error);
};

const deleteRow = async (table: string, id: number): Promise<void> => {
    if (!supabase) return;
    const { error } = await supabase.from(table).delete().eq('id', id);
    if (error) console.error(`Error deleting from ${table}:`, error);
};

