    // Settings table Key-Value
    get: async <T>(key: string, defaultVal: T): Promise<T> => {
        if (!supabase) return defaultVal;
        const { data } = await supabase.from('settings').select('value').eq('key', key).single();
        return data ? data.value : defaultVal;
    },
    set: async <T>(key: string, val: T): Promise<T> => {
        if (!supabase) return val;
        // Upsert logic for settings
        const { data, error } = await supabase.from('settings').upsert({ key, value: val }).select().single();
        return data ? data.value : val;
    },

    // Lists handled via standard tables
    getList: <T>(key: string, defaultVal: T[]) => {
         // Map legacy LocalStorage keys to Supabase Table Names
         let table = key;
         if (key === 'hero_slides') table = 'hero_slides';
         if (key === 'content_services') table = 'services';
         if (key === 'donationNeeds') table = 'donation_needs';
         if (key === 'content_custom_pages') table = 'custom_pages';

         return fetchAll<T>(table, defaultVal);
    },

    createItem: <T>(key: string, item: any) => {
         let table = key;
         if (key === 'hero_slides') table = 'hero_slides';
         if (key === 'content_services') table = 'services';
         if (key === 'donationNeeds') table = 'donation_needs';
         if (key === 'content_custom_pages') table = 'custom_pages';
