// --- SUPABASE HELPERS ---
// Using function declaration instead of arrow function for generics to avoid JSX ambiguity
async function fetchAll<T>(table: string, defaults: T[] = []): Promise<T[]> {
    if (!supabase) return defaults;
    const { data, error } = await supabase.from(table).select('*').order('id', { ascending: true });
    if (error) {
        console.error(`Error fetching ${table}:`, error);
        return defaults;
    }
    if (!data || data.length === 0) {
        if (table === 'hero_slides') return defaultSlides as unknown as T[];
        if (table === 'services') return defaultServices as unknown as T[];
        return defaults;
    }
    return data as T[];
}

// Using function declaration instead of arrow function for generics to avoid JSX ambiguity
async function insertItem<T>(table: string, item: any): Promise<T> {
    if (!supabase) throw new Error("Supabase no configurado");
    const { id, ...rest } = item; 
    const { data, error } = await supabase.from(table).insert(rest).select().single();
    if (error) throw error;
    return data as T;
}

const updateRow = async (table: string, id: number, updates: any): Promise<void> => {
    if (!supabase) return;
    const { error } = await supabase.from(table).update(updates).eq('id', id);
    if (error) throw error;
};

const deleteRow = async (table: string, id: number): Promise<void> => {
    if (!supabase) return;
    const { error } = await supabase.from(table).delete().eq('id', id);
    if (error) throw error;
};

// --- API EXPORT ---
export const db = {
  volunteers: {
    getAll: () => fetchAll<Volunteer>('volunteers'),
    create: (data: Omit<Volunteer, 'id'>) => insertItem<Volunteer>('volunteers', data),
    update: (id: number, data: Partial<Volunteer>) => updateRow('volunteers', id, data),
    delete: (id: number) => deleteRow('volunteers', id)
  },

  shifts: {
    getAll: () => fetchAll<Shift>('shifts'),
    create: (data: Omit<Shift, 'id'>) => insertItem<Shift>('shifts', data),
    update: (id: number, data: Partial<Shift>) => updateRow('shifts', id, data),
    delete: (id: number) => deleteRow('shifts', id)
  },

  crm: {
    getCampaigns: () => fetchAll<Campaign>('campaigns'),
    create: (data: Omit<Campaign, 'id'>) => insertItem<Campaign>('campaigns', data),
    update: (id: number, data: Partial<Campaign>) => updateRow('campaigns', id, data),
    delete: (id: number) => deleteRow('campaigns', id)
  },

  blog: {
    getPosts: () => fetchAll<BlogPost>('blog_posts'),
    create: (data: Omit<BlogPost, 'id' | 'publishDate'>) => insertItem<BlogPost>('blog_posts', { ...data, publishDate: new Date().toISOString() }),
    update: (id: number, data: Partial<BlogPost>) => updateRow('blog_posts', id, data),
    delete: (id: number) => deleteRow('blog_posts', id)
  },

  content: {
    // Using method shorthand syntax to correctly handle generics and avoid JSX ambiguity
    async get<T>(key: string, defaultVal: T): Promise<T> {
        if (!supabase) return defaultVal;
        const { data } = await supabase.from('settings').select('value').eq('key', key).single();
        return data ? data.value : defaultVal;
    },
    async set<T>(key: string, val: T): Promise<T> {
        if (!supabase) return val;
        const { data } = await supabase.from('settings').upsert({ key, value: val }).select().single();
        return data ? data.value : val;
    },
    getList<T>(key: string, defaultVal: T[]) {
         let table = key;
         if (key === 'hero_slides') table = 'hero_slides';
         if (key === 'content_services') table = 'services';
         if (key === 'donationNeeds') table = 'donation_needs';
         if (key === 'content_custom_pages') table = 'custom_pages';
         return fetchAll<T>(table, defaultVal);
    },
    createItem<T>(key: string, item: any) {
         let table = key === 'hero_slides' ? 'hero_slides' : key === 'content_services' ? 'services' : key === 'donationNeeds' ? 'donation_needs' : 'custom_pages';
         return insertItem<T>(table, item);
    },
    async updateItem<T extends {id: number}>(key: string, id: number, updates: Partial<T>) {
         let table = key === 'hero_slides' ? 'hero_slides' : key === 'content_services' ? 'services' : key === 'donationNeeds' ? 'donation_needs' : 'custom_pages';
         await updateRow(table, id, updates);
         return fetchAll<T>(table, []);
    },
    deleteItem(key: string, id: number) {
         let table = key === 'hero_slides' ? 'hero_slides' : key === 'content_services' ? 'services' : key === 'donationNeeds' ? 'donation_needs' : 'custom_pages';
         return deleteRow(table, id);
    }
  },

  messaging: {
    sendMail: async (to: string, subject: string, body: string) => {
        if (!supabase) return;
        return supabase.from('mail_queue').insert({ to_email: to, subject, body, status: 'pending' });
    },
    getQueue: async () => {
        if (!supabase) return [];
        const { data } = await supabase.from('mail_queue').select('*').order('created_at', { ascending: false });
        return data || [];
    }
  },

  auth: {
      login: async (username: string, pass: string) => {
        if (!supabase) return null;
        const { data } = await supabase.from('app_users').select('*').eq('username', username).eq('password', pass).single();
        if (!data && username === 'admin' && pass === 'admin') return { id: 1, username: 'admin', name: 'SuperAdmin', role: UserRole.SUPERADMIN };
        return data as User;
      },
      getUser: async () => {
          const u = localStorage.getItem('auth_user');
          return u ? JSON.parse(u) as User : null;
      },
      setUser: async (user: User | null) => {
          if(user) localStorage.setItem('auth_user', JSON.stringify(user));
          else localStorage.removeItem('auth_user');
      }
  }
};

