// --- SUPABASE HELPERS ---
// Using function declaration instead of arrow function for generics to avoid JSX ambiguity
async function fetchAll<T>(table: string, defaults: T[] = []): Promise<T[]> {
    if (!supabase) return defaults;
    const { data, error } = await supabase.from(table).select('*').order('id', { ascending: true });
    if (error) {
        console.error(`Error fetching ${table}:`, error);
        return defaults;
    }
    if (!data || data.length === 0) {
        if (table === 'hero_slides') return defaultSlides as unknown as T[];
        if (table === 'services') return defaultServices as unknown as T[];
        return defaults;
    }
    return data as T[];
}

// Using function declaration instead of arrow function for generics to avoid JSX ambiguity
async function insertItem<T>(table: string, item: any): Promise<T> {
    if (!supabase) throw new Error("Supabase no configurado");
    const { id, ...rest } = item; 
    const { data, error } = await supabase.from(table).insert(rest).select().single();
    if (error) throw error;
    return data as T;
}

const updateRow = async (table: string, id: number, updates: any): Promise<void> => {
    if (!supabase) return;
    const { error } = await supabase.from(table).update(updates).eq('id', id);
    if (error) throw error;
};

const deleteRow = async (table: string, id: number): Promise<void> => {
    if (!supabase) return;
    const { error } = await supabase.from(table).delete().eq('id', id);
    if (error) throw error;
};

