        root.style.setProperty(`--${prefix}-700`, adjustBrightness(baseColor, -0.2));
        root.style.setProperty(`--${prefix}-800`, adjustBrightness(baseColor, -0.3));
        root.style.setProperty(`--${prefix}-900`, adjustBrightness(baseColor, -0.45));
