// --- CORE FETCHERS WITH ERROR BOUNDARIES ---

async function safeFetch<T>(table: string, defaults: T[] = []): Promise<T[]> {
    if (!supabase) return defaults;
    try {
        const { data, error } = await supabase.from(table).select('*').order('id', { ascending: true });

        // Error code 42P01 is "relation does not exist" in Postgres
        if (error) {
            console.warn(`Supabase: La tabla "${table}" no existe o no es accesible. Usando datos locales.`);
            return defaults;
        }

        if (!data || data.length === 0) return defaults;
        return data as T[];
    } catch (e) {
        console.error(`Error crítico en safeFetch(${table}):`, e);
        return defaults;
    }
}

async function safeInsert<T>(table: string, item: any): Promise<T> {
    if (!supabase) throw new Error("Cliente Supabase no inicializado");
    // Remove ID for auto-increment tables if present
    const { id, ...payload } = item;
    const { data, error } = await supabase.from(table).insert(payload).select().single();
    if (error) {
        console.error(`Error insertando en ${table}:`, error);
        throw error;
    }
    return data as T;
}

