import { createClient, SupabaseClient } from '@supabase/supabase-js';

const SUPABASE_URL_KEY = 'vidayesperanza_supabase_url';
const SUPABASE_ANON_KEY_KEY = 'vidayesperanza_supabase_key';

export const getStoredCredentials = () => {
    return {
        url: localStorage.getItem(SUPABASE_URL_KEY)?.trim() || null,
        key: localStorage.getItem(SUPABASE_ANON_KEY_KEY)?.trim() || null
    };
};

export const setStoredCredentials = (url: string, key: string) => {
    const cleanUrl = url.trim().replace(/\/$/, ""); // Quitar slash final si existe
    const cleanKey = key.trim();

    if (!cleanUrl.startsWith('http')) {
        throw new Error("La URL del proyecto debe comenzar con http:// o https://");
    }

    localStorage.setItem(SUPABASE_URL_KEY, cleanUrl);
    localStorage.setItem(SUPABASE_ANON_KEY_KEY, cleanKey);

    // Usar reload directo es más seguro que reconstruir la URL manualmente
    window.location.reload();
};

export const clearCredentials = () => {
    localStorage.removeItem(SUPABASE_URL_KEY);
    localStorage.removeItem(SUPABASE_ANON_KEY_KEY);
    window.location.reload();
};

const initSupabase = (): SupabaseClient | null => {
    const creds = getStoredCredentials();
    if (!creds.url || !creds.key) return null;

    try {
        // Validación básica de URL
        new URL(creds.url); 
        return createClient(creds.url, creds.key);
    } catch (e) {
        console.error("Supabase Initialization Error:", e);
        return null;
    }
};

export const supabase = initSupabase();

