            <Heart className="absolute bottom-[-20px] left-10 text-white" size={200} />
        </div>
        <div className="container mx-auto px-6 relative z-10 text-center">
            <h1 className="text-4xl md:text-5xl font-extrabold mb-6">Quiero Ser Voluntaria</h1>
            <p className="text-xl text-emerald-100 max-w-3xl mx-auto font-light leading-relaxed">
              Únete a las mujeres que transforman el acompañamiento hospitalario en La Serena con amor, dignidad y esperanza.
            </p>
        </div>
      </div>

      {/* Contenedor Principal - CAPA SUPERIOR z-10 y relative */}
      <div className="container mx-auto px-6 lg:px-8 -mt-10 relative z-10">
        <div className="grid lg:grid-cols-12 gap-12 max-w-6xl mx-auto">

          {/* Columna de Información (4/12) */}
