interface SupabaseSetupProps {
    onConnected?: () => void;
}

export const SupabaseSetup: React.FC<SupabaseSetupProps> = ({ onConnected }) => {
    const [url, setUrl] = useState('');
    const [key, setKey] = useState('');
    const [error, setError] = useState<string | null>(null);

    const handleSave = (e: React.FormEvent) => {
        e.preventDefault();
        setError(null);

        if (!url || !key) {
            setError("Ambos campos son obligatorios.");
            return;
        }

        try {
            if (!url.includes('supabase.co') && !url.includes('localhost')) {
                setError("La URL parece no ser de un proyecto Supabase válido.");
                return;
            }

            setStoredCredentials(url, key);

            // Notificamos al componente padre en lugar de recargar la página
            if (onConnected) {
                onConnected();
            } else {
                window.location.reload();
            }
        } catch (err: any) {
            setError(err.message || "Error al guardar las credenciales.");
        }
    };

    return (
        <div className="min-h-screen bg-brand-900 flex items-center justify-center p-4">
            <div className="bg-white rounded-2xl shadow-2xl p-8 max-w-md w-full animate-fadeIn">
                <div className="flex items-center gap-3 mb-6 text-emerald-600">
                    <div className="p-2 bg-emerald-50 rounded-lg">
                        <Database size={32} />
                    </div>
                    <h1 className="text-2xl font-bold text-gray-800">Conectar Base de Datos</h1>
                </div>

                <p className="text-gray-600 mb-6 text-sm leading-relaxed">
                    Configura la conexión con tu proyecto de <strong>Supabase</strong>. Una vez guardado, el sistema quedará "blindado" y recordará tu conexión automáticamente.
                </p>

                {error && (
                    <div className="bg-red-50 border border-red-200 rounded-xl p-4 mb-6 flex gap-3 animate-pulse">
                        <XCircle className="text-red-600 flex-shrink-0" size={20} />
                        <p className="text-sm text-red-800 font-medium">{error}</p>
                    </div>
                )}

                <div className="bg-blue-50 border border-blue-200 rounded-xl p-4 mb-8 flex gap-3">
                    <AlertCircle className="text-blue-600 flex-shrink-0" size={20} />
                    <div className="text-xs text-blue-800">
                        <p className="font-bold mb-1">Paso Importante:</p>
                        Ejecuta el Script SQL en tu Dashboard de Supabase antes de ingresar estos datos.
                    </div>
                </div>

                <form onSubmit={handleSave} className="space-y-5">
                    <div>
                        <label className="block text-xs font-bold text-gray-500 uppercase mb-2 tracking-wider">Project URL</label>
                        <input 
                            type="text" 
                            required
                            value={url}
                            onChange={e => setUrl(e.target.value)}
                            placeholder="https://xyz.supabase.co"
                            className="w-full px-4 py-3 border border-gray-200 rounded-xl focus:ring-2 focus:ring-emerald-500 focus:border-emerald-500 outline-none transition-all text-sm font-mono"
                        />
                    </div>
                    <div>
                        <label className="block text-xs font-bold text-gray-500 uppercase mb-2 tracking-wider">API Key (anon/public)</label>
                        <input 
                            type="password" 
                            required
                            value={key}
                            onChange={e => setKey(e.target.value)}
                            placeholder="Introducir clave anónima..."
                            className="w-full px-4 py-3 border border-gray-200 rounded-xl focus:ring-2 focus:ring-emerald-500 focus:border-emerald-500 outline-none transition-all text-sm font-mono"
                        />
