};

import { createClient, SupabaseClient } from '@supabase/supabase-js';

// --- CAPA DE SEGURIDAD: CONSTANTES DE RESPALDO ---
const FALLBACK_URL = ''; 
const FALLBACK_KEY = ''; 

const SUPABASE_URL_KEY = 'vidayesperanza_supabase_url';
const SUPABASE_ANON_KEY_KEY = 'vidayesperanza_supabase_key';

export const getStoredCredentials = () => {
    const url = localStorage.getItem(SUPABASE_URL_KEY)?.trim() || FALLBACK_URL;
    const key = localStorage.getItem(SUPABASE_ANON_KEY_KEY)?.trim() || FALLBACK_KEY;
    return { url: url || null, key: key || null };
};

export const setStoredCredentials = (url: string, key: string) => {
    const cleanUrl = url.trim().replace(/\/$/, ""); 
    const cleanKey = key.trim();

    if (!cleanUrl.startsWith('http')) {
        throw new Error("La URL debe comenzar con http:// o https://");
    }

    localStorage.setItem(SUPABASE_URL_KEY, cleanUrl);
    localStorage.setItem(SUPABASE_ANON_KEY_KEY, cleanKey);
};

export const clearCredentials = () => {
    localStorage.removeItem(SUPABASE_URL_KEY);
    localStorage.removeItem(SUPABASE_ANON_KEY_KEY);
};

// Instancia interna para el Singleton
let internalInstance: SupabaseClient | null = null;

export const getSupabase = (): SupabaseClient | null => {
    const creds = getStoredCredentials();
    if (!creds.url || !creds.key) return null;

    // Si ya existe instancia y la URL coincide, la reutilizamos
    if (internalInstance && internalInstance.supabaseUrl === creds.url) {
        return internalInstance;
    }

    // Si no hay instancia o cambió la URL, creamos una nueva
    try {
        internalInstance = createClient(creds.url, creds.key, {
            auth: {
                persistSession: true,
                autoRefreshToken: true
            }
        });
        return internalInstance;
    } catch (e) {
        console.error("Critical Connection Error:", e);
        return null;
    }
};

// Exportamos una instancia inicial pero advertimos que debe usarse getSupabase()
export const supabase = getSupabase();

