// --- CORE FETCHERS ---
async function safeFetchMapped<T>(table: string, mapper: (raw: any) => T, defaults: T[] = []): Promise<T[]> {
    const client = getSupabase();
    if (!client) return defaults;
    try {
        const { data, error } = await client.from(table).select('*').order('id', { ascending: true });
        if (error || !data || data.length === 0) return defaults;
        return data.map(mapper);
    } catch (e) {
        console.error(`Error fetch en ${table}:`, e);
        return defaults;
    }
}

// --- API EXPORT ---
export const db = {
  system: {
      checkHealth: async (): Promise<{ ok: boolean; error?: string }> => {
          const client = getSupabase();
          if (!client) return { ok: false, error: "Cliente no inicializado" };
          try {
              const { error } = await client.from('settings').select('key').limit(1);
              if (error) return { ok: false, error: error.message };
              return { ok: true };
          } catch (e: any) {
              return { ok: false, error: e.message };
          }
      }
  },

  volunteers: {
    getAll: () => safeFetchMapped('volunteers', mappers.volunteer.toApp),
    create: async (data: Omit<Volunteer, 'id'>) => {
        const client = getSupabase();
        if (!client) throw new Error("DB No Connected");
        const { data: res, error } = await client.from('volunteers').insert(mappers.volunteer.toDB(data)).select().single();
        if (error) throw error;
        return mappers.volunteer.toApp(res);
    },
    update: async (id: number, updates: Partial<Volunteer>) => {
        const client = getSupabase();
        if (!client) return;
        await client.from('volunteers').update(mappers.volunteer.toDB(updates)).eq('id', id);
    },
    delete: async (id: number) => {
        const client = getSupabase();
        if (!client) return;
        await client.from('volunteers').delete().eq('id', id);
    }
  },

  shifts: {
    getAll: async () => {
        const client = getSupabase();
        if (!client) return [];
        const { data } = await client.from('shifts').select('*');
        return (data || []).map(raw => ({
            id: raw.id,
            volunteerId: raw.volunteer_id,
            date: raw.date,
            startTime: raw.start_time,
            endTime: raw.end_time,
            establishment: raw.establishment,
            hospital_unit: raw.hospital_unit,
            status: raw.status
        })) as unknown as Shift[];
    },
    create: async (data: Omit<Shift, 'id'>) => {
        const client = getSupabase();
        if (!client) throw new Error("DB No Connected");
        const { data: res, error } = await client.from('shifts').insert({
            volunteer_id: data.volunteerId,
            date: data.date,
            start_time: data.startTime,
            end_time: data.endTime,
            establishment: data.establishment,
            hospital_unit: data.hospitalUnit,
            status: data.status
        }).select().single();
        if (error) throw error;
        return { ...data, id: res.id };
    },
    update: async (id: number, updates: Partial<Shift>) => {
        const client = getSupabase();
        if (!client) return;
        const dbUpdates: any = {};
        if (updates.volunteerId) dbUpdates.volunteer_id = updates.volunteerId;
        if (updates.date) dbUpdates.date = updates.date;
        if (updates.startTime) dbUpdates.start_time = updates.startTime;
        if (updates.endTime) dbUpdates.end_time = updates.endTime;
        if (updates.status) dbUpdates.status = updates.status;
        await client.from('shifts').update(dbUpdates).eq('id', id);
    },
    delete: async (id: number) => {
        const client = getSupabase();
        if (!client) return;
        await client.from('shifts').delete().eq('id', id);
    }
  },

  crm: {
    getCampaigns: () => safeFetchMapped('campaigns', (raw) => ({
        id: raw.id,
        name: raw.name,
        objective: raw.objective,
        startDate: raw.start_date,
        endDate: raw.end_date,
        channel: raw.channel,
        targetAudience: raw.target_audience,
        status: raw.status,
        budget: raw.budget,
        notes: raw.notes
    })),
    create: async (data: Omit<Campaign, 'id'>) => {
        const client = getSupabase();
        if (!client) throw new Error("DB No Connected");
        const { data: res } = await client.from('campaigns').insert({
            name: data.name,
            objective: data.objective,
            start_date: data.startDate,
            end_date: data.endDate,
            channel: data.channel,
            target_audience: data.targetAudience,
            status: data.status,
            budget: data.budget,
            notes: data.notes
        }).select().single();
        return { ...data, id: res?.id };
    },
    update: async (id: number, updates: Partial<Campaign>) => {
        const client = getSupabase();
        if (!client) return;
        const dbUpdates: any = { ...updates };
        if (updates.startDate) dbUpdates.start_date = updates.startDate;
        if (updates.endDate) dbUpdates.end_date = updates.endDate;
        if (updates.targetAudience) dbUpdates.target_audience = updates.targetAudience;
        await client.from('campaigns').update(dbUpdates).eq('id', id);
    },
    delete: async (id: number) => {
        const client = getSupabase();
        if (!client) return;
        await client.from('campaigns').delete().eq('id', id);
    }
  },

  blog: {
    getPosts: () => safeFetchMapped('blog_posts', mappers.blog.toApp),
    getCategories: () => safeFetchMapped('blog_categories', mappers.category.toApp),
    getSubCategories: () => safeFetchMapped('blog_subcategories', mappers.subcategory.toApp),

    createCategory: async (data: Omit<BlogCategory, 'id'>) => {
        const client = getSupabase();
        if (!client) throw new Error("DB No Connected");
        const { data: res } = await client.from('blog_categories').insert(mappers.category.toDB(data)).select().single();
        return mappers.category.toApp(res);
    },

    createSubCategory: async (data: Omit<BlogSubCategory, 'id'>) => {
        const client = getSupabase();
        if (!client) throw new Error("DB No Connected");
        const { data: res } = await client.from('blog_subcategories').insert(mappers.subcategory.toDB(data)).select().single();
        return mappers.subcategory.toApp(res);
    },

    create: async (data: Omit<BlogPost, 'id' | 'publishDate'>) => {
        const client = getSupabase();
        if (!client) throw new Error("DB No Connected");
        const payload = mappers.blog.toDB({ ...data, publishDate: new Date().toISOString() } as BlogPost);
        const { data: res } = await client.from('blog_posts').insert(payload).select().single();
        return mappers.blog.toApp(res);
    },
    update: async (id: number, updates: Partial<BlogPost>) => {
        const client = getSupabase();
        if (!client) return;
        await client.from('blog_posts').update(mappers.blog.toDB(updates)).eq('id', id);
    },
    delete: async (id: number) => {
        const client = getSupabase();
        if (!client) return;
        await client.from('blog_posts').delete().eq('id', id);
    }
  },

  content: {
    async get<T>(key: string, defaultVal: T): Promise<T> {
        const client = getSupabase();
        if (!client) return defaultVal;
        try {
            const { data } = await client.from('settings').select('value').eq('key', key).maybeSingle();
            return data ? data.value : defaultVal;
        } catch {
            return defaultVal;
        }
    },
    async set<T>(key: string, value: T): Promise<T> {
        const client = getSupabase();
        if (!client) return value;
        await client.from('settings').upsert({ key, value });
        return value;
    },
    async getList<T>(key: string, defaultVal: T[]): Promise<T[]> {
        const client = getSupabase();
        if (!client) return defaultVal;
        if (key === 'hero_slides') return await safeFetchMapped('hero_slides', mappers.slide.toApp, defaultVal as any) as any;
        if (key === 'donationNeeds') return await safeFetchMapped('donation_needs', mappers.donation.toApp, defaultVal as any) as any;
        if (key === 'content_services') {
            const { data } = await client.from('services').select('*').order('id');
            return (data || defaultVal) as T[];
        }
        if (key === 'content_custom_pages') {
            const { data } = await client.from('custom_pages').select('*');
            return (data || []).map(raw => ({
                id: raw.id,
                slug: raw.slug,
                title: raw.title,
                content: raw.content,
                isVisible: raw.is_visible,
                lastModified: raw.last_modified
            })) as any;
        }
        return defaultVal;
    },
    async createItem<T>(key: string, item: any): Promise<T> {
        const client = getSupabase();
        if (!client) throw new Error("DB No Connected");
        let table = key;
        let payload = item;
        if (key === 'hero_slides') { table = 'hero_slides'; payload = mappers.slide.toDB(item); }
        if (key === 'donationNeeds') { table = 'donation_needs'; payload = mappers.donation.toDB(item); }
        if (key === 'content_services') table = 'services';
        if (key === 'content_custom_pages') {
            table = 'custom_pages';
            payload = { slug: item.slug, title: item.title, content: item.content, is_visible: item.isVisible };
        }

        const { data, error } = await client.from(table).insert(payload).select().single();
        if (error) throw error;

        if (key === 'hero_slides') return mappers.slide.toApp(data) as any;
        if (key === 'donationNeeds') return mappers.donation.toApp(data) as any;
        return data;
    },
    async updateItem<T extends {id: number}>(key: string, id: number, updates: Partial<T>): Promise<T[]> {
        const client = getSupabase();
        if (!client) return [];
        let table = key;
        let payload = updates as any;
        if (key === 'hero_slides') { table = 'hero_slides'; payload = mappers.slide.toDB(updates as any); }
        if (key === 'donationNeeds') { table = 'donation_needs'; payload = mappers.donation.toDB(updates as any); }
        if (key === 'content_services') table = 'services';
        if (key === 'content_custom_pages') {
            table = 'custom_pages';
            payload = { ...updates };
            if (updates.hasOwnProperty('isVisible')) {
                (payload as any).is_visible = (updates as any).isVisible;
                delete (payload as any).isVisible;
            }
        }

        await client.from(table).update(payload).eq('id', id);
        return db.content.getList<T>(key, []);
    },
    async deleteItem(key: string, id: number): Promise<void> {
        const client = getSupabase();
        if (!client) return;
        const tableMap: Record<string, string> = {
            'hero_slides': 'hero_slides',
            'content_services': 'services',
            'donationNeeds': 'donation_needs',
            'content_custom_pages': 'custom_pages'
        };
        await client.from(tableMap[key] || key).delete().eq('id', id);
    }
  },

  auth: {
      login: async (username: string, pass: string): Promise<User | null> => {
        const client = getSupabase();
        if (!client) return null;
        try {
            const { data } = await client.from('app_users').select('*').eq('username', username).eq('password', pass).maybeSingle();
            if (!data && username === 'admin' && pass === 'admin') 
                return { id: 1, username: 'admin', name: 'SuperAdmin', role: UserRole.SUPERADMIN };
            return data ? {
                id: data.id,
                username: data.username,
                name: data.name,
                role: data.role,
                volunteerId: data.volunteer_id
            } : null;
        } catch {
            return null;
        }
      },
      getUser: async (): Promise<User | null> => {
          const u = localStorage.getItem('auth_user');
          return u ? JSON.parse(u) as User : null;
      },
      setUser: async (user: User | null): Promise<void> => {
          if(user) localStorage.setItem('auth_user', JSON.stringify(user));
          else localStorage.removeItem('auth_user');
      }
  }
};

import React, { useState, useEffect, useRef } from 'react';
import { 
  ArrowLeft, Plus, Edit2, Trash2, Save, X, Image as ImageIcon, 
  Type, MousePointer2, MoveDown, MoveUp, Layers, Settings, Tag, 
  FolderPlus, ChevronRight, FileText, Layout, Upload, Check
} from 'lucide-react';
import { useBlog } from '../../context/BlogContext';
import { BlogPost, BlogPostStatus, BlogBlock, BlogBlockType, BlogCategory, BlogSubCategory } from '../../types';

interface AdminBlogProps {
  onBack: () => void;
}

export const AdminBlog: React.FC<AdminBlogProps> = ({ onBack }) => {
  const { 
    posts, categories, subCategories, addPost, updatePost, deletePost, 
    addCategory, addSubCategory 
  } = useBlog();

  const [activeView, setActiveView] = useState<'posts' | 'categories' | 'editor'>('posts');
  const [editingPostId, setEditingPostId] = useState<number | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // --- Form States ---
  const [postMeta, setPostMeta] = useState({
    title: '',
    slug: '',
    excerpt: '',
    coverImage: '',
    author: 'Coordinación Vida y Esperanza',
    status: BlogPostStatus.DRAFT,
    categoryId: undefined as number | undefined,
    subCategoryId: undefined as number | undefined,
    tags: ''
  });

  const [blocks, setBlocks] = useState<BlogBlock[]>([]);
  const [newCatName, setNewCatName] = useState('');

  // --- Image Processing ---
  const processFile = (file: File): Promise<string> => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onload = () => resolve(reader.result as string);
      reader.onerror = reject;
      reader.readAsDataURL(file);
    });
  };

  const handleCoverUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      try {
        const base64 = await processFile(file);
        setPostMeta(prev => ({ ...prev, coverImage: base64 }));
      } catch (err) {
        alert("Error al procesar la imagen");
      }
    }
  };

  const handleBlockImageUpload = async (id: string, e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      try {
        const base64 = await processFile(file);
        updateBlock(id, { mediaUrl: base64 });
      } catch (err) {
        alert("Error al procesar la imagen");
      }
    }
  };

  // --- Functions ---
  const generateSlug = (text: string) => text.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)+/g, '');

  const handleEditPost = (post: BlogPost) => {
    setPostMeta({
      title: post.title,
      slug: post.slug,
      excerpt: post.excerpt,
      coverImage: post.coverImage,
      author: post.author,
      status: post.status,
      categoryId: post.categoryId,
      subCategoryId: post.subCategoryId,
      tags: post.tags.join(', ')
    });
    try {
        setBlocks(JSON.parse(post.content));
    } catch (e) {
        setBlocks([{ id: Date.now().toString(), type: 'text', content: post.content }]);
    }
    setEditingPostId(post.id);
    setActiveView('editor');
  };

  const handleCreatePost = () => {
    setPostMeta({
      title: '',
      slug: '',
      excerpt: '',
      coverImage: '',
      author: 'Coordinación Vida y Esperanza',
      status: BlogPostStatus.DRAFT,
      categoryId: categories[0]?.id,
      subCategoryId: undefined,
      tags: ''
    });
    setBlocks([{ id: Date.now().toString(), type: 'text', content: '<p>Empieza a escribir aquí...</p>' }]);
    setEditingPostId(null);
    setActiveView('editor');
  };

  const addBlock = (type: BlogBlockType) => {
    const newBlock: BlogBlock = {
        id: Math.random().toString(36).substr(2, 9),
        type,
        content: type === 'text' ? '<p>Nuevo párrafo...</p>' : '',
        mediaUrl: '',
        caption: '',
        linkUrl: '',
        buttonStyle: 'primary'
    };
    setBlocks([...blocks, newBlock]);
  };

  const updateBlock = (id: string, updates: Partial<BlogBlock>) => {
    setBlocks(blocks.map(b => b.id === id ? { ...b, ...updates } : b));
  };

  const moveBlock = (index: number, direction: 'up' | 'down') => {
    const newBlocks = [...blocks];
    const target = direction === 'up' ? index - 1 : index + 1;
    if (target < 0 || target >= newBlocks.length) return;
    [newBlocks[index], newBlocks[target]] = [newBlocks[target], newBlocks[index]];
    setBlocks(newBlocks);
  };

  const deleteBlock = (id: string) => setBlocks(blocks.filter(b => b.id !== id));

  const handleSavePost = async (e: React.FormEvent) => {
    e.preventDefault();
    const finalData = {
        title: postMeta.title,
        slug: postMeta.slug || generateSlug(postMeta.title),
        excerpt: postMeta.excerpt,
        content: JSON.stringify(blocks),
        coverImage: postMeta.coverImage,
        author: postMeta.author,
        status: postMeta.status,
        tags: postMeta.tags.split(',').map(t => t.trim()).filter(Boolean),
        categoryId: postMeta.categoryId,
        subCategoryId: postMeta.subCategoryId
    };

    if (editingPostId) {
        await updatePost(editingPostId, finalData);
    } else {
        await addPost(finalData);
    }
    setActiveView('posts');
  };

  const handleAddCategory = async () => {
    if (!newCatName) return;
    await addCategory({ name: newCatName, slug: generateSlug(newCatName) });
    setNewCatName('');
  };

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col md:flex-row">
      {/* SIDEBAR ADMINISTRATIVO (WordPress Style) */}
      <aside className="w-full md:w-64 bg-emerald-900 text-white p-6 flex-shrink-0">
        <div className="flex items-center gap-3 mb-10 pb-4 border-b border-white/10">
            <Layout className="text-emerald-400" />
            <h1 className="font-bold text-lg">Panel de Blog</h1>
        </div>
        <nav className="space-y-1">
            <button 
                onClick={() => setActiveView('posts')}
                className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-medium transition ${activeView === 'posts' ? 'bg-white/10 text-white shadow-inner' : 'text-emerald-100 hover:bg-white/5'}`}
            >
                <FileText size={18} /> Entradas
            </button>
            <button 
                onClick={() => setActiveView('categories')}
                className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-medium transition ${activeView === 'categories' ? 'bg-white/10 text-white shadow-inner' : 'text-emerald-100 hover:bg-white/5'}`}
            >
                <Layers size={18} /> Categorías
            </button>
            <div className="pt-8 px-4">
                <p className="text-[10px] font-bold text-emerald-400 uppercase tracking-widest mb-4">Ayuda Técnica</p>
                <div className="text-[11px] text-emerald-200/60 leading-relaxed space-y-2">
                    <p>• Portada: 1200x630px</p>
                    <p>• Bloques: 800px ancho</p>
                    <p>• Las imágenes se guardan en el sistema automáticamente.</p>
                </div>
            </div>
        </nav>
      </aside>

      {/* ÁREA DE TRABAJO */}
      <main className="flex-1 p-6 md:p-10 overflow-y-auto">

        {/* VISTA: LISTA DE ENTRADAS */}
        {activeView === 'posts' && (
            <div className="animate-fadeIn">
                <div className="flex justify-between items-center mb-10">
                    <div>
                        <h2 className="text-3xl font-extrabold text-gray-900">Entradas del Blog</h2>
                        <p className="text-gray-500">Gestiona todos los artículos y noticias de la plataforma.</p>
                    </div>
                    <button 
                        onClick={handleCreatePost}
                        className="bg-emerald-600 text-white px-6 py-3 rounded-2xl font-bold flex items-center gap-2 shadow-xl shadow-emerald-100 hover:bg-emerald-700 transition active:scale-95"
                    >
                        <Plus size={20} /> Crear Nueva Entrada
                    </button>
                </div>

                <div className="grid gap-4">
                    {posts.map(post => (
                        <div key={post.id} className="bg-white p-4 rounded-3xl shadow-sm border border-gray-100 flex items-center gap-4 hover:shadow-lg transition group">
                            <div className="w-20 h-20 bg-gray-100 rounded-2xl overflow-hidden flex-shrink-0">
                                <img src={post.coverImage || 'https://via.placeholder.com/200?text=Sin+Imagen'} className="w-full h-full object-cover" />
                            </div>
                            <div className="flex-1">
                                <div className="flex items-center gap-2 mb-1">
                                    <h3 className="font-bold text-gray-900 group-hover:text-emerald-600 transition-colors">{post.title}</h3>
                                    <span className={`text-[10px] px-2 py-0.5 rounded-full font-bold uppercase border ${
                                        post.status === 'Publicado' ? 'bg-emerald-50 text-emerald-700 border-emerald-100' : 'bg-yellow-50 text-yellow-700 border-yellow-100'
                                    }`}>
