                                </div>
                                <div className="flex items-center gap-4 text-xs text-gray-400">
                                    <span className="flex items-center gap-1"><FolderPlus size={12}/> {categories.find(c => c.id === post.categoryId)?.name || 'Sin Categoría'}</span>
                                    <span>{new Date(post.publishDate).toLocaleDateString()}</span>
                                </div>
                            </div>
                            <div className="flex items-center gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                                <button onClick={() => handleEditPost(post)} className="p-2 bg-gray-50 text-emerald-600 rounded-xl hover:bg-emerald-100"><Edit2 size={18}/></button>
