        {/* VISTA: CATEGORÍAS */}
        {activeView === 'categories' && (
            <div className="animate-fadeIn max-w-4xl">
                 <h2 className="text-3xl font-extrabold text-gray-900 mb-2">Categorías</h2>
                 <p className="text-gray-500 mb-10">Organiza tus contenidos jerárquicamente para una mejor navegación.</p>

                 <div className="grid md:grid-cols-2 gap-10">
                    <div className="bg-white p-8 rounded-3xl shadow-sm border border-gray-100">
                        <h3 className="font-bold text-gray-800 mb-6 flex items-center gap-2"><Plus size={20} className="text-emerald-600"/> Nueva Categoría</h3>
                        <div className="space-y-4">
                            <input 
                                type="text" placeholder="Nombre de categoría..." value={newCatName} onChange={e => setNewCatName(e.target.value)}
                                className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-2xl focus:ring-2 focus:ring-emerald-500 outline-none"
                            />
                            <button onClick={handleAddCategory} className="w-full bg-emerald-600 text-white py-3 rounded-2xl font-bold shadow-lg shadow-emerald-100">Crear Categoría</button>
                        </div>
                    </div>

                    <div className="space-y-3">
                        {categories.map(cat => (
