                    {/* Header Editor */}
                    <div className="lg:col-span-12 flex justify-between items-center mb-4">
                         <button type="button" onClick={() => setActiveView('posts')} className="flex items-center gap-2 text-gray-500 hover:text-emerald-600 font-bold">
                            <ArrowLeft size={20}/> Volver a lista
                         </button>
                         <div className="flex gap-3">
                             <button type="submit" className="bg-emerald-600 text-white px-8 py-3 rounded-2xl font-bold flex items-center gap-2 shadow-xl shadow-emerald-100 active:scale-95 transition">
