                                            <button type="button" onClick={() => moveBlock(idx, 'down')} className="p-1.5 bg-white border border-gray-200 rounded-lg text-gray-400 hover:text-emerald-600 shadow-sm"><MoveDown size={14}/></button>
                                        </div>

                                        {/* Block Content Inputs */}
                                        {block.type === 'text' && (
                                            <textarea 
                                                className="w-full bg-transparent border-none outline-none prose prose-emerald text-gray-800 leading-relaxed font-serif"
