                                                        <div className="flex-1 relative">
                                                            <ImageIcon size={14} className="absolute left-3 top-3.5 text-gray-400" />
                                                            <input 
                                                                type="text" placeholder="O pega URL de imagen..." value={block.mediaUrl.startsWith('data:') ? 'Imagen cargada localmente' : block.mediaUrl} 
                                                                onChange={e => updateBlock(block.id, { mediaUrl: e.target.value })}
                                                                className="w-full pl-9 pr-4 py-3 bg-white border border-gray-200 rounded-xl text-xs focus:ring-2 focus:ring-emerald-500 outline-none"
                                                                disabled={block.mediaUrl.startsWith('data:')}
                                                            />
                                                            {block.mediaUrl.startsWith('data:') && (
