import { createClient, SupabaseClient } from '@supabase/supabase-js';

// --- CAPA DE SEGURIDAD: CONSTANTES DE RESPALDO ---
const FALLBACK_URL = ''; 
const FALLBACK_KEY = ''; 

const SUPABASE_URL_KEY = 'vidayesperanza_supabase_url';
const SUPABASE_ANON_KEY_KEY = 'vidayesperanza_supabase_key';

export const getStoredCredentials = () => {
    const url = localStorage.getItem(SUPABASE_URL_KEY)?.trim() || FALLBACK_URL;
    const key = localStorage.getItem(SUPABASE_ANON_KEY_KEY)?.trim() || FALLBACK_KEY;
    return { url: url || null, key: key || null };
};

export const setStoredCredentials = (url: string, key: string) => {
    const cleanUrl = url.trim().replace(/\/$/, ""); 
    const cleanKey = key.trim();

    if (!cleanUrl.startsWith('http')) {
        throw new Error("La URL debe comenzar con http:// o https://");
    }

    localStorage.setItem(SUPABASE_URL_KEY, cleanUrl);
    localStorage.setItem(SUPABASE_ANON_KEY_KEY, cleanKey);
    // Dispara un evento para que otras pestañas (como App.tsx) puedan reaccionar
    window.dispatchEvent(new Event('storage'));
};

export const clearCredentials = () => {
    localStorage.removeItem(SUPABASE_URL_KEY);
    localStorage.removeItem(SUPABASE_ANON_KEY_KEY);
    // Dispara un evento para que otras pestañas reaccionen al logout de credenciales
    window.dispatchEvent(new Event('storage'));
};

// Instancia interna para el Singleton
let internalInstance: SupabaseClient | null = null;

export const getSupabase = (): SupabaseClient | null => {
    const creds = getStoredCredentials();
    if (!creds.url || !creds.key) {
        internalInstance = null;
        return null;
    }

    // Si ya existe instancia y la URL coincide, la reutilizamos
    if (internalInstance && internalInstance.supabaseUrl === creds.url) {
        return internalInstance;
    }

    // Si no hay instancia o cambió la URL, creamos una nueva
    try {
        internalInstance = createClient(creds.url, creds.key, {
            auth: {
                persistSession: true,
                autoRefreshToken: true
            }
        });
        return internalInstance;
    } catch (e) {
        console.error("Critical Connection Error:", e);
        internalInstance = null;
        return null;
    }
};

/**
 * Función para probar una conexión a Supabase con credenciales temporales.
 * No guarda nada, solo valida que la conexión es posible.
 */
export const testSupabaseConnection = async (url: string, key: string): Promise<{ ok: boolean; error?: string }> => {
    try {
        const cleanUrl = url.trim().replace(/\/$/, ""); 
        const cleanKey = key.trim();

        if (!cleanUrl || !cleanKey) {
            return { ok: false, error: "La URL y la Clave API no pueden estar vacías." };
        }

        const testClient = createClient(cleanUrl, cleanKey);

        // Intentamos una consulta simple. Si la tabla 'settings' no es pública, fallará.
        // Pero el tipo de error nos dirá si es un problema de autenticación o de otro tipo.
        const { error } = await testClient.from('settings').select('key').limit(1);

        if (error && (error.message.includes('JWT') || error.message.includes('API key'))) {
            return { ok: false, error: "La clave API (anon key) parece ser inválida." };
        }

        // Si hay otro error, podría ser la URL, la red o que la tabla no existe (lo cual es un problema de setup, no de conexión)
        // No mostraremos errores de "tabla no existe" aquí, sino que lo consideraremos una conexión exitosa a nivel de red/auth.
        if (error && !error.message.includes('relation "public.settings" does not exist')) {
            return { ok: false, error: `Fallo la conexión: ${error.message}. Revisa la URL y tu conexión a internet.` };
        }

        return { ok: true };
    } catch (e: any) {
        return { ok: false, error: `Error de conexión: ${e.message}` };
    }
};

