const App: React.FC = () => {
  const [connectionStatus, setConnectionStatus] = useState<'checking' | 'connected' | 'setup'>('checking');

  useEffect(() => {
    const verifyConnection = async () => {
        const creds = getStoredCredentials();
        if (!creds.url || !creds.key) {
            setConnectionStatus('setup');
            return;
        }

        // Forzamos la creación de una instancia para el chequeo
        getSupabase(); 
        const health = await db.system.checkHealth();

        if (health.ok) {
            setConnectionStatus('connected');
        } else {
            console.warn("Health check failed with stored credentials:", health.error);
            clearCredentials();
            setConnectionStatus('setup');
        }
    };

    verifyConnection();

    // Escuchamos si las credenciales cambian en otra parte (ej. al guardar en setup o al hacer clear en settings)
    const handleStorageChange = () => {
        setConnectionStatus('checking'); // Re-evaluar la conexión
        verifyConnection();
    };
    window.addEventListener('storage', handleStorageChange);

    return () => window.removeEventListener('storage', handleStorageChange);
  }, []);

  if (connectionStatus === 'checking') {
      return <FullPageLoader title="Verificando Conexión" subtitle="Estableciendo un enlace seguro con la base de datos..." />;
  }

  if (connectionStatus === 'setup') {
      return <SupabaseSetup onConnected={() => setConnectionStatus('connected')} />;
  }

  return (
    <AuthProvider>
      <ContentProvider>
        <CRMProvider>
          <VolunteerProvider>
            <BlogProvider>
                <AppRoutes />
            </BlogProvider>
          </VolunteerProvider>
        </CRMProvider>
      </ContentProvider>
    </AuthProvider>
  );
};

export default App;

