const App: React.FC = () => {
  const [connectionStatus, setConnectionStatus] = useState<'checking' | 'connected' | 'setup'>('checking');

  useEffect(() => {
    // Lógica de "Confiar Primero": si hay credenciales, la app se considera conectada.
    // Jamás se desconectará a menos que el usuario lo haga explícitamente.
    const verifyConnection = () => {
        const creds = getStoredCredentials();
        if (creds.url && creds.key) {
            // Se asume que la conexión es válida y persistente. No se realiza un health check activo.
            // Si las credenciales son incorrectas, las llamadas a la DB fallarán, pero la UI no se romperá.
            setConnectionStatus('connected');
        } else {
            // Solo se muestra el setup si NO existen credenciales.
            setConnectionStatus('setup');
        }
    };

    verifyConnection();

    // Este listener es clave: si el usuario borra las credenciales desde el panel de ajustes,
    // la app reaccionará y volverá a la pantalla de configuración.
    const handleStorageChange = () => {
        verifyConnection();
    };
    window.addEventListener('storage', handleStorageChange);

    return () => window.removeEventListener('storage', handleStorageChange);
  }, []);

  if (connectionStatus === 'checking') {
      return <FullPageLoader title="Estableciendo Conexión" subtitle="Verificando credenciales permanentes..." />;
  }

  if (connectionStatus === 'setup') {
      return <SupabaseSetup onConnected={() => setConnectionStatus('connected')} />;
  }

  return (
    <AuthProvider>
      <ContentProvider>
        <CRMProvider>
          <VolunteerProvider>
            <BlogProvider>
                <AppRoutes />
            </BlogProvider>
          </VolunteerProvider>
        </CRMProvider>
      </ContentProvider>
    </AuthProvider>
  );
};

