// --- CORE FETCHERS ---
async function safeFetchMapped<T>(table: string, mapper: (raw: any) => T, defaults: T[] = []): Promise<T[]> {
    const client = getSupabase();
    if (!client) return defaults;

    const { data, error } = await client.from(table).select('*').order('id', { ascending: true });

    // If there's an error (like table not found), we throw it.
    // This allows Promise.allSettled in contexts to correctly identify a failed fetch,
    // preventing incorrect follow-up actions like trying to seed a non-existent table.
    if (error) {
        throw error;
    }

    // If data is null/undefined but no error, return default (usually an empty array).
    if (!data) {
        return defaults;
    }

    return data.map(mapper);
}

