            return (data || defaultVal) as T[];
        }
        if (key === 'content_custom_pages') {
            const { data } = await client.from('custom_pages').select('*');
            return (data || []).map(raw => ({
                id: raw.id,
                slug: raw.slug,
                title: raw.title,
                content: raw.content,
                isVisible: raw.is_visible,
                lastModified: raw.last_modified
            })) as any;
        }
        return defaultVal;
    },
    async createItem<T>(key: string, item: any): Promise<T> {
        const client = getSupabase();
        if (!client) throw new Error("DB No Connected");
        let table = key;
        let payload = item;
        if (key === 'hero_slides') { table = 'hero_slides'; payload = mappers.slide.toDB(item); }
        if (key === 'donationNeeds') { table = 'donation_needs'; payload = mappers.donation.toDB(item); }
        if (key === 'content_services') table = 'services';
        if (key === 'content_custom_pages') {
            table = 'custom_pages';
            payload = { slug: item.slug, title: item.title, content: item.content, is_visible: item.isVisible };
        }

        const { data, error } = await client.from(table).insert(payload).select().single();
        if (error) throw error;

        if (key === 'hero_slides') return mappers.slide.toApp(data) as any;
        if (key === 'donationNeeds') return mappers.donation.toApp(data) as any;
        return data;
    },
    async updateItem<T extends {id: number}>(key: string, id: number, updates: Partial<T>): Promise<T[]> {
        const client = getSupabase();
        if (!client) return [];
        let table = key;
        let payload = updates as any;
        if (key === 'hero_slides') { table = 'hero_slides'; payload = mappers.slide.toDB(updates as any); }
        if (key === 'donationNeeds') { table = 'donation_needs'; payload = mappers.donation.toDB(updates as any); }
        if (key === 'content_services') table = 'services';
        if (key === 'content_custom_pages') {
            table = 'custom_pages';
            payload = { ...updates };
            if (updates.hasOwnProperty('isVisible')) {
                (payload as any).is_visible = (updates as any).isVisible;
                delete (payload as any).isVisible;
            }
        }

        const { error } = await client.from(table).update(payload).eq('id', id);
        if (error) throw error;
        return db.content.getList<T>(key, []);
    },
    async deleteItem(key: string, id: number): Promise<void> {
        const client = getSupabase();
        if (!client) return;
        const tableMap: Record<string, string> = {
            'hero_slides': 'hero_slides',
            'content_services': 'services',
            'donationNeeds': 'donation_needs',
            'content_custom_pages': 'custom_pages'
        };
        await client.from(tableMap[key] || key).delete().eq('id', id);
    }
  },

  auth: {
      login: async (username: string, pass: string): Promise<User | null> => {
        const client = getSupabase();
        if (!client) return null;
        try {
            const { data } = await client.from('app_users').select('*').eq('username', username).eq('password', pass).maybeSingle();

            // FALLBACK PARA DEMO (Si no existen en la DB aún)
            if (!data) {
                if (username === 'admin' && pass === 'admin') 
                    return { id: 1, username: 'admin', name: 'SuperAdmin', role: UserRole.SUPERADMIN };
                if (username === 'colab' && pass === 'colab') 
                    return { id: 2, username: 'colab', name: 'Colaborador Demo', role: UserRole.COLLABORATOR };
                if (username === 'vol' && pass === 'vol') 
                    return { id: 3, username: 'vol', name: 'Voluntaria Demo', role: UserRole.VOLUNTEER, volunteerId: 1 };
                return null;
            }

            return {
                id: data.id,
                username: data.username,
                name: data.name,
                role: data.role,
                volunteerId: data.volunteer_id
            };
        } catch {
            return null;
        }
      },
      getUser: async (): Promise<User | null> => {
          const u = localStorage.getItem('auth_user');
          return u ? JSON.parse(u) as User : null;
      },
      setUser: async (user: User | null): Promise<void> => {
          if(user) localStorage.setItem('auth_user', JSON.stringify(user));
          else localStorage.removeItem('auth_user');
      }
  }
};

import React, { createContext, useContext, useState, useEffect } from 'react';
import { Volunteer, VolunteerStatus, Shift } from '../types';
import { db } from '../services/db';

interface VolunteerContextType {
  volunteers: Volunteer[];
  shifts: Shift[];
  loading: boolean;
  addVolunteer: (vol: Partial<Volunteer>) => Promise<void>;
  updateVolunteerStatus: (id: number, status: VolunteerStatus) => Promise<void>;
  updateVolunteerDetails: (id: number, details: Partial<Volunteer>) => Promise<void>;
  getVolunteerStats: () => { active: number; pending: number; totalHours: number };
  addShift: (shift: Omit<Shift, 'id'>) => Promise<void>;
  updateShift: (id: number, shift: Partial<Shift>) => Promise<void>;
  deleteShift: (id: number) => Promise<void>;
  getShiftsByVolunteer: (volunteerId: number) => Shift[];
}

const VolunteerContext = createContext<VolunteerContextType | undefined>(undefined);

export const VolunteerProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [volunteers, setVolunteers] = useState<Volunteer[]>([]);
  const [shifts, setShifts] = useState<Shift[]>([]);
  const [loading, setLoading] = useState(true);

  // Initial Load from DB
  useEffect(() => {
    const loadData = async () => {
        try {
            const [vols, shfts] = await Promise.all([
                db.volunteers.getAll(),
                db.shifts.getAll()
            ]);
            setVolunteers(vols);
            setShifts(shfts);
        } catch (error) {
            console.error("Failed to load volunteer data", error);
        } finally {
            setLoading(false);
        }
    };
    loadData();
  }, []);

  const addVolunteer = async (volData: Partial<Volunteer>) => {
    const newVol = await db.volunteers.create({
      fullName: volData.fullName || '',
      email: volData.email || '',
      phone: volData.phone || '',
      establishment: volData.establishment || '',
      hospitalUnit: volData.hospitalUnit || undefined,
      location: volData.location || '',
      group: volData.group || undefined,
      motivation: volData.motivation || '',
      status: volData.status || VolunteerStatus.PENDING,
      hoursThisMonth: volData.hoursThisMonth || 0,
      joinDate: new Date().toISOString().split('T')[0]
    } as Omit<Volunteer, 'id'>);

    setVolunteers(prev => [...prev, newVol]);
  };

  const updateVolunteerStatus = async (id: number, status: VolunteerStatus) => {
    await db.volunteers.update(id, { status });
    setVolunteers(prev => prev.map(v => v.id === id ? { ...v, status } : v));
  };

  const updateVolunteerDetails = async (id: number, details: Partial<Volunteer>) => {
    await db.volunteers.update(id, details);
    setVolunteers(prev => prev.map(v => v.id === id ? { ...v, ...details } : v));
  };

  const getVolunteerStats = () => {
    return {
      active: volunteers.filter(v => v.status === VolunteerStatus.ACTIVE).length,
      pending: volunteers.filter(v => v.status === VolunteerStatus.PENDING).length,
      totalHours: volunteers.reduce((acc, curr) => acc + curr.hoursThisMonth, 0)
    };
  };

  const addShift = async (shift: Omit<Shift, 'id'>) => {
    const newShift = await db.shifts.create(shift);
    setShifts(prev => [...prev, newShift]);
  };

  const updateShift = async (id: number, shift: Partial<Shift>) => {
    await db.shifts.update(id, shift);
    setShifts(prev => prev.map(s => s.id === id ? { ...s, ...shift } : s));
  };

  const deleteShift = async (id: number) => {
    try {
      await db.shifts.delete(id);
      setShifts(prev => prev.filter(s => s.id !== id));
    } catch (error) {
        console.error("Error al eliminar el turno:", error);
        alert("Ocurrió un error al intentar eliminar el turno. Por favor, inténtelo de nuevo.");
    }
  };

  const getShiftsByVolunteer = (volunteerId: number) => {
    return shifts.filter(s => s.volunteerId === volunteerId).sort((a,b) => a.date.localeCompare(b.date));
  };

  return (
    <VolunteerContext.Provider value={{ 
      volunteers, 
      shifts,
      loading,
      addVolunteer, 
      updateVolunteerStatus, 
      updateVolunteerDetails,
      getVolunteerStats,
      addShift,
      updateShift,
      deleteShift,
      getShiftsByVolunteer
    }}>
      {children}
    </VolunteerContext.Provider>
  );
};

export const useVolunteer = () => {
  const context = useContext(VolunteerContext);
  if (!context) throw new Error('useVolunteer must be used within a VolunteerProvider');
  return context;
};

import React, { createContext, useContext, useState, useEffect } from 'react';
import { BlogPost, BlogPostStatus, BlogCategory, BlogSubCategory } from '../types';
import { db } from '../services/db';

interface BlogContextType {
  posts: BlogPost[];
  categories: BlogCategory[];
  subCategories: BlogSubCategory[];
  loading: boolean;
  addPost: (post: Omit<BlogPost, 'id' | 'publishDate'>) => Promise<void>;
  updatePost: (id: number, post: Partial<BlogPost>) => Promise<void>;
  deletePost: (id: number) => Promise<void>;
  addCategory: (cat: Omit<BlogCategory, 'id'>) => Promise<void>;
  addSubCategory: (sub: Omit<BlogSubCategory, 'id'>) => Promise<void>;
  getPublishedPosts: (categoryId?: number, subCategoryId?: number) => BlogPost[];
  getPostById: (id: number) => BlogPost | undefined;
  getPostBySlug: (slug: string) => BlogPost | undefined;
}

const BlogContext = createContext<BlogContextType | undefined>(undefined);

export const BlogProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [posts, setPosts] = useState<BlogPost[]>([]);
  const [categories, setCategories] = useState<BlogCategory[]>([]);
  const [subCategories, setSubCategories] = useState<BlogSubCategory[]>([]);
  const [loading, setLoading] = useState(true);

  const loadData = async () => {
    setLoading(true);
    try {
        const results = await Promise.allSettled([
            db.blog.getPosts(),
            db.blog.getCategories(),
            db.blog.getSubCategories()
        ]);

        // Helper to gracefully handle "table not found" errors, which are expected in a new setup
        const getResultOrEmpty = <T,>(result: PromiseSettledResult<T[]>, tableName: string): T[] => {
            if (result.status === 'fulfilled') {
                return result.value;
            }

            const reason = result.reason as Error;
            if (reason && reason.message && (reason.message.includes('does not exist') || reason.message.includes('Could not find the table'))) {
                console.warn(`Tabla opcional '${tableName}' no encontrada. La funcionalidad del blog estará limitada. Esto es normal en un setup nuevo.`);
                return []; // Return an empty array to allow the app to function
            }

            // For any other unexpected error, log it properly
            console.error(`Error crítico cargando datos de '${tableName}':`, reason.message || reason);
            return [];
        };

        const postsData = getResultOrEmpty(results[0], 'blog_posts');
        let catsData = getResultOrEmpty(results[1], 'blog_categories');
        const subsData = getResultOrEmpty(results[2], 'blog_subcategories');

        let finalCats = catsData;
        // Seed default category ONLY if the table exists but is empty
        if (results[1].status === 'fulfilled' && catsData.length === 0) {
            try {
                const defaultCat = await db.blog.createCategory({
                    name: 'General',
                    slug: 'general',
                    description: 'Noticias generales de la agrupación'
                });
                finalCats = [defaultCat];
            } catch (seedError: any) {
                console.error("Error al crear categoría por defecto (la tabla existe pero la inserción falló):", seedError.message || seedError);
            }
        }

        setPosts(postsData);
        setCategories(finalCats);
        setSubCategories(subsData);

    } catch (e: any) {
        console.error("Error general al cargar datos del blog:", e.message || e);
    } finally {
        setLoading(false);
    }
  };

  useEffect(() => {
    loadData();
  }, []);

  const addPost = async (post: Omit<BlogPost, 'id' | 'publishDate'>) => {
    try {
        const newPost = await db.blog.create(post);
        setPosts(prev => [newPost, ...prev]);
    } catch (error) {
        console.error("Error creating post:", error);
        throw error;
    }
  };

  const updatePost = async (id: number, updatedFields: Partial<BlogPost>) => {
    try {
        await db.blog.update(id, updatedFields);
        setPosts(prev => prev.map(p => (p.id === id ? { ...p, ...updatedFields } : p)));
    } catch (error) {
        console.error("Error updating post:", error);
        throw error;
    }
  };

  const deletePost = async (id: number) => {
    if(!window.confirm("¿Seguro que deseas eliminar este artículo?")) return;
    try {
        await db.blog.delete(id);
        setPosts(prev => prev.filter(p => p.id !== id));
    } catch (error) {
        console.error("Error deleting post:", error);
    }
  };

  const addCategory = async (cat: Omit<BlogCategory, 'id'>) => {
      try {
          const newCat = await db.blog.createCategory(cat);
          setCategories(prev => [...prev, newCat]);
      } catch (error) {
          console.error("Error adding category:", error);
          throw error;
      }
  };

  const addSubCategory = async (sub: Omit<BlogSubCategory, 'id'>) => {
      try {
          const newSub = await db.blog.createSubCategory(sub);
          setSubCategories(prev => [...prev, newSub]);
      } catch (error) {
          console.error("Error adding subcategory:", error);
          throw error;
      }
  };

  const getPublishedPosts = (categoryId?: number, subCategoryId?: number) => {
    let filtered = posts.filter(p => p.status === BlogPostStatus.PUBLISHED);
    if (categoryId) filtered = filtered.filter(p => p.categoryId === categoryId);
    if (subCategoryId) filtered = filtered.filter(p => p.subCategoryId === subCategoryId);
    return filtered.sort((a, b) => new Date(b.publishDate).getTime() - new Date(a.publishDate).getTime());
  };

  const getPostById = (id: number) => posts.find(p => p.id === id);
  const getPostBySlug = (slug: string) => posts.find(p => p.slug === slug);

  return (
    <BlogContext.Provider value={{ 
        posts, categories, subCategories, loading, 
        addPost, updatePost, deletePost, addCategory, addSubCategory,
        getPublishedPosts, getPostById, getPostBySlug 
    }}>
      {children}
    </BlogContext.Provider>
  );
};

export const useBlog = () => {
  const context = useContext(BlogContext);
  if (!context) throw new Error('useBlog must be used within a BlogProvider');
  return context;
};

import React, { createContext, useContext, useState, useEffect } from 'react';
import { Volunteer, VolunteerStatus, Shift } from '../types';
import { db } from '../services/db';

interface VolunteerContextType {
  volunteers: Volunteer[];
  shifts: Shift[];
  loading: boolean;
  addVolunteer: (vol: Partial<Volunteer>) => Promise<void>;
  updateVolunteerStatus: (id: number, status: VolunteerStatus) => Promise<void>;
  updateVolunteerDetails: (id: number, details: Partial<Volunteer>) => Promise<void>;
  getVolunteerStats: () => { active: number; pending: number; totalHours: number };
  addShift: (shift: Omit<Shift, 'id'>) => Promise<void>;
  updateShift: (id: number, shift: Partial<Shift>) => Promise<void>;
  deleteShift: (id: number) => Promise<void>;
  getShiftsByVolunteer: (volunteerId: number) => Shift[];
}

const VolunteerContext = createContext<VolunteerContextType | undefined>(undefined);

export const VolunteerProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [volunteers, setVolunteers] = useState<Volunteer[]>([]);
  const [shifts, setShifts] = useState<Shift[]>([]);
  const [loading, setLoading] = useState(true);

  // Initial Load from DB
  useEffect(() => {
    const loadData = async () => {
        try {
            const [vols, shfts] = await Promise.all([
                db.volunteers.getAll(),
                db.shifts.getAll()
            ]);
            setVolunteers(vols);
            setShifts(shfts);
        } catch (error) {
            console.error("Failed to load volunteer data", error);
        } finally {
            setLoading(false);
        }
    };
    loadData();
  }, []);

  const addVolunteer = async (volData: Partial<Volunteer>) => {
    const newVol = await db.volunteers.create({
      fullName: volData.fullName || '',
      email: volData.email || '',
      phone: volData.phone || '',
      establishment: volData.establishment || '',
      hospitalUnit: volData.hospitalUnit || undefined,
      location: volData.location || '',
      group: volData.group || undefined,
      motivation: volData.motivation || '',
      status: volData.status || VolunteerStatus.PENDING,
      hoursThisMonth: volData.hoursThisMonth || 0,
      joinDate: new Date().toISOString().split('T')[0]
    } as Omit<Volunteer, 'id'>);

    setVolunteers(prev => [...prev, newVol]);
  };

  const updateVolunteerDetails = async (id: number, details: Partial<Volunteer>) => {
    await db.volunteers.update(id, details);
    setVolunteers(prev => prev.map(v => v.id === id ? { ...v, ...details } : v));
  };

  // REGLA DE NEGOCIO: Validador de traslape de turnos
  const isShiftOverlapping = (shiftToCheck: Partial<Shift>, existingShifts: Shift[]): boolean => {
    const newStart = new Date(`${shiftToCheck.date}T${shiftToCheck.startTime}`).getTime();
    const newEnd = new Date(`${shiftToCheck.date}T${shiftToCheck.endTime}`).getTime();

    if (newStart >= newEnd) {
      throw new Error("La hora de inicio debe ser anterior a la hora de término.");
    }

    const conflictingShift = existingShifts.find(existingShift => {
      // Ignorar el propio turno si se está actualizando
      if (shiftToCheck.id && existingShift.id === shiftToCheck.id) {
        return false;
      }

      // Solo verificar turnos de la misma voluntaria en el mismo día
      if (existingShift.volunteerId === shiftToCheck.volunteerId && existingShift.date === shiftToCheck.date) {
        const oldStart = new Date(`${existingShift.date}T${existingShift.startTime}`).getTime();
        const oldEnd = new Date(`${existingShift.date}T${existingShift.endTime}`).getTime();

        // Lógica de traslape: (StartA < EndB) and (EndA > StartB)
        return newStart < oldEnd && newEnd > oldStart;
      }
      return false;
    });

    return !!conflictingShift;
  };

  // REGLA DE NEGOCIO: Cálculo de horas de un turno
  const calculateShiftHours = (startTime: string, endTime: string): number => {
      const start = new Date(`1970-01-01T${startTime}`);
      const end = new Date(`1970-01-01T${endTime}`);
      const diff = end.getTime() - start.getTime();
      return diff / (1000 * 60 * 60);
  };

  // MANTENIMIENTO DE HORAS DE VOLUNTARIADO
  const adjustVolunteerHours = async (volunteerId: number, hours: number) => {
    const volunteer = volunteers.find(v => v.id === volunteerId);
    if (volunteer) {
        const newTotal = Math.max(0, volunteer.hoursThisMonth + hours); // hours puede ser negativo
        await updateVolunteerDetails(volunteerId, { hoursThisMonth: newTotal });
    }
  };


  const updateVolunteerStatus = async (id: number, status: VolunteerStatus) => {
    await db.volunteers.update(id, { status });
    setVolunteers(prev => prev.map(v => v.id === id ? { ...v, status } : v));
  };


  const getVolunteerStats = () => {
    return {
      active: volunteers.filter(v => v.status === VolunteerStatus.ACTIVE).length,
      pending: volunteers.filter(v => v.status === VolunteerStatus.PENDING).length,
      totalHours: volunteers.reduce((acc, curr) => acc + curr.hoursThisMonth, 0)
    };
  };

  const addShift = async (shift: Omit<Shift, 'id'>) => {
    if (isShiftOverlapping(shift, shifts)) {
      throw new Error("Error de Traslape: La voluntaria ya tiene un turno asignado en ese rango horario.");
    }
    const newShift = await db.shifts.create(shift);
    setShifts(prev => [...prev, newShift]);
  };

  const updateShift = async (id: number, updatedFields: Partial<Shift>) => {
    const originalShift = shifts.find(s => s.id === id);
    if (!originalShift) throw new Error("Turno no encontrado");

    const mergedShift = { ...originalShift, ...updatedFields };

    if (isShiftOverlapping(mergedShift, shifts)) {
      throw new Error("Error de Traslape: El nuevo horario entra en conflicto con otro turno existente.");
    }

    // REGLA DE NEGOCIO: Actualización automática de horas
    if (updatedFields.status && updatedFields.status !== originalShift.status) {
        const shiftHours = calculateShiftHours(originalShift.startTime, originalShift.endTime);

        // Si se marca como completado Y ANTES no lo estaba, sumar horas
        if (updatedFields.status === 'Completado' && originalShift.status !== 'Completado') {
            await adjustVolunteerHours(originalShift.volunteerId, shiftHours);
        }
        // Si se cambia de completado a otro estado, restar horas
        else if (originalShift.status === 'Completado' && updatedFields.status !== 'Completado') {
            await adjustVolunteerHours(originalShift.volunteerId, -shiftHours);
        }
    }

    await db.shifts.update(id, updatedFields);
    setShifts(prev => prev.map(s => s.id === id ? { ...s, ...updatedFields } : s));
  };

  const deleteShift = async (id: number) => {
    try {
      const shiftToDelete = shifts.find(s => s.id === id);
      // Si se elimina un turno que ya estaba completado, se deben restar las horas.
      if (shiftToDelete && shiftToDelete.status === 'Completado') {
          const shiftHours = calculateShiftHours(shiftToDelete.startTime, shiftToDelete.endTime);
          await adjustVolunteerHours(shiftToDelete.volunteerId, -shiftHours);
      }

      await db.shifts.delete(id);
      setShifts(prev => prev.filter(s => s.id !== id));
    } catch (error) {
        console.error("Error al eliminar el turno:", error);
        alert("Ocurrió un error al intentar eliminar el turno. Por favor, inténtelo de nuevo.");
    }
  };

  const getShiftsByVolunteer = (volunteerId: number) => {
    return shifts.filter(s => s.volunteerId === volunteerId).sort((a,b) => a.date.localeCompare(b.date));
  };

  return (
    <VolunteerContext.Provider value={{ 
      volunteers, 
      shifts,
      loading,
      addVolunteer, 
      updateVolunteerStatus, 
      updateVolunteerDetails,
      getVolunteerStats,
      addShift,
      updateShift,
      deleteShift,
      getShiftsByVolunteer
    }}>
      {children}
    </VolunteerContext.Provider>
  );
};

export const useVolunteer = () => {
  const context = useContext(VolunteerContext);
  if (!context) throw new Error('useVolunteer must be used within a VolunteerProvider');
  return context;
};

