export const AdminBlog: React.FC<AdminBlogProps> = ({ onBack }) => {
  const { 
    posts, categories, subCategories, addPost, updatePost, deletePost, 
    addCategory, deleteCategory, addSubCategory, deleteSubCategory
  } = useBlog();

  const [activeView, setActiveView] = useState<'posts' | 'categories' | 'editor'>('posts');
  const [editingPostId, setEditingPostId] = useState<number | null>(null);
  const [isSaving, setIsSaving] = useState(false);

  const [postMeta, setPostMeta] = useState({ title: '', slug: '', excerpt: '', coverImage: '', author: 'Coordinación Vida y Esperanza', status: BlogPostStatus.DRAFT, categoryId: undefined as number | undefined, subCategoryId: undefined as number | undefined, tags: '' });
  const [blocks, setBlocks] = useState<BlogBlock[]>([]);
  const [newCatName, setNewCatName] = useState('');
  const [newSubCat, setNewSubCat] = useState({ name: '', categoryId: 0 });

  const processFile = (file: File): Promise<string> => {
    return new Promise((resolve, reject) => { if (file.size > 2 * 1024 * 1024) { alert("Imagen demasiado grande (máx 2MB)."); return reject("File too large"); } const reader = new FileReader(); reader.onload = () => resolve(reader.result as string); reader.onerror = reject; reader.readAsDataURL(file); });
  };

  // FIX: The `await` expression was used inside a non-async callback. It has been moved to the top level of the async function.
  const handleCoverUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files?.[0]) {
      const coverImage = await processFile(e.target.files[0]);
      setPostMeta(prev => ({ ...prev, coverImage }));
    }
  };
  const handleBlockImageUpload = async (id: string, e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files?.[0]) {
      const mediaUrl = await processFile(e.target.files[0]);
      updateBlock(id, { mediaUrl });
    }
  };

  const generateSlug = (text: string) => text.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)+/g, '');

  const handleEditPost = (post: BlogPost) => {
    setPostMeta({ title: post.title, slug: post.slug, excerpt: post.excerpt, coverImage: post.coverImage, author: post.author, status: post.status, categoryId: post.categoryId, subCategoryId: post.subCategoryId, tags: post.tags.join(', ') });
    try { setBlocks(JSON.parse(post.content)); } catch (e) { setBlocks([{ id: Date.now().toString(), type: 'text', content: post.content }]); }
    setEditingPostId(post.id); setActiveView('editor');
  };

  const handleCreatePost = () => {
    setPostMeta({ title: '', slug: '', excerpt: '', coverImage: '', author: 'Coordinación Vida y Esperanza', status: BlogPostStatus.DRAFT, categoryId: categories[0]?.id, subCategoryId: undefined, tags: '' });
    setBlocks([{ id: Date.now().toString(), type: 'text', content: '' }]);
    setEditingPostId(null); setActiveView('editor');
  };

  const addBlock = (type: BlogBlockType) => setBlocks([...blocks, { id: Math.random().toString(36).substr(2, 9), type, content: '', mediaUrl: '', caption: '', linkUrl: '', buttonStyle: 'primary' }]);
  const updateBlock = (id: string, updates: Partial<BlogBlock>) => setBlocks(blocks.map(b => b.id === id ? { ...b, ...updates } : b));
  const deleteBlock = (id: string) => setBlocks(blocks.filter(b => b.id !== id));

  const moveBlock = (index: number, direction: 'up' | 'down') => {
    const newBlocks = [...blocks]; const target = direction === 'up' ? index - 1 : index + 1;
    if (target < 0 || target >= newBlocks.length) return;
    [newBlocks[index], newBlocks[target]] = [newBlocks[target], newBlocks[index]]; setBlocks(newBlocks);
  };

  const handleSavePost = async (e: React.FormEvent) => {
    e.preventDefault(); if (!postMeta.title) return alert("El título es obligatorio");
    setIsSaving(true);
    const finalData = { title: postMeta.title, slug: postMeta.slug || generateSlug(postMeta.title), excerpt: postMeta.excerpt, content: JSON.stringify(blocks), coverImage: postMeta.coverImage, author: postMeta.author, status: postMeta.status, tags: postMeta.tags.split(',').map(t => t.trim()).filter(Boolean), categoryId: postMeta.categoryId, subCategoryId: postMeta.subCategoryId };
    try { if (editingPostId) { await updatePost(editingPostId, finalData); } else { await addPost(finalData); } setActiveView('posts'); } 
    catch (err) { alert("Error al guardar: " + err); } finally { setIsSaving(false); }
  };

  const handleAddCategory = async () => { if (!newCatName) return; await addCategory({ name: newCatName, slug: generateSlug(newCatName) }); setNewCatName(''); };
  const handleAddSubCategory = async () => { if (!newSubCat.name || !newSubCat.categoryId) return; await addSubCategory({ name: newSubCat.name, slug: generateSlug(newSubCat.name), categoryId: newSubCat.categoryId }); setNewSubCat({ name: '', categoryId: 0 }); };

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col md:flex-row">
      <aside className="w-full md:w-64 bg-emerald-900 text-white p-6 flex-shrink-0">
        <div className="flex items-center gap-3 mb-10 pb-4 border-b border-white/10"><Layout className="text-emerald-400" /><h1 className="font-bold text-lg">Panel de Blog</h1></div>
        <nav className="space-y-1">
            <button onClick={() => setActiveView('posts')} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-medium transition ${activeView === 'posts' ? 'bg-white/10 text-white' : 'text-emerald-100 hover:bg-white/5'}`}><FileText size={18} /> Entradas</button>
            <button onClick={() => setActiveView('categories')} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-medium transition ${activeView === 'categories' ? 'bg-white/10 text-white' : 'text-emerald-100 hover:bg-white/5'}`}><Layers size={18} /> Categorías</button>
        </nav>
      </aside>

      <main className="flex-1 p-6 md:p-10 overflow-y-auto">
        {activeView === 'posts' && (
            <div className="animate-fadeIn">
                <div className="flex justify-between items-center mb-10">
                    <div><h2 className="text-3xl font-extrabold text-gray-900">Entradas del Blog</h2><p className="text-gray-500">Gestiona todos los artículos y noticias.</p></div>
                    <button onClick={handleCreatePost} className="bg-emerald-600 text-white px-6 py-3 rounded-2xl font-bold flex items-center gap-2 shadow-xl shadow-emerald-100 hover:bg-emerald-700 transition"><Plus size={20} /> Crear Nueva Entrada</button>
                </div>
