  const [newSubCat, setNewSubCat] = useState({ name: '', categoryId: 0 });

  const processFile = (file: File): Promise<string> => {
    return new Promise((resolve, reject) => { if (file.size > 2 * 1024 * 1024) { alert("Imagen demasiado grande (máx 2MB)."); return reject("File too large"); } const reader = new FileReader(); reader.onload = () => resolve(reader.result as string); reader.onerror = reject; reader.readAsDataURL(file); });
  };

  const handleCoverUpload = async (e: React.ChangeEvent<HTMLInputElement>) => { if (e.target.files?.[0]) { const data = await processFile(e.target.files[0]); setPostMeta(prev => ({ ...prev, coverImage: data })); } };
  const handleBlockImageUpload = async (id: string, e: React.ChangeEvent<HTMLInputElement>) => { if (e.target.files?.[0]) { const data = await processFile(e.target.files[0]); updateBlock(id, { mediaUrl: data }); } };

  const generateSlug = (text: string) => text.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)+/g, '');

  const handleEditPost = (post: BlogPost) => {
    setPostMeta({ title: post.title, slug: post.slug, excerpt: post.excerpt, coverImage: post.coverImage, author: post.author, status: post.status, categoryId: post.categoryId, subCategoryId: post.subCategoryId, tags: post.tags.join(', ') });
    setBlocks(post.blocks || [{ id: Date.now().toString(), type: 'text', content: '' }]);
    setEditingPostId(post.id); 
    setActiveView('editor');
  };

  const handleCreatePost = () => {
    setPostMeta({ title: '', slug: '', excerpt: '', coverImage: '', author: 'Coordinación Vida y Esperanza', status: BlogPostStatus.DRAFT, categoryId: categories[0]?.id, subCategoryId: undefined, tags: '' });
    setBlocks([{ id: Date.now().toString(), type: 'text', content: '' }]);
    setEditingPostId(null); setActiveView('editor');
  };

  const addBlock = (type: BlogBlockType) => setBlocks([...blocks, { id: Math.random().toString(36).substr(2, 9), type, content: '', mediaUrl: '', caption: '', linkUrl: '', buttonStyle: 'primary' }]);
  const updateBlock = (id: string, updates: Partial<BlogBlock>) => setBlocks(blocks.map(b => b.id === id ? { ...b, ...updates } : b));
  const deleteBlock = (id: string) => setBlocks(blocks.filter(b => b.id !== id));

  const moveBlock = (index: number, direction: 'up' | 'down') => {
    const newBlocks = [...blocks]; const target = direction === 'up' ? index - 1 : index + 1;
    if (target < 0 || target >= newBlocks.length) return;
    [newBlocks[index], newBlocks[target]] = [newBlocks[target], newBlocks[index]]; setBlocks(newBlocks);
  };

  const handleSavePost = async (e: React.FormEvent) => {
    e.preventDefault(); if (!postMeta.title) return alert("El título es obligatorio");
    setIsSaving(true);
    const postData = { title: postMeta.title, slug: postMeta.slug || generateSlug(postMeta.title), excerpt: postMeta.excerpt, coverImage: postMeta.coverImage, author: postMeta.author, status: postMeta.status, tags: postMeta.tags.split(',').map(t => t.trim()).filter(Boolean), categoryId: postMeta.categoryId, subCategoryId: postMeta.subCategoryId };
    try { if (editingPostId) { await updatePost(editingPostId, postData, blocks); } else { await addPost(postData, blocks); } setActiveView('posts'); } 
    catch (err: any) { alert("Error al guardar: " + (err.message || err)); } finally { setIsSaving(false); }
  };

  const handleAddCategory = async () => { if (!newCatName) return; try { await addCategory({ name: newCatName, slug: generateSlug(newCatName) }); setNewCatName(''); } catch (e: any) { alert(`Error al crear categoría: ${e.message}`); } };
  const handleAddSubCategory = async () => { if (!newSubCat.name || !newSubCat.categoryId) return; try { await addSubCategory({ name: newSubCat.name, slug: generateSlug(newSubCat.name), categoryId: newSubCat.categoryId }); setNewSubCat({ name: '', categoryId: 0 }); } catch (e: any) { alert(`Error al crear subcategoría: ${e.message}`); } };

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col md:flex-row">
      <aside className="w-full md:w-64 bg-emerald-900 text-white p-6 flex-shrink-0">
        <div className="flex items-center gap-3 mb-10 pb-4 border-b border-white/10"><Layout className="text-emerald-400" /><h1 className="font-bold text-lg">Panel de Blog</h1></div>
        <nav className="space-y-1">
            <button onClick={() => setActiveView('posts')} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-medium transition ${activeView === 'posts' ? 'bg-white/10 text-white' : 'text-emerald-100 hover:bg-white/5'}`}><FileText size={18} /> Entradas</button>
            <button onClick={() => setActiveView('categories')} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-medium transition ${activeView === 'categories' ? 'bg-white/10 text-white' : 'text-emerald-100 hover:bg-white/5'}`}><Layers size={18} /> Categorías</button>
        </nav>
      </aside>

      <main className="flex-1 p-6 md:p-10 overflow-y-auto">
        {activeView === 'posts' && (
            <div className="animate-fadeIn">
                <div className="flex justify-between items-center mb-10">
                    <div><h2 className="text-3xl font-extrabold text-gray-900">Entradas del Blog</h2><p className="text-gray-500">Gestiona todos los artículos y noticias.</p></div>
                    <button onClick={handleCreatePost} className="bg-emerald-600 text-white px-6 py-3 rounded-2xl font-bold flex items-center gap-2 shadow-xl shadow-emerald-100 hover:bg-emerald-700 transition"><Plus size={20} /> Crear Nueva Entrada</button>
                </div>
                <div className="grid gap-4">{posts.map(post => (<div key={post.id} className="bg-white p-4 rounded-3xl shadow-sm border border-gray-100 flex items-center gap-4 hover:shadow-lg transition group"><div className="w-20 h-20 bg-gray-100 rounded-2xl overflow-hidden flex-shrink-0"><img src={post.coverImage || 'https://i.imgur.com/k2yKx60.jpg'} className="w-full h-full object-cover" /></div><div className="flex-1"><div className="flex items-center gap-2 mb-1"><h3 className="font-bold text-gray-900 group-hover:text-emerald-600">{post.title}</h3><span className={`text-[10px] px-2 py-0.5 rounded-full font-bold uppercase border ${post.status === 'Publicado' ? 'bg-emerald-50 text-emerald-700 border-emerald-100' : 'bg-yellow-50 text-yellow-700 border-yellow-100'}`}>{post.status}</span></div><div className="flex items-center gap-4 text-xs text-gray-400"><span className="flex items-center gap-1"><FolderPlus size={12}/> {categories.find(c => c.id === post.categoryId)?.name || 'S/C'}</span><span>{new Date(post.publishDate).toLocaleDateString()}</span></div></div><div className="flex items-center gap-2 opacity-0 group-hover:opacity-100"><button onClick={() => handleEditPost(post)} className="p-2 bg-gray-50 text-emerald-600 rounded-xl hover:bg-emerald-100"><Edit2 size={18}/></button><button onClick={() => deletePost(post.id)} className="p-2 bg-gray-50 text-red-600 rounded-xl hover:bg-red-100"><Trash2 size={18}/></button></div></div>))}{posts.length === 0 && <p className="text-center py-10 text-gray-400">No hay entradas aún.</p>}</div>
            </div>
        )}
        {activeView === 'categories' && (
            <div className="animate-fadeIn">
                 <h2 className="text-3xl font-extrabold text-gray-900 mb-2">Categorías y Subcategorías</h2><p className="text-gray-500 mb-10">Organiza tus contenidos.</p>
                 <div className="grid lg:grid-cols-2 gap-10">
                    <div className="bg-white p-8 rounded-3xl shadow-sm border border-gray-100"><h3 className="font-bold text-gray-800 mb-6 flex items-center gap-2 text-lg"><Layers size={20} className="text-emerald-600"/> Nueva Categoría</h3><div className="space-y-4"><input type="text" placeholder="Nombre (ej: Salud Hospitalaria)" value={newCatName} onChange={e => setNewCatName(e.target.value)} className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-2xl outline-none focus:ring-2 focus:ring-emerald-500" /><button onClick={handleAddCategory} className="w-full bg-emerald-600 text-white py-3 rounded-2xl font-bold shadow-lg shadow-emerald-100">Crear Categoría</button></div><div className="mt-8 space-y-3"><p className="text-xs font-bold text-gray-400 uppercase tracking-widest">Existentes</p>{categories.map(cat => (<div key={cat.id} className="flex items-center justify-between p-3 bg-gray-50 rounded-xl border border-gray-100 group"><div><span className="font-bold text-gray-700">{cat.name}</span><p className="text-[10px] text-gray-400 font-mono">/{cat.slug}</p></div><button onClick={() => deleteCategory(cat.id)} className="text-red-400 opacity-0 group-hover:opacity-100"><X size={16}/></button></div>))}</div></div>
                    <div className="bg-white p-8 rounded-3xl shadow-sm border border-gray-100"><h3 className="font-bold text-gray-800 mb-6 flex items-center gap-2 text-lg"><FolderPlus size={20} className="text-emerald-600"/> Nueva Subcategoría</h3><div className="space-y-4"><select value={newSubCat.categoryId} onChange={e => setNewSubCat({...newSubCat, categoryId: Number(e.target.value)})} className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-2xl outline-none text-sm focus:ring-2 focus:ring-emerald-500"><option value={0}>Selecciona Categoría Padre</option>{categories.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}</select><input type="text" placeholder="Nombre (ej: Pediatría)" value={newSubCat.name} onChange={e => setNewSubCat({...newSubCat, name: e.target.value})} className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-2xl outline-none focus:ring-2 focus:ring-emerald-500" /><button onClick={handleAddSubCategory} className="w-full bg-emerald-600 text-white py-3 rounded-2xl font-bold shadow-lg shadow-emerald-100">Vincular</button></div><div className="mt-8 space-y-3"><p className="text-xs font-bold text-gray-400 uppercase tracking-widest">Jerarquía Actual</p>{subCategories.map(sub => (<div key={sub.id} className="flex items-center justify-between p-3 bg-emerald-50/50 rounded-xl border border-emerald-100 group"><div><span className="text-[10px] text-emerald-600 font-bold uppercase">{categories.find(c => c.id === sub.categoryId)?.name}</span><p className="font-bold text-gray-700">{sub.name}</p></div><button onClick={() => deleteSubCategory(sub.id)} className="text-red-400 opacity-0 group-hover:opacity-100"><X size={16}/></button></div>))}</div></div>
                 </div>
            </div>
        )}
        {activeView === 'editor' && (
            <div className="animate-fadeIn"><form onSubmit={handleSavePost} className="max-w-6xl mx-auto grid lg:grid-cols-12 gap-8 pb-20">
                <div className="lg:col-span-12 flex justify-between items-center mb-4"><button type="button" onClick={() => setActiveView('posts')} className="flex items-center gap-2 text-gray-500 hover:text-emerald-600 font-bold"><ArrowLeft size={20}/> Volver</button><div className="flex gap-3"><button type="submit" disabled={isSaving} className="bg-emerald-600 text-white px-10 py-4 rounded-2xl font-black text-sm uppercase tracking-widest flex items-center gap-3 shadow-xl shadow-emerald-100 disabled:opacity-50">{isSaving ? <Loader2 className="animate-spin" size={20}/> : <Save size={20}/>}{isSaving ? 'Guardando...' : 'Guardar'}</button></div></div>
                <div className="lg:col-span-8 space-y-6"><div className="bg-white p-8 md:p-12 rounded-[40px] shadow-xl border border-gray-100"><input type="text" placeholder="Título del Artículo..." value={postMeta.title} onChange={e => setPostMeta({...postMeta, title: e.target.value, slug: generateSlug(e.target.value)})} className="w-full text-4xl font-black text-gray-900 border-none outline-none mb-6 placeholder:text-gray-200" /><textarea placeholder="Escribe un resumen o bajada que invite a leer..." value={postMeta.excerpt} onChange={e => setPostMeta({...postMeta, excerpt: e.target.value})} className="w-full text-lg text-gray-500 border-none outline-none resize-none mb-10 italic border-l-4 border-emerald-100 pl-4" rows={2} /><div className="space-y-4">{blocks.map((block, idx) => <BlockEditor key={block.id} block={block} index={idx} total={blocks.length} onUpdate={updateBlock} onMove={moveBlock} onDelete={deleteBlock} onImageUpload={handleBlockImageUpload} />)}</div><div className="mt-16 pt-16 border-t border-dashed border-gray-200"><p className="text-center text-[10px] font-black text-gray-400 uppercase tracking-[0.2em] mb-8">Añadir Bloque</p><div className="flex flex-wrap justify-center gap-4"><button type="button" onClick={() => addBlock('text')} className="flex items-center gap-3 px-8 py-4 bg-gray-50 text-gray-700 rounded-2xl hover:bg-emerald-600 hover:text-white font-black text-xs uppercase tracking-widest shadow-sm"><Type size={18}/> Párrafo</button><button type="button" onClick={() => addBlock('heading')} className="flex items-center gap-3 px-8 py-4 bg-gray-50 text-gray-700 rounded-2xl hover:bg-emerald-600 hover:text-white font-black text-xs uppercase tracking-widest shadow-sm"><ChevronRight size={18}/> Subtítulo</button><button type="button" onClick={() => addBlock('image')} className="flex items-center gap-3 px-8 py-4 bg-gray-50 text-gray-700 rounded-2xl hover:bg-emerald-600 hover:text-white font-black text-xs uppercase tracking-widest shadow-sm"><ImageIcon size={18}/> Imagen</button><button type="button" onClick={() => addBlock('button')} className="flex items-center gap-3 px-8 py-4 bg-gray-50 text-gray-700 rounded-2xl hover:bg-emerald-600 hover:text-white font-black text-xs uppercase tracking-widest shadow-sm"><MousePointer2 size={18}/> Botón</button></div></div></div></div>
                <div className="lg:col-span-4"><div className="sticky top-10 bg-white p-8 rounded-3xl shadow-lg border border-gray-100 space-y-6">
                    <h3 className="font-bold text-gray-800 flex items-center gap-2"><Settings size={20} className="text-emerald-600"/> Publicación</h3>
                    <div><label className="block text-xs font-bold text-gray-400 uppercase mb-2">Estado</label><select value={postMeta.status} onChange={e => setPostMeta({...postMeta, status: e.target.value as BlogPostStatus})} className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-xl outline-none text-sm focus:ring-2 focus:ring-emerald-500"><option value="Borrador">Borrador</option><option value="Publicado">Publicado</option></select></div>
                    <div><label className="block text-xs font-bold text-gray-400 uppercase mb-2">Imagen de Portada</label><div className="h-40 bg-gray-100 rounded-2xl overflow-hidden flex items-center justify-center border-2 border-dashed border-gray-300 relative group"><label htmlFor="cover-upload" className="absolute inset-0 bg-black/50 text-white flex flex-col items-center justify-center cursor-pointer opacity-0 group-hover:opacity-100 transition-opacity"><Upload size={24} className="mb-2"/> <span className="text-xs font-bold">Cambiar Imagen</span></label>{postMeta.coverImage ? <img src={postMeta.coverImage} className="w-full h-full object-cover"/> : <ImageIcon size={32} className="text-gray-300"/>}</div><input id="cover-upload" type="file" className="hidden" accept="image/*" onChange={handleCoverUpload}/></div>
                    <div><label className="block text-xs font-bold text-gray-400 uppercase mb-2">Categoría</label><select value={postMeta.categoryId} onChange={e => setPostMeta({...postMeta, categoryId: Number(e.target.value), subCategoryId: undefined})} className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-xl outline-none text-sm focus:ring-2 focus:ring-emerald-500"><option>-- Sin Asignar --</option>{categories.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}</select></div>
                    {postMeta.categoryId && subCategories.filter(s => s.categoryId === postMeta.categoryId).length > 0 && <div><label className="block text-xs font-bold text-gray-400 uppercase mb-2">Subcategoría</label><select value={postMeta.subCategoryId} onChange={e => setPostMeta({...postMeta, subCategoryId: Number(e.target.value)})} className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-xl outline-none text-sm focus:ring-2 focus:ring-emerald-500"><option>-- Sin Asignar --</option>{subCategories.filter(s => s.categoryId === postMeta.categoryId).map(s => <option key={s.id} value={s.id}>{s.name}</option>)}</select></div>}
                    <div><label className="block text-xs font-bold text-gray-400 uppercase mb-2">Etiquetas</label><input type="text" placeholder="salud, niños, campaña" value={postMeta.tags} onChange={e => setPostMeta({...postMeta, tags: e.target.value})} className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-xl outline-none text-sm focus:ring-2 focus:ring-emerald-500"/></div>
                </div></div>
            </form></div>
        )}
      </main>
    </div>
  );
};

import React from 'react';
import { ArrowLeft, Calendar, User, Tag, Share2, MousePointer2 } from 'lucide-react';
import { useBlog } from '../context/BlogContext';
import { BlogBlock } from '../types';

interface BlogPostPageProps {
  postId: number;
  onBack: () => void;
}

export const BlogPostPage: React.FC<BlogPostPageProps> = ({ postId, onBack }) => {
  const { getPostById, categories } = useBlog();
  const post = getPostById(postId);

  if (!post) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-white">
        <div className="text-center">
          <p className="text-gray-500 mb-4 font-bold">Publicación no encontrada.</p>
          <button onClick={onBack} className="bg-emerald-600 text-white px-8 py-3 rounded-2xl font-bold">Volver al Blog</button>
        </div>
      </div>
    );
  }

  const blocks: BlogBlock[] = post.blocks || [];
  const category = categories.find(c => c.id === post.categoryId);

  return (
    <article className="bg-white min-h-screen font-sans">
      {/* Hero Header Mobile Optimized */}
      <div className="relative h-[60vh] md:h-[70vh] w-full bg-emerald-950 overflow-hidden">
        <img 
          src={post.coverImage} 
          alt={post.title} 
          className="w-full h-full object-cover opacity-60 transition-transform duration-[10s] hover:scale-110"
        />
        <div className="absolute inset-0 bg-gradient-to-t from-emerald-950 via-emerald-950/20 to-transparent" />

        <div className="absolute top-6 left-6 z-20">
             <button 
                onClick={onBack} 
                className="flex items-center gap-2 text-white font-bold bg-white/10 backdrop-blur-xl px-6 py-3 rounded-2xl hover:bg-white/20 transition active:scale-95"
            >
                <ArrowLeft size={20} /> <span className="hidden sm:inline">Volver</span>
            </button>
        </div>

        <div className="absolute bottom-0 left-0 w-full p-8 md:p-20 text-white max-w-6xl mx-auto">
            <div className="flex flex-wrap gap-2 mb-6">
                <span className="bg-emerald-500 text-white text-[10px] font-black px-4 py-2 rounded-xl uppercase tracking-widest shadow-xl">
                    {category?.name || 'General'}
                </span>
            </div>
            <h1 className="text-4xl md:text-6xl font-black leading-[1.1] mb-8 drop-shadow-xl max-w-4xl">
                {post.title}
            </h1>
            <div className="flex flex-wrap items-center gap-6 text-sm md:text-base text-emerald-100/80 font-medium">
                <span className="flex items-center gap-2"><div className="w-8 h-8 bg-emerald-800 rounded-full flex items-center justify-center font-bold">{post.author.charAt(0)}</div> {post.author}</span>
                <span className="flex items-center gap-2 bg-white/10 px-3 py-1.5 rounded-xl"><Calendar size={18}/> {new Date(post.publishDate).toLocaleDateString('es-ES', { day: 'numeric', month: 'long', year: 'numeric' })}</span>
            </div>
        </div>
      </div>

      {/* Content Renderer Mobile-First */}
      <div className="max-w-3xl mx-auto px-6 py-12 md:py-24">

        {/* Render Blocks */}
        <div className="space-y-12">
            {blocks.map((block) => (
                <div key={block.id} className="animate-fadeIn">
                    {block.type === 'text' && (
                        <div 
                            className="prose prose-emerald prose-lg md:prose-xl max-w-none text-gray-700 leading-relaxed font-serif"
                            dangerouslySetInnerHTML={{ __html: block.content }}
                        />
                    )}
                    {block.type === 'heading' && (
                        <h2 className="text-2xl md:text-3xl font-black text-gray-900 leading-tight">
                            {block.content}
                        </h2>
                    )}
                    {block.type === 'image' && (
                        <figure className="my-10">
                            <div className="rounded-[40px] overflow-hidden shadow-2xl border border-gray-100">
                                <img src={block.mediaUrl} alt={block.caption} className="w-full object-cover" />
                            </div>
                            {block.caption && (
                                <figcaption className="text-center text-sm text-gray-400 mt-4 font-medium italic">
                                    {block.caption}
                                </figcaption>
                            )}
                        </figure>
                    )}
                    {block.type === 'button' && (
                        <div className="flex justify-center my-8">
                            <a 
                                href={block.linkUrl}
                                target="_blank"
                                rel="noopener noreferrer"
                                className={`px-10 py-5 rounded-[20px] font-black text-sm uppercase tracking-widest transition-all shadow-xl active:scale-95 flex items-center gap-3 ${
                                    block.buttonStyle === 'primary' 
                                    ? 'bg-emerald-600 text-white shadow-emerald-100 hover:bg-emerald-700' 
                                    : 'border-2 border-emerald-600 text-emerald-600 hover:bg-emerald-50'
                                }`}
                            >
                                <MousePointer2 size={20}/>
                                {block.content}
                            </a>
                        </div>
                    )}
                    {block.type === 'spacer' && <div className="h-12 w-full"></div>}
                </div>
            ))}
        </div>

        {/* Footer Meta & Share */}
        <div className="mt-24 pt-10 border-t border-gray-100">
            <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6">
                <div className="flex flex-wrap gap-2">
                    <Tag className="text-emerald-500 mr-2" size={20} />
                    {post.tags.map(tag => (
                        <span key={tag} className="text-xs font-bold text-gray-400 bg-gray-50 px-3 py-1.5 rounded-xl hover:text-emerald-600 hover:bg-emerald-50 transition-colors cursor-pointer">
                            #{tag}
                        </span>
                    ))}
                </div>
                <button 
                    onClick={() => {
                        navigator.share?.({ title: post.title, url: window.location.href });
                    }}
                    className="flex items-center gap-3 bg-gray-50 text-gray-600 font-bold px-8 py-4 rounded-2xl hover:bg-emerald-600 hover:text-white transition-all shadow-sm active:scale-95"
                >
                    <Share2 size={20} /> Compartir
                </button>
            </div>
        </div>
      </div>

      {/* Suggested Article Hint */}
      <div className="bg-emerald-50 py-20 px-6">
          <div className="max-w-3xl mx-auto text-center">
              <h3 className="text-2xl font-black text-emerald-900 mb-4">¿Te inspiró este artículo?</h3>
              <p className="text-emerald-800/70 mb-10 font-medium">Juntas damos vida y acompañamos la esperanza. Únete hoy mismo.</p>
              <div className="flex flex-col sm:flex-row justify-center gap-4">
                  <button onClick={() => window.location.hash = 'volunteer'} className="bg-emerald-600 text-white px-10 py-5 rounded-2xl font-black shadow-xl shadow-emerald-900/10 hover:bg-emerald-700 transition">Quiero Ser Voluntaria</button>
                  <button onClick={() => window.location.hash = 'donate'} className="bg-white text-emerald-600 px-10 py-5 rounded-2xl font-black shadow-xl shadow-emerald-900/5 hover:bg-gray-50 transition border border-emerald-100">Hacer una Donación</button>
              </div>
          </div>
      </div>
    </article>
  );
};

import { createClient, SupabaseClient } from '@supabase/supabase-js';

// --- CAPA DE SEGURIDAD: CONSTANTES DE RESPALDO ---
const FALLBACK_URL = ''; 
const FALLBACK_KEY = ''; 

const SUPABASE_URL_KEY = 'vidayesperanza_supabase_url';
const SUPABASE_ANON_KEY_KEY = 'vidayesperanza_supabase_key';

export const getStoredCredentials = () => {
    const url = localStorage.getItem(SUPABASE_URL_KEY)?.trim() || FALLBACK_URL;
    const key = localStorage.getItem(SUPABASE_ANON_KEY_KEY)?.trim() || FALLBACK_KEY;
    return { url: url || null, key: key || null };
};

export const setStoredCredentials = (url: string, key: string) => {
    const cleanUrl = url.trim().replace(/\/$/, ""); 
    const cleanKey = key.trim();

    if (!cleanUrl.startsWith('http')) {
        throw new Error("La URL debe comenzar con http:// o https://");
    }

    localStorage.setItem(SUPABASE_URL_KEY, cleanUrl);
    localStorage.setItem(SUPABASE_ANON_KEY_KEY, cleanKey);
    // Dispara un evento para que otras pestañas (como App.tsx) puedan reaccionar
    window.dispatchEvent(new Event('storage'));
};

export const clearCredentials = () => {
    localStorage.removeItem(SUPABASE_URL_KEY);
    localStorage.removeItem(SUPABASE_ANON_KEY_KEY);
    // Dispara un evento para que otras pestañas reaccionen al logout de credenciales
    window.dispatchEvent(new Event('storage'));
};

// Instancia interna para el Singleton
let internalInstance: SupabaseClient | null = null;
let internalUrl: string | null = null;

export const getSupabase = (): SupabaseClient | null => {
    const creds = getStoredCredentials();
    if (!creds.url || !creds.key) {
        internalInstance = null;
        internalUrl = null;
        return null;
    }

    // Si ya existe instancia y la URL coincide, la reutilizamos
    if (internalInstance && internalUrl === creds.url) {
        return internalInstance;
    }

    // Si no hay instancia o cambió la URL, creamos una nueva
    try {
        internalInstance = createClient(creds.url, creds.key, {
            auth: {
                persistSession: true,
                autoRefreshToken: true
            }
        });
        internalUrl = creds.url;
        return internalInstance;
    } catch (e) {
        console.error("Critical Connection Error:", e);
        internalInstance = null;
        internalUrl = null;
        return null;
    }
};

/**
 * Función para probar una conexión a Supabase con credenciales temporales.
 * No guarda nada, solo valida que la conexión es posible.
 */
export const testSupabaseConnection = async (url: string, key: string): Promise<{ ok: boolean; error?: string }> => {
    try {
        const cleanUrl = url.trim().replace(/\/$/, ""); 
        const cleanKey = key.trim();

        if (!cleanUrl || !cleanKey) {
            return { ok: false, error: "La URL y la Clave API no pueden estar vacías." };
        }

        const testClient = createClient(cleanUrl, cleanKey);

        // Intentamos una consulta simple. Si la tabla 'settings' no es pública, fallará.
        // Pero el tipo de error nos dirá si es un problema de autenticación o de otro tipo.
        const { error } = await testClient.from('settings').select('key').limit(1);

        if (error && (error.message.includes('JWT') || error.message.includes('API key'))) {
            return { ok: false, error: "La clave API (anon key) parece ser inválida." };
        }

        // Si hay otro error, podría ser la URL, la red o que la tabla no existe (lo cual es un problema de setup, no de conexión)
        // No mostraremos errores de "tabla no existe" aquí, sino que lo consideraremos una conexión exitosa a nivel de red/auth.
        if (error && !error.message.includes('relation "public.settings" does not exist')) {
            return { ok: false, error: `Fallo la conexión: ${error.message}. Revisa la URL y tu conexión a internet.` };
        }

        return { ok: true };
    } catch (e: any) {
        return { ok: false, error: `Error de conexión: ${e.message}` };
    }
};

